;

-- <<< END section 3: supabase/migrations/20260909210000_phase3_live_match_engine.sql <<<

-- >>> BEGIN section 4: supabase/migrations/20260910120000_phase4_read_aggregates.sql >>>
SELECT '4 / 10: supabase/migrations/20260910120000_phase4_read_aggregates.sql' AS kicklive_sql_section;

-- ============================================================================
--  KICKLIVE · Phase 4 — read aggregates
--  20260910120000_phase4_read_aggregates.sql
--
--  Why this file exists (docs/PHASE4_DATA_ARCHITECTURE.md F-05, F-06):
--  the league table was computed in the browser from an unbounded read of every match in a competition, in
--  three places, with three rules; and the clubs page counted squad sizes by fetching one row per player in
--  the league. Neither answer needs the rows: both are a grouped aggregate Postgres can do in one pass and
--  return as ~20 rows. This is the only schema change in the phase, and it is additive — no drop, no alter
--  of an existing column, no rewrite of history.
--
--  Both functions are SECURITY **INVOKER**, deliberately. A read aggregate has no business seeing rows the
--  caller cannot see: it is here to compute an answer near the data, not to widen what anyone may read. RLS
--  on `matches`, `players` and `teams` therefore still decides which rows enter the aggregate, which is why
--  an anonymous visitor and a signed-in admin get the same public table and no more.
--
--  How to run it: `supabase db push`, or paste the whole file into the dashboard SQL editor. It opens with
--  `begin;` and closes with `commit;` like the other two files here, so an error mid-way rolls back rather
--  than leaving one function created and the next not. The verification block raises, which is what makes
--  that rollback the outcome you see instead of a silent partial state.
--
--  To watch it fail safely first: `psql -1 -f <this file> --single-transaction -v ON_ERROR_STOP=1`.
-- ============================================================================

begin;

-- ── 1. one predicate: which statuses count as a result ──────────────────────────────────────
--
--  `matches.status`'s CHECK list (KICKLIVE_FINAL_SCHEMA.sql §3.6) admits 'full_time' and 'completed'.
--  'finished' is not in it: the superseded `MatchControlComplete` used to write it and the CHECK rejected
--  the row, but a project created from an older schema dump may still hold one. Tolerating it here — and
--  only here, in the one predicate every reader shares — keeps the aggregate agreeing with the browser rule
--  in `src/lib/data/standings.ts` instead of quietly disagreeing with it. `tests/unit/phase4-data.test.ts`
--  pins the two against each other, so they cannot drift apart silently.
create or replace function kicklive_is_final_status(p_status text)
returns boolean
language sql
immutable
set search_path = public, pg_temp
as $$
  select p_status in ('full_time', 'completed', 'finished');
$$;

comment on function kicklive_is_final_status(text) is
  'The single definition of "this match is a result", shared by the standings aggregate and pinned against src/lib/data/standings.ts.';

-- ── 2. the league table, computed where the rows are ─────────────────────────────────────────
--
--  Shape mirrors `StandingRow` in `src/lib/data/standings.ts`, because the client falls back to that rule
--  when this function is not deployed and the two must be interchangeable (same fields, same tie-breaks):
--  points, then goal difference, then goals for, then name. `form` is chronological (`["W","D"]` = won then
--  drew); `recentForm()` on the client shows the last five, newest first.
create or replace function kicklive_competition_standings(
  p_competition_id integer,
  out team_id         integer,
  out name            text,
  out short_name      text,
  out primary_color   text,
  out secondary_color text,
  out played          integer,
  out won             integer,
  out drawn           integer,
  out lost            integer,
  out gf              integer,
  out ga              integer,
  out gd              integer,
  out points          integer,
  out form            jsonb
)
returns setof record
language sql
stable
set search_path = public, pg_temp
as $$
  with sides as (
    select m.home_team_id as team,
           m.away_team_id as opponent,
           coalesce(m.home_score, 0) as scored,
           coalesce(m.away_score, 0) as conceded,
           m.start_time,
           m.id as match_id,
           m.status
      from matches m
     where m.competition_id = p_competition_id
       and m.home_team_id is not null
       and m.away_team_id is not null
    union all
    select m.away_team_id,
           m.home_team_id,
           coalesce(m.away_score, 0),
           coalesce(m.home_score, 0),
           m.start_time,
           m.id,
           m.status
      from matches m
     where m.competition_id = p_competition_id
       and m.home_team_id is not null
       and m.away_team_id is not null
  ),
  -- Every club that appears in the competition, played or not: the browser rule builds a row for each of
  -- them (played = 0), so a competition mid-schedule must not shrink to only its finished sides.
  participants as (
    select distinct team from sides
  ),
  decided as (
    select * from sides where kicklive_is_final_status(status)
  ),
  tallied as (
    select team,
           count(*)                                                    as played,
           count(*) filter (where scored > conceded)                   as won,
           count(*) filter (where scored = conceded)                   as drawn,
           count(*) filter (where scored < conceded)                   as lost,
           coalesce(sum(scored), 0)                                    as gf,
           coalesce(sum(conceded), 0)                                  as ga,
           coalesce(sum(scored), 0) - coalesce(sum(conceded), 0)        as gd,
           -- 3/1/0, the rule the app has always applied; `competitions` has no points-per-win column, so
           -- inventing one here would be a schema change smuggled into a performance phase.
           coalesce(sum(case when scored > conceded then 3
                             when scored = conceded then 1
                             else 0 end), 0)                            as points
      from decided
     group by team
  ),
  forms as (
    select team,
           jsonb_agg(
             case when scored > conceded then 'W'
                  when scored = conceded then 'D'
                  else 'L'
             end
             order by start_time nulls last, match_id
           ) as form
      from decided
     group by team
  )
  select t.id,
         t.name,
         t.short_name,
         t.primary_color,
         t.secondary_color,
         coalesce(ta.played, 0)::integer,
         coalesce(ta.won, 0)::integer,
         coalesce(ta.drawn, 0)::integer,
         coalesce(ta.lost, 0)::integer,
         coalesce(ta.gf, 0)::integer,
         coalesce(ta.ga, 0)::integer,
         coalesce(ta.gd, 0)::integer,
         coalesce(ta.points, 0)::integer,
         coalesce(f.form, '[]'::jsonb)
    from participants p
    join teams t on t.id = p.team
    left join tallied ta on ta.team = t.id
    left join forms f on f.team = t.id
   -- The browser rule only counts clubs that are `active` (or pre-date the status column); keeping the same
   -- filter means the fallback and the function cannot disagree about a rejected club.
   where t.status = 'active' or t.status is null
   order by coalesce(ta.points, 0) desc,
            coalesce(ta.gd, 0) desc,
            coalesce(ta.gf, 0) desc,
            t.name asc;
$$;

comment on function kicklive_competition_standings(integer) is
  'League table for one competition, computed near the rows. SECURITY INVOKER: RLS decides which matches count. Mirrors src/lib/data/standings.ts.';

-- ── 3. squad sizes, for the club index ───────────────────────────────────────────────────────
--
--  `TeamsPage` used to read `select('team_id')` across every player row in the database and count them in a
--  Map — one row per human being, per page view. The column is named `count` because that is the field the
--  client spec reads.
create or replace function kicklive_squad_sizes()
returns table (team_id integer, count bigint)
language sql
stable
set search_path = public, pg_temp
as $$
  select p.team_id, count(*)::bigint
    from players p
    join teams t on t.id = p.team_id
   where p.team_id is not null
   group by p.team_id
   order by count(*) desc, p.team_id asc;
$$;

comment on function kicklive_squad_sizes() is
  'Rows per club, aggregated in Postgres. Replaces a per-player row scan in TeamsPage; bounded by RLS on players.';

-- ── 4. grants: execute for the roles that read, nothing else ──────────────────────────────────
--
--  Same posture as Phase 1/3: revoke broadly, then grant the one privilege the read path needs. These are
--  functions, so there is nothing to revoke DML on; the point of the revoke is that `execute` is granted to
--  PUBLIC by default in a fresh database.
revoke all on function kicklive_is_final_status(text) from public, anon, authenticated;
revoke all on function kicklive_competition_standings(integer) from public, anon, authenticated;
revoke all on function kicklive_squad_sizes() from public, anon, authenticated;

grant execute on function kicklive_is_final_status(text) to anon, authenticated, service_role;
grant execute on function kicklive_competition_standings(integer) to anon, authenticated, service_role;
grant execute on function kicklive_squad_sizes() to anon, authenticated, service_role;

-- ── 5. indexes: proposed, and deliberately NOT applied here ───────────────────────────────────
--
--  The rule for this phase is that an index needs a measurement. There is no database in this repository's
--  sandbox to measure against — no Postgres, no rows, no plan — so nothing is applied here. What is here
--  instead is the exact candidate set, in the exact names `scripts/query-audit.mjs --explain` prints (that
--  command emits an `explain (analyze, buffers, settings)` for the read each index serves, and a test in
--  `tests/unit/query-ratchet.test.ts` fails if this list and that list stop agreeing, because a name that
--  drifts is a name nobody applies).
--
--  Apply one at a time, against staging with production-shaped data, only for the ones whose plan shows a
--  sequential scan you actually pay for. `CREATE INDEX CONCURRENTLY` on a large table; `ANALYZE` after.
--
--    -- matches: the home live strip and every status-filtered fixture list — `status in (…) [and competition_id = …] order by start_time desc`
--    -- create index if not exists matches_status_start_time_idx on matches (status, start_time desc);
--    -- matches: the paginated match list, `order by start_time desc limit n`
--    -- create index if not exists matches_start_time_idx on matches (start_time desc);
--    -- matches: the standings aggregate's two side-scans and every per-competition fixture read
--    -- create index if not exists matches_competition_id_start_time_idx on matches (competition_id, start_time);
--    -- players: top scorers (`order by goals desc limit n`), the only unbounded sort left in a public read
--    -- create index if not exists players_goals_idx on players (goals desc nulls last, id);
--    -- teams: the club index and every sidebar — `status in (active, null) order by name`
--    -- create index if not exists teams_status_name_idx on teams (status, name);
--    -- media: the media feed and portal lists, `order by created_at desc limit n`
--    -- create index if not exists media_created_at_idx on media (created_at desc);
--    -- players: only if §3's aggregate turns out to cost more than it saves; its plan is
--    --   explain (analyze, buffers) select * from kicklive_squad_sizes();
--    -- create index if not exists players_team_id_idx on players (team_id);
--
--  The one the phase was tempted by and did not do: a covering index on `matches (competition_id) include
--  (status, home_score, away_score, home_team_id, away_team_id, start_time)` would make the standings
--  aggregate index-only. That is an index justified by one function written in the same change — precisely
--  the circular measurement the rule exists to stop.

-- ── 6. verification ───────────────────────────────────────────────────────────────────────────
--
--  Run in the same transaction as the file. It raises, so `commit` is unreachable from a broken state.
do $verify$
declare
begin
  if (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname = 'public'
         and p.proname in ('kicklive_is_final_status','kicklive_competition_standings','kicklive_squad_sizes')) <> 3 then
    raise exception 'phase4 verification failed: expected 3 read aggregates in public, found a different number';
  end if;

  -- INVOKER, not DEFINER: an aggregate must not see rows the caller cannot.
  if exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname in ('kicklive_competition_standings','kicklive_squad_sizes')
       and p.prosecdef
  ) then
    raise exception 'phase4 verification failed: a read aggregate is SECURITY DEFINER; it must be INVOKER';
  end if;

  -- search_path pinned, or a hijacked `public` alias could change what the aggregate reads.
  if exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname in ('kicklive_is_final_status','kicklive_competition_standings','kicklive_squad_sizes')
       and coalesce(array_to_string(p.proconfig, ','), '') not like '%search_path=public%'
  ) then
    raise exception 'phase4 verification failed: a read aggregate does not pin search_path';
  end if;

  if not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = 'kicklive_is_final_status'
       and p.prosrc like '%full_time%' and p.prosrc like '%completed%' and p.prosrc like '%finished%'
  ) then
    raise exception 'phase4 verification failed: kicklive_is_final_status lost a status the client rule counts';
  end if;

  -- Execute granted to the roles the browser uses, and nothing granted to PUBLIC beyond that.
  if (
    select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname in ('kicklive_is_final_status','kicklive_competition_standings','kicklive_squad_sizes')
       -- read the ACL rather than has_function_privilege(): the latter is true for the superuser the SQL
       -- editor runs as, which would make this count 3 on a database where the grant never landed.
       and exists (
         select 1 from pg_roles r, aclexplode(p.proacl) g
          where r.rolname = 'anon' and g.privilege_type = 'X' and (g.grantee = r.oid or g.grantee = 0))
  ) <> 3 then
    raise exception 'phase4 verification failed: anon cannot execute one of the read aggregates';
  end if;

  -- Calling the aggregate on a competition that does not exist must answer "nothing", not raise: the client
  -- treats an error as an outage and a zero-row answer as an empty table.
  perform kicklive_competition_standings(-1);
  perform count(*) from kicklive_squad_sizes();

  raise notice 'phase4 read aggregates: ok (3 functions, INVOKER, search_path pinned, granted to anon)';
end
$verify$;

-- PostgREST caches the schema cache; without this the new functions 404 until the next reload.
notify pgrst, 'reload schema';

-- ── manual checks, once applied ────────────────────────────────────────────────────────────────
--  VERIFY:  select count(*) from kicklive_squad_sizes();
--  VERIFY:  select * from kicklive_competition_standings((select id from competitions order by id limit 1)) limit 5;
--  VERIFY:  -- compare against the browser rule on the same data:
--           --   node scripts/query-audit.mjs --live --url https://<ref>.supabase.co --key <anon>
--           --   and open /tables (it now shows the SQL answer; the fallback path is /team/:id's cache key)
--  ROLLBACK: drop function if exists kicklive_competition_standings(integer);
--            drop function if exists kicklive_squad_sizes();
--            drop function if exists kicklive_is_final_status(text);
--            -- nothing else in this file needs undoing: no table, column, policy or row was touched.

commit;
;

-- <<< END section 4: supabase/migrations/20260910120000_phase4_read_aggregates.sql <<<

-- >>> BEGIN section 5: supabase/migrations/20260911120000_phase5_notifications.sql >>>
SELECT '5 / 10: supabase/migrations/20260911120000_phase5_notifications.sql' AS kicklive_sql_section;

-- ============================================================================
--  KICKLIVE · Phase 5 — notification system
--  20260911120000_phase5_notifications.sql
--
--  Design and audit: docs/NOTIFICATIONS_ARCHITECTURE.md. This file is the data half of it: the model, the
--  row-level security, and the SQL the Worker calls. No delivery logic lives here — FCM is a Worker concern.
--
--  WHAT THIS FILE DOES
--    1. extends `notifications` with a recipient, a kind, a read marker, a dedupe key and metadata;
--    2. replaces `notifications: public read` with an owner-or-broadcast policy (§5 — the security-critical
--       statement in this file, because a per-user inbox on a table everyone could read is a leak with a
--       nicer name);
--    3. adds `notification_preferences`, `notification_devices`, `notification_jobs`,
--       `notification_deliveries`, `match_interest`;
--    4. adds `profiles.notifications_enabled`;
--    5. puts a trigger on `match_events` that creates one job per notification-worthy event, in the same
--       transaction as the event;
--    6. adds the seven functions the Worker calls, so identity, the device cap, the audience and the
--       idempotency constraints are enforced in SQL rather than assumed from a client.
--
--  WHAT THIS FILE DOES NOT DO
--    - no drop, no truncate, no update of an existing row, and no delete of anything the app already had.
--      The only row deletions in this file are of rows this phase owns: an owner dismissing their own
--      `match_interest`, and the retention prune of device rows that were deactivated more than 30 days ago
--      (a credential from a churned install is a liability, not history).
--    - no `alter default privileges … revoke update, delete` (that pattern broke writes in an earlier phase
--      and is still forbidden by docs/PRODUCTION_MIGRATION_PLAN.md's standing constraints);
--    - no RLS disable, anywhere, ever;
--    - no change to `match_events`, `matches` or the Phase 3 functions: the event table gains a trigger, not
--      a column, and Phase 3's migration file is history and stays byte-identical;
--    - no FCM token, service-account material or VAPID private key — a database is a poor place to keep a
--      credential that Google can rotate, and `notification_devices.token` holds only what a client gave us.
--
--  HOW TO RUN IT — the same as the other two, and the same self-verifying shape:
--
--      begin;
--      \i supabase/migrations/20260911120000_phase5_notifications.sql
--      -- read §9's notice output, then commit;  (or rollback;)
--
--  It is safe to run twice (every statement is `if not exists` / `or replace` / drop-then-create by name),
--  which matters because a partially applied notification schema is worse than none: half the tables would
--  be readable by the wrong people.
-- ============================================================================

begin;

-- ── 1. the vocabulary, in one place ───────────────────────────────────────────────────────────
--
--  A category is simultaneously a preference row, a notification row, a job and a policy decision, so the
--  same eleven names appear in four CHECK constraints and in
--  `src/lib/data/notifications.ts` + `workers/src/lib/notificationPolicy.ts`. Three copies of a list is how
--  a phase like this produces "the app calls it goal, the database calls it match_goal, the phone gets
--  nothing", which is why the test in `tests/unit/phase5-notifications.test.ts` compares all four rather
--  than trusting this comment.
--
--  `match_reminder`, `team_update`, `competition_update` and `news` are in the vocabulary with no producer in
--  this file: they are the categories the settings screen has to show (step 17 of the brief asks for them)
--  and a preference for a kind that nothing sends yet is an honest placeholder, whereas a *table* the
--  frontend invents is a schema someone has to undo later.

-- ── 2. `notifications` — the inbox, on the table that already exists ────────────────────────────
--
--  Today: id, title, body, match_id, event_type, created_at. A broadcast log with no recipient. Every
--  existing row keeps working: `user_id is null` means broadcast, which is what all of them are.

alter table public.notifications
  add column if not exists user_id    uuid    references public.profiles(id) on delete cascade,
  add column if not exists kind       text    not null default 'system',
  add column if not exists dedupe_key text,
  add column if not exists read_at    timestamptz,
  add column if not exists metadata   jsonb   not null default '{}'::jsonb,
  add column if not exists priority   smallint not null default 0,
  add column if not exists expires_at timestamptz;

comment on column public.notifications.user_id is
  'The recipient. NULL = broadcast, which is every row written before Phase 5 and every admin announcement after it.';
comment on column public.notifications.dedupe_key is
  'match:<id>|seq:<sequence>|kind:<kind>, assigned by the server. The idempotency key: see docs/NOTIFICATIONS_ARCHITECTURE.md §10.';

alter table public.notifications
  drop constraint if exists notifications_kind_check;
alter table public.notifications
  add constraint notifications_kind_check
  check (kind in ('goal','red_card','half_time','full_time','match_start','match_reminder',
                  'team_update','competition_update','news','system','announcement'));

-- `event_type` is the pre-Phase-5 field and stays populated for old rows; new writers set `kind`. Both are
-- kept rather than migrated so that a rollback of this file does not lose the meaning of existing rows.

-- Partial, deliberately: the existing rows have no dedupe_key and several share a match_id, so a plain
-- unique index over (user_id, dedupe_key) would abort the migration on real data instead of extending it.
create unique index if not exists notifications_user_dedupe_key
  on public.notifications (user_id, dedupe_key)
  where dedupe_key is not null and user_id is not null;

create index if not exists notifications_inbox_idx
  on public.notifications (user_id, created_at desc nulls last)
  where user_id is not null;

create index if not exists notifications_unread_idx
  on public.notifications (user_id)
  where read_at is null and user_id is not null;

create index if not exists notifications_broadcast_idx
  on public.notifications (created_at desc)
  where user_id is null;

-- `expires_at` exists so a 90-minute "kick-off" nudge can age out of an inbox instead of sitting unread at the
-- top forever: the consumer sets it when it creates the row, and every read filters on it. Expiring is a
-- filter, not a delete — "we told you" stays auditable either way.

-- ── 3. new tables ───────────────────────────────────────────────────────────────────────────────

create table if not exists public.notification_preferences (
  user_id    uuid        not null references public.profiles(id) on delete cascade,
  kind       text        not null,
  enabled    boolean     not null default false,
  -- Two booleans would have been simpler and wrong: a second delivery medium is a third array element, not
  -- a migration. 'inbox' only = the app says something, the phone stays quiet.
  channels   text[]      not null default '{inbox,push}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, kind),
  constraint notification_preferences_kind_check
    check (kind in ('goal','red_card','half_time','full_time','match_start','match_reminder',
                    'team_update','competition_update','news','system','announcement')),
  -- `<@` is the whole rule: an array may not contain a channel that does not exist. A duplicate
  -- ('{push,push}') is harmless to every consumer and would only make the constraint worth misreading.
  constraint notification_preferences_channel_check
    check (channels <@ array['inbox','push']::text[] and channels <> '{}')
);

comment on table public.notification_preferences is
  'One row per user per category. Absent = the default below, which is why the defaults live in code that both the API and this file can read (kicklive_preference_defaults).';

create table if not exists public.notification_devices (
  id            uuid        primary key default gen_random_uuid(),
  user_id       uuid        not null references public.profiles(id) on delete cascade,
  -- 'webpush' exists so a raw browser subscription is a row and not a schema change; FCM is the only
  -- provider this phase delivers to (docs/NOTIFICATIONS_ARCHITECTURE.md §16).
  provider      text        not null check (provider in ('fcm','webpush')),
  token         text        not null,
  platform      text        not null default 'unknown' check (platform in ('android','ios','web','unknown')),
  app_id        text,
  ua_family     text,
  ua_major      integer,
  active        boolean     not null default true,
  failure_count integer     not null default 0,
  last_error_code text,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  last_seen_at  timestamptz not null default now(),
  last_sent_at  timestamptz,
  -- The load-bearing line for ownership: a token can belong to exactly one account, so registering it
  -- elsewhere moves it instead of subscribing a second recipient. Enforced here because a client cannot.
  constraint notification_devices_token_unique unique (provider, token)
);

create index if not exists notification_devices_user_active_idx
  on public.notification_devices (user_id, last_seen_at desc)
  where active;

comment on column public.notification_devices.token is
  'A credential. Never selected by a policy a browser can use, never returned by an endpoint, never logged (workers/src/services/fcm.ts redacts it).';

create table if not exists public.notification_jobs (
  id              bigint generated always as identity primary key,
  -- Named explicitly, because an inline `unique` on a column already called `dedupe_key` gets the
  -- autogenerated name `notification_jobs_dedupe_key_key` (the `_key` suffix is appended to a name that
  -- already ends in one), and §9.4 has to assert the index by the name pg_indexes actually stores. A
  -- verification that guesses at generated names is a verification that fails on a fresh install.
  dedupe_key      text    not null constraint notification_jobs_dedupe_key unique,
  kind            text    not null,
  match_id        integer references public.matches(id) on delete cascade,
  competition_id  integer references public.competitions(id) on delete cascade,
  team_id         integer references public.teams(id) on delete cascade,
  title           text    not null,
  body            text    not null,
  metadata        jsonb   not null default '{}'::jsonb,
  -- pending → running → sent | partial; retry is the only way back in, failed is terminal.
  status          text    not null default 'pending'
                          check (status in ('pending','running','retry','sent','partial','failed')),
  attempts        integer not null default 0,
  max_attempts    integer not null default 6 check (max_attempts between 1 and 25),
  next_attempt_at timestamptz not null default now(),
  recipient_count integer,
  created_at      timestamptz not null default now(),
  started_at      timestamptz,
  finished_at     timestamptz,
  last_error      text,
  created_by      uuid references public.profiles(id) on delete set null,
  constraint notification_jobs_kind_check
    check (kind in ('goal','red_card','half_time','full_time','match_start','match_reminder',
                    'team_update','competition_update','news','system','announcement')),
  -- A job with no audience selector would be "send to everyone", which is not a thing that should be
  -- accidentally reachable from a trigger.
  constraint notification_jobs_has_target
    check (match_id is not null or competition_id is not null or team_id is not null or kind = 'announcement')
);

create index if not exists notification_jobs_claimable_idx
  on public.notification_jobs (next_attempt_at)
  where status in ('pending','retry');

comment on table public.notification_jobs is
  'The durable wake-up. A notification exists as a row here before it exists in a queue, so a lost queue message costs delay, not silence (docs/NOTIFICATIONS_ARCHITECTURE.md §11).';

create table if not exists public.notification_deliveries (
  id                  bigint generated always as identity primary key,
  job_id              bigint  not null references public.notification_jobs(id) on delete cascade,
  device_id           uuid    not null references public.notification_devices(id) on delete cascade,
  user_id             uuid    not null references public.profiles(id) on delete cascade,
  notification_id     integer references public.notifications(id) on delete set null,
  status              text    not null check (status in ('sent','failed','skipped_invalid_token')),
  provider_message_id text,
  fcm_error           text,
  attempt             integer not null default 1,
  created_at          timestamptz not null default now(),
  sent_at             timestamptz,
  -- Per-device idempotency, which is what makes a queue redelivery safe to consume twice.
  constraint notification_deliveries_job_device_unique unique (job_id, device_id)
);

create index if not exists notification_deliveries_user_idx
  on public.notification_deliveries (user_id, created_at desc);

comment on table public.notification_deliveries is
  'Push outcomes, deliberately separate from `notifications`: an offline device has a notification and no delivery, and that difference is the product (§2 of the architecture).';

create table if not exists public.match_interest (
  user_id    uuid        not null references public.profiles(id) on delete cascade,
  match_id   integer     not null references public.matches(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, match_id)
);

comment on table public.match_interest is
  'The only relationship table in this phase: "tell me about this match". The follow model does not exist yet, and an audience needs one seam to grow into (step 18 of the brief: do not build favourites here).';

-- ── 4. the global switch ──────────────────────────────────────────────────────────────────────────
--
--  On `profiles`, because "everything off" is not a category and a per-kind table should stay a set of
--  categories. Default true: the app must not be born deaf, and with no `notification_devices` row nobody is
--  pushed to, so a default that is generous costs nothing until a user opts in.

alter table public.profiles
  add column if not exists notifications_enabled boolean not null default true;

comment on column public.profiles.notifications_enabled is
  'The master switch. Checked by every audience query; the per-category preferences sit under it, not over it.';

-- ── 5. row level security ─────────────────────────────────────────────────────────────────────────
--
--  Order: revoke everything from the client roles, grant only what a client genuinely needs, then policies.
--  RLS is *enabled*, never *forced*. Forced RLS also applies to the table owner, and every RPC below runs as
--  the owner by design (SECURITY DEFINER, `postgres`), so a FORCE here would make each of them insert zero
--  rows into its own table. This is the exact rule Phase 1 wrote down for `access_requests` and Phase 3
--  repeated for `match_assignments`; the client-side protection comes from `revoke` plus the absence of any
--  INSERT/UPDATE policy, both of which apply to anon/authenticated whether or not RLS is forced.

do $rls$
declare
  t text;
begin
  foreach t in array array['notification_preferences','notification_devices','notification_jobs','notification_deliveries','match_interest']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
  end loop;
  -- `notifications` is *not* revoked here. It is a pre-existing table whose grants Supabase issued at
  -- creation time, and a revocation would be a behaviour change for every caller at once — including the
  -- dead browser code in `MatchAutomation`, which should fail on RLS (a policy answer) rather than on
  -- privileges (a grant answer). The new tables are revoked because they have no such history.
  -- Function revokes are in §8, after the functions exist: `revoke … from public` on a name Postgres cannot
  -- resolve raises, and a migration that dies on its own ordering is a migration that gets run twice.
end
$rls$;

-- `notifications` — the statement to read carefully.
--
-- Phase 1's `notifications: public read` is `for select to anon, authenticated using (true)`: every row
-- readable by everyone, which was correct for a broadcast table and is a leak for an inbox. It is dropped by
-- name and replaced with owner-or-broadcast. A fan still sees every pre-Phase-5 row (they are broadcasts), so
-- this migration changes no existing behaviour for existing data — it only refuses to extend that visibility
-- to rows that have a recipient.
drop policy if exists "notifications: public read" on public.notifications;
-- Dropped by its own name as well, for the second run rather than the first: the line above retires
-- Phase 1's policy, and without this one a re-application of this file dies on
-- `policy "notifications: owner or broadcast read" already exists`.
drop policy if exists "notifications: owner or broadcast read" on public.notifications;
create policy "notifications: owner or broadcast read"
  on public.notifications for select to anon, authenticated
  using (user_id is null or user_id = auth.uid());

-- A user may mark their own rows read (and nothing else) and may dismiss them. Writes that *create* a
-- notification for anyone — including oneself — are not a client privilege: the Worker's service-role client
-- does them, so a browser cannot forge a "we told you about the title race" row.
drop policy if exists "notifications: owner update read" on public.notifications;
create policy "notifications: owner update read"
  on public.notifications for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid() and read_at is not null);

drop policy if exists "notifications: owner delete" on public.notifications;
create policy "notifications: owner delete"
  on public.notifications for delete to authenticated
  using (user_id = auth.uid());

-- Admin keeps the Phase 1 `notifications: admin all` policy (FOR ALL, is_admin()), which is how a broadcast
-- is written; it is not redefined here so that a rollback of this file cannot leave the table with no admin
-- write path.

-- preferences: self only, both directions.
drop policy if exists "notification_preferences: owner read" on public.notification_preferences;
create policy "notification_preferences: owner read"
  on public.notification_preferences for select to authenticated
  using (user_id = auth.uid());
drop policy if exists "notification_preferences: owner write" on public.notification_preferences;
create policy "notification_preferences: owner write"
  on public.notification_preferences for insert to authenticated
  with check (user_id = auth.uid());
drop policy if exists "notification_preferences: owner update" on public.notification_preferences;
create policy "notification_preferences: owner update"
  on public.notification_preferences for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
-- No FOR DELETE: "off" is `enabled = false`, and a missing row means defaults, so deleting a row to hide a
-- preference would be a way to make a setting unturnoffable. The RPC writes the full document either way.

-- devices: self only, and the token column is not reachable by a client policy at all — the settings screen
-- reads the view below instead. Delete is allowed because "sign this phone out" is a user action.
drop policy if exists "notification_devices: owner read" on public.notification_devices;
create policy "notification_devices: owner read"
  on public.notification_devices for select to authenticated
  using (false);   -- superseded by notification_devices_public; see the view
drop policy if exists "notification_devices: owner delete" on public.notification_devices;
create policy "notification_devices: owner delete"
  on public.notification_devices for delete to authenticated
  using (user_id = auth.uid());
-- No INSERT/UPDATE policy on purpose: registration goes through kicklive_register_notification_device(),
-- which takes the user from auth.uid() rather than from an argument. A client with a direct insert path can
-- point a token at another account the moment such a path exists.

-- jobs and deliveries: no client read, no client write, ever.
drop policy if exists "notification_jobs: admin read" on public.notification_jobs;
create policy "notification_jobs: admin read"
  on public.notification_jobs for select to authenticated
  using (public.is_admin());
drop policy if exists "notification_deliveries: admin read" on public.notification_deliveries;
create policy "notification_deliveries: admin read"
  on public.notification_deliveries for select to authenticated
  using (public.is_admin());
-- Diagnostics is the only surface a client gets, and it is an aggregate, not a row set (§17 of the
-- architecture): no policy here exposes who is subscribed to what.

-- match interest: owner, no update (the key *is* the state), no admin read.
drop policy if exists "match_interest: owner read" on public.match_interest;
create policy "match_interest: owner read"
  on public.match_interest for select to authenticated
  using (user_id = auth.uid());
drop policy if exists "match_interest: owner write" on public.match_interest;
create policy "match_interest: owner write"
  on public.match_interest for insert to authenticated
  with check (user_id = auth.uid());
drop policy if exists "match_interest: owner delete" on public.match_interest;
create policy "match_interest: owner delete"
  on public.match_interest for delete to authenticated
  using (user_id = auth.uid());

-- What the settings screen may read about its own devices: everything except the credential.
create or replace view public.notification_devices_public as
  select d.id, d.platform, d.provider, d.app_id, d.active, d.created_at, d.updated_at, d.last_seen_at, d.last_sent_at,
         d.failure_count > 0 as has_failures
    from public.notification_devices d
   where d.user_id = auth.uid();

comment on view public.notification_devices_public is
  'The device list a signed-in user may see. Deliberately without `token`: a settings screen has no reason to read a credential back, and a view is how that stays true after someone adds a fifth column.';

alter view public.notification_devices_public owner to postgres;
grant select on public.notification_devices_public to authenticated;

-- No grant line for `notifications` at all, on purpose (see §5): the table's privileges stay as the base
-- schema issued them and RLS decides, so the only new refusal a caller can hit is a policy refusal.
grant select, insert, delete on public.match_interest to authenticated;
grant select on public.notification_preferences to authenticated;
grant insert, update on public.notification_preferences to authenticated;
grant select, delete on public.notification_devices to authenticated;
grant select on public.notification_devices_public to authenticated;
-- Deliberately absent: insert/update on notification_devices, any write to notification_jobs or
-- notification_deliveries, and select on notification_devices (the token table) from a client role.

-- ── 6. the trigger: an authoritative event creates one job ────────────────────────────────────────
--
--  Why a trigger rather than a line inside `kicklive_record_match_event()`: the Phase 3 function is not the
--  only writer of `match_events` (the Durable Object's write-behind, an admin correction, a future importer),
--  and a notification rule that lives in one caller is a rule that the next caller forgets. It also means
--  the job row and the event row commit or roll back together without any coordination, which is the only
--  durability statement this phase needs (§8 of the architecture).
--
--  The key is `match:<id>|seq:<sequence>|kind:<kind>`. `sequence` is assigned by the server, once per match,
--  so it is exactly the thing that makes a replayed or re-delivered event a no-op instead of a duplicate push.

create or replace function public.kicklive_notification_job_for_event()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_kind   text;
  v_title  text;
  v_body   text;
  v_home   text;
  v_away   text;
  v_player text;
  v_match  public.matches%rowtype;
  v_score  text;
begin
  -- Only events that stand are worth a phone buzzing. A corrected row (event_status 'corrected') and the
  -- correction itself (corrects_event_id set) both stay silent: the inbox keeps the original notification,
  -- and the score a fan sees comes from the derived state, not from a second push.
  if new.corrects_event_id is not null then
    return new;
  end if;
  if new.event_status is not null and new.event_status <> 'active' then
    return new;
  end if;
  if new.match_id is null then
    return new;
  end if;

  -- The event→category map, in full. Everything Phase 3 treats as a moment worth a row is a moment worth a
  -- notification here, and everything else is `null` — a corner is not a push. Two judgement calls are worth
  -- naming: penalty goals and own goals are still goals (the category is what the user subscribed to, not the
  -- taxonomy of the pitch), and `second_half_start` rides the `match_start` category rather than inventing a
  -- twelfth one, because the setting a user toggles is "tell me when this match is happening".
  v_kind := case new.event_type
    when 'goal'                  then 'goal'
    when 'penalty_goal'          then 'goal'
    when 'own_goal'              then 'goal'
    when 'red_card'              then 'red_card'
    when 'second_yellow'         then 'red_card'
    when 'half_time'             then 'half_time'
    when 'extra_time_half_time'  then 'half_time'
    when 'full_time'             then 'full_time'
    when 'kickoff'               then 'match_start'
    when 'second_half_start'     then 'match_start'
    -- `match_abandoned` is deliberately absent. Abandonment is the most serious thing that can happen to a
    -- match, so a notification looks obviously right — but the brief's authoritative event list does not
    -- include it, `matches.status` already carries it, and inventing a trigger for a moment the spec did not
    -- name is how a notification system starts sending things nobody agreed to receive. Phase 6 can add it as
    -- its own category (with a default and a copy) rather than borrowing `system`.
    else null
  end;
  if v_kind is null then
    return new;
  end if;

  select * into v_match from public.matches where id = new.match_id;
  if not found then
    return new;
  end if;

  select name into v_home from public.teams where id = v_match.home_team_id;
  select name into v_away from public.teams where id = v_match.away_team_id;
  v_home := coalesce(v_home, 'Home');
  v_away := coalesce(v_away, 'Away');
  v_score := coalesce(v_match.home_score, 0)::text || ' – ' || coalesce(v_match.away_score, 0)::text;

  if new.player_id is not null then
    select name into v_player from public.players where id = new.player_id;
  end if;

  -- The wording the browser-side `sendMatchNotification` used, kept on purpose: the copy is product, and the
  -- only change in Phase 5 is who is allowed to trigger it and who receives it.
  v_title := case new.event_type
    when 'goal'                  then '⚽ GOAL!'
    when 'penalty_goal'          then '⚽ Penalty goal'
    when 'own_goal'              then '⚽ Own goal'
    when 'red_card'              then '🟥 Red card'
    when 'second_yellow'         then '🟥 Red card (second yellow)'
    when 'half_time'             then 'Half time'
    when 'extra_time_half_time'  then 'Half time, extra time'
    when 'full_time'             then 'Full time'
    when 'second_half_start'     then 'Second half'
    else 'Kick-off'
  end;
  -- The wording the browser-side `sendMatchNotification` used, kept on purpose, with the scorer suffix
  -- parenthesised as a sub-expression. Note that no arm of this CASE ends in `;`: inside a plpgsql
  -- assignment the whole `case … end` is one expression, so a semicolon after an arm closes the
  -- *statement* and leaves the outer CASE unterminated. Postgres reports that as
  -- `syntax error at end of input`, at CREATE FUNCTION time — which is why the trigger below would fail
  -- to install rather than fail to fire.
  v_body := case v_kind
    when 'goal' then v_home || ' ' || v_score || ' ' || v_away || (case when v_player is not null then ' — ' || v_player else '' end)
    when 'red_card' then v_home || ' vs ' || v_away || (case when v_player is not null then ' — ' || v_player else '' end)
    when 'half_time' then v_home || ' ' || v_score || ' ' || v_away
    when 'full_time' then 'Final: ' || v_home || ' ' || v_score || ' ' || v_away
    else case when new.event_type = 'second_half_start' then 'Second half under way: ' else 'Kick-off: ' end
         || v_home || ' vs ' || v_away
  end;

  insert into public.notification_jobs (dedupe_key, kind, match_id, competition_id, team_id, title, body, metadata, created_by)
  values (
    format('match:%s|seq:%s|kind:%s', new.match_id, coalesce(new.sequence, -new.id), v_kind),
    v_kind,
    new.match_id,
    v_match.competition_id,
    new.team_id,
    v_title,
    v_body,
    jsonb_build_object(
      'matchId', new.match_id,
      'eventId', new.id,
      'sequence', new.sequence,
      'minute', new.minute,
      'extraMinute', new.extra_minute,
      'homeScore', v_match.home_score,
      'awayScore', v_match.away_score,
      'homeTeam', v_home,
      'awayTeam', v_away,
      'scorer', v_player,
      'eventType', new.event_type
    ),
    new.recorded_by
  )
  on conflict (dedupe_key) do nothing;

  return new;
end;
$$;

comment on function public.kicklive_notification_job_for_event() is
  'AFTER INSERT on match_events: one job per stand-worthy event, keyed on the server-assigned sequence. Same transaction as the event, so a goal and its notification are one fact.';

-- An AFTER INSERT trigger's return value is ignored. It returns NEW anyway because the day someone changes
-- this to BEFORE ROW, a `return null` here would silently discard a referee's goal event — which is the
-- difference between a missed push and a corrupted match, and should not be reachable by a one-word edit.
drop trigger if exists kicklive_notification_job on public.match_events;
create trigger kicklive_notification_job
  after insert on public.match_events
  for each row execute function public.kicklive_notification_job_for_event();

-- ── 7. the functions the Worker calls ──────────────────────────────────────────────────────────────
--
--  Identity, the device cap, the audience, the claim and the idempotency rules are all here rather than in
--  TypeScript for one reason: the Worker is the only caller today, and "today" is the word that rots. A rule
--  in SQL cannot be bypassed by a second caller, a replayed request, or a route someone adds next month.
--
--  All of them are SECURITY DEFINER with a pinned search_path, all of them revoke from public, and each one
--  that a client could plausibly call checks `auth.uid()` itself instead of trusting the caller to have
--  filtered. Every function returns jsonb with an explicit `ok`/`code`, because "the server said no" needs to
--  be a code the SPA branches on, not a Postgres message the SPA pattern-matches.

-- 7.1 the defaults, so the API, the settings screen and the migration agree without a copy.
create or replace function public.kicklive_preference_defaults()
returns jsonb
language sql
immutable
set search_path = public, pg_temp
as $$
  select '{
    "goal": true,
    "red_card": false,
    "half_time": true,
    "full_time": true,
    "match_start": true,
    "match_reminder": false,
    "team_update": false,
    "competition_update": false,
    "news": false,
    "system": true,
    "announcement": true
  }'::jsonb;
$$;

comment on function public.kicklive_preference_defaults() is
  'Per-kind defaults. Noisy categories (red_card, reminders, news) start off: a notification system people turn the app off is worse than one they forget about.';

create or replace function public.kicklive_notification_defaults_document(p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
           'notificationsEnabled', coalesce((select pr.notifications_enabled from public.profiles pr where pr.id = p_user_id), true),
           'categories', coalesce(
             (select jsonb_object_agg(k.kind, jsonb_build_object('enabled', coalesce(p.enabled, (select (kicklive_preference_defaults() ->> k.kind)::boolean)), 'channels', coalesce(p.channels, array['inbox','push'])))
                from (select unnest(array['goal','red_card','half_time','full_time','match_start','match_reminder','team_update','competition_update','news','system','announcement']) as kind) k
                left join public.notification_preferences p on p.user_id = p_user_id and p.kind = k.kind),
             '{}'::jsonb)
         );
$$;

-- The client's read of its own document. A separate zero-argument function rather than granting
-- kicklive_notification_defaults_document(uuid) to `authenticated`: with a uuid argument, any signed-in user
-- could read *anyone's* per-category flags, and the "defaults" in the name is exactly the kind of word that
-- makes that look harmless in review. `auth.uid()` here, and nothing else.
create or replace function public.kicklive_notification_preferences()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.kicklive_notification_defaults_document(auth.uid());
$$;

comment on function public.kicklive_notification_preferences() is
  'GET /notifications/preferences. The caller''s own document; a signed-out session sees the defaults and no one else''s data.';

comment on function public.kicklive_notification_defaults_document(uuid) is
  'The whole preferences document for one user, defaults included. SECURITY DEFINER because a missing preference row must be answerable without granting a client select on the next user''s rows — which is what a left join across the table would otherwise need.';

-- 7.2 preferences: one round trip, one transaction, full-document semantics.
create or replace function public.kicklive_set_notification_preferences(
  p_enabled    boolean,
  p_categories jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  r      record;
  v_kind text;
  v_seen text[] := '{}';
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  if p_categories is null or jsonb_typeof(p_categories) <> 'object' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'categories must be an object');
  end if;

  update public.profiles set notifications_enabled = coalesce(p_enabled, true) where id = v_user;

  for r in select * from jsonb_each(p_categories)
  loop
    v_kind := r.key;
    if not exists (select 1 from (select unnest(array['goal','red_card','half_time','full_time','match_start','match_reminder','team_update','competition_update','news','system','announcement']) as k) x where x.k = v_kind) then
      return jsonb_build_object('ok', false, 'code', 'UNKNOWN_KIND', 'detail', v_kind);
    end if;
    if r.value ? 'enabled' and jsonb_typeof(r.value -> 'enabled') <> 'boolean' then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', v_kind || '.enabled must be a boolean');
    end if;
    if r.value ? 'channels' and (jsonb_typeof(r.value -> 'channels') <> 'array'
       or exists (select 1 from jsonb_array_elements_text(r.value -> 'channels') c where c not in ('inbox','push'))) then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', v_kind || '.channels must be a subset of {inbox,push}');
    end if;

    insert into public.notification_preferences (user_id, kind, enabled, channels, updated_at)
    values (
      v_user,
      v_kind,
      coalesce((r.value ->> 'enabled')::boolean, (select (kicklive_preference_defaults() ->> v_kind)::boolean), false),
      coalesce(array(select jsonb_array_elements_text(r.value -> 'channels')), array['inbox','push']),
      now()
    )
    on conflict (user_id, kind) do update
      set enabled = excluded.enabled,
          channels = excluded.channels,
          updated_at = now();

    v_seen := array_append(v_seen, v_kind);
  end loop;

  return jsonb_build_object('ok', true, 'document', kicklive_notification_defaults_document(v_user));
end;
$$;

comment on function public.kicklive_set_notification_preferences(boolean, jsonb) is
  'Full-document PUT for preferences. Returns the stored document so the client reconciles its optimistic state against the server rather than assuming it (§23 of the brief: a rejected save must not look saved).';

-- 7.3 device registration. The user id comes from auth.uid() and nowhere else; the cap and the re-pointing
--     rule are here so no route can get them wrong.
create or replace function public.kicklive_register_notification_device(
  p_provider text,
  p_token    text,
  p_platform text,
  p_app_id   text default null,
  p_ua       text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user   uuid := auth.uid();
  v_id     uuid;
  v_count  integer;
  v_max    integer := 10;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  if p_provider not in ('fcm','webpush') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'provider must be fcm or webpush');
  end if;
  if p_platform not in ('android','ios','web','unknown') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'platform must be android, ios, web or unknown');
  end if;
  -- A token is opaque and long; 4 KB is generous for FCM and Web Push alike, and it is the reason a
  -- malformed client cannot fill the table with a megabyte of noise per row.
  if p_token is null or length(p_token) < 20 or length(p_token) > 4096 then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'token must be 20-4096 characters');
  end if;

  select count(*) into v_count from public.notification_devices where user_id = v_user and active;
  -- Re-registering an existing token is never refused for a cap: the same phone refreshing its token must not
  -- be locked out because the owner has ten other devices.
  if v_count >= v_max and not exists (
       select 1 from public.notification_devices where provider = p_provider and token = p_token and user_id = v_user
     ) then
    return jsonb_build_object('ok', false, 'code', 'DEVICE_LIMIT', 'detail', v_max || ' active devices per account');
  end if;

  insert into public.notification_devices (user_id, provider, token, platform, app_id, ua_family, ua_major, active, last_seen_at, updated_at)
  values (
    v_user, p_provider, p_token, p_platform, nullif(coalesce(p_app_id, ''), ''),
    nullif(split_part(coalesce(p_ua, ''), '/', 1), ''),
    case when coalesce(p_ua, '') ~ '^[A-Za-z0-9 ._-]+/[0-9]+'
         then (split_part(split_part(p_ua, '/', 2), '.', 1))::integer else null end,
    true, now(), now()
  )
  on conflict (provider, token) do update
    set user_id      = excluded.user_id,
        platform     = excluded.platform,
        app_id       = coalesce(excluded.app_id, public.notification_devices.app_id),
        active       = true,
        failure_count = 0,
        last_error_code = null,
        last_seen_at = now(),
        updated_at   = now()
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id, 'active', true, 'devices',
    (select count(*) from public.notification_devices where user_id = v_user and active));
end;
$$;

comment on function public.kicklive_register_notification_device(text,text,text,text,text) is
  'The only write path for a device row. Identity from auth.uid(), ten-device cap, and ON CONFLICT re-points a token that changed owner. The response carries an id, never the token.';

create or replace function public.kicklive_unregister_notification_device(p_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
  v_rows integer;
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  -- Not "delete where id = p_id and user_id = auth.uid()" and a 404 on zero rows: the row may not exist or
  -- may belong to someone else, and a device list is not a place to leak which ids exist.
  delete from public.notification_devices where id = p_id and user_id = v_user;
  get diagnostics v_rows = row_count;
  if v_rows = 0 then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- 7.4 claiming a job: two consumers, one winner.
create or replace function public.kicklive_claim_notification_job(p_job_id bigint)
returns jsonb
language sql
security definer
set search_path = public, pg_temp
as $$
  with claim as (
    update public.notification_jobs
       set status = 'running', started_at = coalesce(started_at, now()), attempts = attempts + 1
     where id = p_job_id
       and status in ('pending','retry')
       and next_attempt_at <= now()
       and attempts < max_attempts
     returning *
  )
  select case when c.id is null then jsonb_build_object('ok', false, 'code', 'NOT_CLAIMABLE')
              else to_jsonb(c) - 'last_error' end
    from (select * from claim) c
   union all
  select jsonb_build_object('ok', false, 'code', 'NOT_CLAIMABLE') where not exists (select 1 from claim);
$$;

comment on function public.kicklive_claim_notification_job(bigint) is
  'FOR UPDATE SKIP LOCKED equivalent: the status predicate is the lock, so a queue redelivery racing the cron sweep yields one sender. Returns the row, never a token.';

-- 7.5 the entitlement rule, in exactly one place.
--
-- Everything that decides *who* may be told about a notification reads this function: the device query the
-- Worker sends to, the inbox insert, and the audience count an admin sees before a blast is accepted. Three
-- callers, one rule — because the failure mode of three copies is a push that arrives for someone the
-- settings screen says is opted out, or (worse) an inbox row for a user who declined the category.
--
-- Two things it deliberately does not do: it never mentions a device (a user with push off still gets an
-- inbox row), and it never mentions a medium (each caller filters `channels`, because "who is entitled" and
-- "through what" are different questions answered at different times).
create or replace function public.kicklive_notification_audience(
  p_kind           text,
  p_match_id       integer default null,
  p_competition_id integer default null,
  p_team_id        integer default null
)
returns table (user_id uuid, channels text[])
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select pr.id, coalesce(p.channels, array['inbox','push']::text[])
    from public.profiles pr
    -- A missing preference row is the default, not a refusal. `join` here rather than `left join` is the
    -- single easiest way to make a brand-new account silently un-notifiable, so it is a left join and the
    -- default is read from the same function the API hands to the settings screen.
    left join public.notification_preferences p on p.user_id = pr.id and p.kind = p_kind
   where pr.notifications_enabled
     and coalesce(p.enabled, (public.kicklive_preference_defaults() ->> p_kind)::boolean)
     and (
       -- A match-scoped kind goes to the people who asked about that match. There is no follow model yet, so
       -- that is the whole audience rule (docs/NOTIFICATIONS_ARCHITECTURE.md §13.1); the day one exists, the
       -- change is in this WHERE clause and nowhere else.
       p_match_id is null
       or p_kind in ('announcement','system','news')
       or exists (
         select 1 from public.match_interest mi
          where mi.match_id = p_match_id and mi.user_id = pr.id
       )
     )
   order by pr.id;
$$;

comment on function public.kicklive_notification_audience(text, integer, integer, integer) is
  'The one place that answers "who is entitled to be told about this". Service-role only: it enumerates users.';

-- 7.6 the devices to actually send to, built on that rule. A `webpush` row is a device we store but do not
-- deliver to (§16 — FCM is the only transport this phase implements), so it is filtered here rather than
-- ignored in the schema, which is what lets raw web push be added without a migration.
create or replace function public.kicklive_notification_recipients(p_job_id bigint)
returns table (device_id uuid, user_id uuid, token text, provider text, platform text)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select d.id, a.user_id, d.token, d.provider, d.platform
    from public.notification_jobs j
    -- lateral, because the audience depends on the job's own kind and match.
    join lateral public.kicklive_notification_audience(j.kind, j.match_id, j.competition_id, j.team_id) as a on true
    join public.notification_devices d on d.user_id = a.user_id
   where j.id = p_job_id
     and 'push' = any (a.channels)
     and d.active
     and d.provider = 'fcm'
     -- A device that FCM already said is dead stays dead until its owner registers it again.
     and coalesce(d.failure_count, 0) < 5
     -- The replay guard, before anything is sent: a delivery row for this device and this job means this job
     -- has already been delivered here, whatever the queue decided to do about the message.
     and not exists (
       select 1 from public.notification_deliveries dd
        where dd.job_id = j.id and dd.device_id = d.id
     )
   order by a.user_id, d.id;
$$;

comment on function public.kicklive_notification_recipients(bigint) is
  'Tokens for one job, already filtered by preference, already de-duplicated against delivery history. Never granted to a client role.';

-- 7.7 the fan-out itself: one statement, idempotent per user, and it never reads a token.
--
-- The inbox row is created from the *audience*, not from the device list, which is the whole point of step 16:
-- history exists whether or not a push succeeded, whether or not the user owns a device, and whether or not
-- `push` is one of their channels. Deriving it from `kicklive_notification_recipients()` would have tied the
-- record of what happened to the state of someone's phone.
create or replace function public.kicklive_materialise_notifications(p_job_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rows integer;
begin
  insert into public.notifications (user_id, title, body, kind, match_id, dedupe_key, metadata, created_at)
  select a.user_id, j.title, j.body, j.kind, j.match_id,
         j.dedupe_key || '|u:' || a.user_id, j.metadata, now()
    from public.notification_jobs j
    join lateral public.kicklive_notification_audience(j.kind, j.match_id, j.competition_id, j.team_id) as a on true
   where j.id = p_job_id
     and 'inbox' = any (a.channels)
  on conflict (user_id, dedupe_key) where dedupe_key is not null and user_id is not null do nothing;
  get diagnostics v_rows = row_count;
  return jsonb_build_object('ok', true, 'created', v_rows);
exception
  when unique_violation then
    -- The partial unique index is the constraint that could fire; a second materialisation of the same job is
    -- a no-op, not an error, and the delivery rows are what make the push itself once-per-device.
    return jsonb_build_object('ok', true, 'created', 0, 'note', 'already materialised');
end;
$$;

-- 7.8 the outcome of one batch, in one call.
--
-- The consumer sends up to 500 tokens at a time; asking it to make a round trip per device to record a result
-- would make the bookkeeping the slow part of a goal. So the batch's outcomes arrive as JSON and all three
-- effects happen here: the delivery row (the replay record), the device's standing (retire or forgive it), and
-- the timestamp the audit trail reads.
create or replace function public.kicklive_record_notification_results(
  p_job_id  bigint,
  p_results jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_deliveries integer;
  v_retired    integer;
begin
  if jsonb_typeof(p_results) <> 'array' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'p_results must be a JSON array');
  end if;

  -- A delivery row for a device that no longer exists must not abort the batch, so the device is joined and
  -- unmatched rows are dropped rather than referenced with an FK-violating insert.
  insert into public.notification_deliveries (job_id, device_id, user_id, status, provider_message_id, fcm_error, attempt, sent_at)
  select p_job_id,
         d.id,
         d.user_id,
         r->>'status',
         nullif(r->>'messageId', ''),
         -- The code FCM gave us, truncated, and nothing else: never the response body, never the token.
         left(coalesce(nullif(r->>'errorCode', ''), 'UNKNOWN'), 64),
         coalesce((select j.attempts from public.notification_jobs j where j.id = p_job_id), 1),
         case when r->>'status' = 'sent' then now() end
    from jsonb_array_elements(p_results) as r
    join public.notification_devices d on d.id = (r->>'deviceId')::uuid
   where jsonb_typeof(r) = 'object'
     and r->>'status' in ('sent','failed','skipped_invalid_token')
  on conflict (job_id, device_id) do update
     set status              = excluded.status,
         provider_message_id = coalesce(excluded.provider_message_id, public.notification_deliveries.provider_message_id),
         fcm_error           = excluded.fcm_error,
         attempt             = excluded.attempt,
         sent_at             = coalesce(excluded.sent_at, public.notification_deliveries.sent_at);
  get diagnostics v_deliveries = row_count;

  -- A token FCM said is gone is retired here, not in the Worker, so the rule cannot be forgotten by the next
  -- transport. The row is kept (audit) and made inactive (audience), and §7.13 deletes it after 30 days.
  update public.notification_devices d
     set active          = false,
         failure_count   = d.failure_count + 1,
         last_error_code = left(coalesce(nullif(r->>'errorCode', ''), 'UNREGISTERED'), 64),
         last_sent_at    = now(),
         updated_at      = now()
    from jsonb_array_elements(p_results) as r
   where d.id = (r->>'deviceId')::uuid
     and r->>'status' = 'skipped_invalid_token';
  get diagnostics v_retired = row_count;

  -- Any other failure is a strike, not a death sentence: five strikes and §7.6 stops offering the device.
  update public.notification_devices d
     set failure_count   = d.failure_count + 1,
         last_error_code = coalesce(left(nullif(r->>'errorCode', ''), 64), d.last_error_code),
         last_sent_at    = now()
    from jsonb_array_elements(p_results) as r
   where d.id = (r->>'deviceId')::uuid
     and r->>'status' = 'failed';

  -- A success forgives the device outright, which is what keeps a flaky network from retiring a good token.
  update public.notification_devices d
     set failure_count   = 0,
         last_error_code = null,
         last_seen_at    = now(),
         last_sent_at    = now()
    from jsonb_array_elements(p_results) as r
   where d.id = (r->>'deviceId')::uuid
     and r->>'status' = 'sent';

  return jsonb_build_object('ok', true, 'deliveries', v_deliveries, 'retired', v_retired);
end;
$$;

comment on function public.kicklive_record_notification_results(bigint, jsonb) is
  'One batch of FCM outcomes. The payload is device ids and error codes — never a token, never a response body.';

create or replace function public.kicklive_finish_notification_job(
  p_job_id          bigint,
  p_status          text,
  p_error           text default null,
  p_next_attempt_at timestamptz default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rows integer;
  v_sent integer;
  v_bad  integer;
begin
  if p_status not in ('sent','partial','failed','retry') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', p_status);
  end if;

  -- Counts come from the delivery rows, not from what the caller believes it sent, so the job's record cannot
  -- be talked into a number the evidence does not support.
  select count(*) filter (where status = 'sent'), count(*) filter (where status <> 'sent')
    into v_sent, v_bad
    from public.notification_deliveries where job_id = p_job_id;

  -- `status = 'running'` is the guard: the claim moved it there, and a finish that arrives after the sweep
  -- already requeued this job must not overwrite a newer attempt.
  update public.notification_jobs j
     set status          = p_status,
         recipient_count = coalesce(j.recipient_count, v_sent + v_bad),
         next_attempt_at = coalesce(p_next_attempt_at, j.next_attempt_at),
         finished_at     = case when p_status = 'retry' then null else now() end,
         last_error      = case when p_status = 'sent' then null
                               else left(coalesce(p_error, 'no detail'), 500) end
    where j.id = p_job_id
      and j.status = 'running'
      -- A job that exhausted its budget is terminal, and `retry` must not resurrect it past max_attempts.
      and not (p_status = 'retry' and j.attempts >= j.max_attempts);
  get diagnostics v_rows = row_count;

  if v_rows = 0 then
    return jsonb_build_object('ok', false, 'code', 'NOT_RUNNING', 'detail', 'already finished or never claimed');
  end if;
  return jsonb_build_object('ok', true, 'status', p_status, 'sent', v_sent, 'failed', v_bad,
                            'exhausted', (select attempts >= max_attempts from public.notification_jobs where id = p_job_id));
end;
$$;

comment on function public.kicklive_finish_notification_job(bigint, text, text, timestamptz) is
  'The only way out of running. Refuses to overwrite a job the sweep already requeued, and never resurrects one past its retry budget.';

-- 7.9 the inbox in one call, so a badge cannot disagree with the list under it.
create or replace function public.kicklive_notifications_page(p_limit integer default 20, p_before timestamptz default null)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', n.id, 'title', n.title, 'body', n.body, 'kind', n.kind,
               'matchId', n.match_id, 'metadata', n.metadata, 'createdAt', n.created_at,
               'readAt', n.read_at, 'priority', n.priority, 'broadcast', n.user_id is null)
             order by n.priority desc, n.created_at desc)
        from (
          select * from public.notifications
           where (user_id = auth.uid() or user_id is null)
             and (expires_at is null or expires_at > now())
             and (p_before is null or created_at < p_before)
           order by priority desc, created_at desc
           limit greatest(1, least(coalesce(p_limit, 20), 100))
        ) n
    ), '[]'::jsonb),
    'unread', coalesce((
      select count(*)::int from public.notifications
       where user_id = auth.uid() and read_at is null and (expires_at is null or expires_at > now())
    ), 0)
  );
$$;

create or replace function public.kicklive_mark_notifications_read(p_id integer)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rows integer;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  -- The user predicate is in the WHERE clause, not only in RLS: "0 rows changed" is the honest answer to a
  -- request about somebody else's row, and it is indistinguishable from "already read", which is the other
  -- answer a client should not have to treat as an error.
  update public.notifications set read_at = now()
   where id = p_id and user_id = auth.uid() and read_at is null;
  get diagnostics v_rows = row_count;
  return jsonb_build_object('ok', true, 'updated', v_rows);
end;
$$;

create or replace function public.kicklive_mark_all_notifications_read()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rows integer;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  -- Capped, so "mark all read" on a four-year account cannot hold a transaction open while the request that
  -- rendered the button is long gone.
  with doomed as (
    select id from public.notifications
     where user_id = auth.uid() and read_at is null
     order by created_at desc
     limit 500
  )
  update public.notifications n set read_at = now() from doomed where n.id = doomed.id;
  get diagnostics v_rows = row_count;
  return jsonb_build_object('ok', true, 'updated', v_rows, 'capped', v_rows >= 500);
end;
$$;

-- 7.10 match interest: the two calls the "notify me" button makes.
create or replace function public.kicklive_set_match_interest(p_match_id integer, p_watching boolean)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := auth.uid();
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'code', 'UNAUTHENTICATED');
  end if;
  if not coalesce(p_watching, false) then
    delete from public.match_interest where user_id = v_user and match_id = p_match_id;
    return jsonb_build_object('ok', true, 'watching', false);
  end if;
  if not exists (select 1 from public.matches m where m.id = p_match_id) then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  end if;
  insert into public.match_interest (user_id, match_id) values (v_user, p_match_id)
  on conflict (user_id, match_id) do nothing;
  return jsonb_build_object('ok', true, 'watching', true);
end;
$$;

-- 7.11 admin broadcast. Audience counted before anything is written, so a typo cannot quietly push to a
--     whole user base; the confirmation is a parameter, not a UI detail, because a scripted caller must hit
--     the same wall.
create or replace function public.kicklive_broadcast_notification(
  p_title text,
  p_body  text,
  p_kind  text,
  p_confirm boolean,
  p_max_audience integer default 50000,
  p_created_by uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_audience integer;
  v_job      bigint;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  if p_kind not in ('announcement','system','news','competition_update','team_update') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'an announcement may not claim a match-event category');
  end if;
  if length(coalesce(p_title,'')) = 0 or length(p_title) > 120 or length(coalesce(p_body,'')) > 480 then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'detail', 'title 1-120 and body up to 480 characters');
  end if;

  -- Counted from the same rule the delivery will use, and before the job exists: an audience estimate that
  -- came from a different query than the one that fans out would make the cap decorative.
  select count(*) into v_audience from public.kicklive_notification_audience(p_kind, null, null, null);

  if v_audience > p_max_audience then
    return jsonb_build_object('ok', false, 'code', 'AUDIENCE_TOO_LARGE', 'audience', v_audience, 'limit', p_max_audience);
  end if;
  if v_audience > 1000 and not coalesce(p_confirm, false) then
    return jsonb_build_object('ok', false, 'code', 'CONFIRMATION_REQUIRED', 'audience', v_audience);
  end if;

  insert into public.notification_jobs (dedupe_key, kind, title, body, metadata, recipient_count, created_by)
  values (
    format('broadcast:%s:%s', coalesce(p_created_by::text, 'system'), extract(epoch from now())::bigint),
    p_kind, p_title, p_body,
    jsonb_build_object('audience', 'all-enabled', 'broadcast', true),
    v_audience, p_created_by
  )
  returning id into v_job;

  return jsonb_build_object('ok', true, 'jobId', v_job, 'audience', v_audience);
end;
$$;

-- 7.12 the sweep's claim set, and the diagnostics read.
create or replace function public.kicklive_pending_notification_jobs(p_limit integer default 25)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'jobIds', coalesce((select jsonb_agg(id) from (
        select id from public.notification_jobs
         where status in ('pending','retry') and next_attempt_at <= now()
         order by created_at
         limit greatest(1, least(coalesce(p_limit, 25), 100))
      ) x), '[]'::jsonb),
    'counts', coalesce((select jsonb_object_agg(status, n) from (
        select status, count(*)::int as n from public.notification_jobs group by status
      ) y), '{}'::jsonb),
    'devices', jsonb_build_object(
      'active',  (select count(*)::int from public.notification_devices where active),
      'dead',    (select count(*)::int from public.notification_devices where not active),
      'invalid', (select count(*)::int from public.notification_devices where last_error_code = 'UNREGISTERED')
    ),
    'oldestPendingSeconds', (select extract(epoch from now() - min(created_at))::int from public.notification_jobs where status in ('pending','retry'))
  );
$$;

-- 7.13 retention: a revoked device is not a credential to keep. One statement in one place, with the window
--      in the SQL where the policy lives, so no Worker constant can drift it.
create or replace function public.kicklive_prune_notification_devices(p_window interval default interval '30 days')
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rows integer;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  delete from public.notification_devices where not active and updated_at < now() - p_window;
  get diagnostics v_rows = row_count;
  return jsonb_build_object('ok', true, 'deleted', v_rows);
end;
$$;

-- ── 8. function grants: the client gets the self-service ones, nothing else ─────────────────────────
--
--  `service_role` needs no grant (it is the owner's bypass and the Worker's only privileged path), and every
--  client-callable function below is one whose user id the function takes from auth.uid() itself.

do $grants$
declare
  f text;
  args text;
begin
  -- name(args) pairs, because Postgres resolves a function by signature and `revoke all on function
  -- public.kicklive_…` without arguments raises rather than silently doing nothing.
  for f, args in select * from (values
    ('kicklive_notification_defaults_document', 'uuid'),
    ('kicklive_notification_preferences', ''),
    ('kicklive_set_notification_preferences', 'boolean,jsonb'),
    ('kicklive_register_notification_device', 'text,text,text,text,text'),
    ('kicklive_unregister_notification_device', 'uuid'),
    ('kicklive_notifications_page', 'integer,timestamptz'),
    ('kicklive_mark_notifications_read', 'integer'),
    ('kicklive_mark_all_notifications_read', ''),
    ('kicklive_set_match_interest', 'integer,boolean'),
    ('kicklive_preference_defaults', ''),
    ('kicklive_notification_audience', 'text,integer,integer,integer'),
    ('kicklive_notification_recipients', 'bigint'),
    ('kicklive_claim_notification_job', 'bigint'),
    ('kicklive_materialise_notifications', 'bigint'),
    ('kicklive_record_notification_results', 'bigint,jsonb'),
    ('kicklive_finish_notification_job', 'bigint,text,text,timestamptz'),
    ('kicklive_broadcast_notification', 'text,text,text,boolean,integer,uuid'),
    ('kicklive_pending_notification_jobs', 'integer'),
    ('kicklive_prune_notification_devices', 'interval')
  ) as t(f, args)
  loop
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated', f, args);
  end loop;

  -- The self-service set only. Everything that reads a token, claims a job, or fans out to strangers stays
  -- service-role-only, so an exposed anon key cannot queue a send or enumerate a subscriber list.
  execute 'grant execute on function public.kicklive_notification_preferences() to authenticated';
  execute 'grant execute on function public.kicklive_set_notification_preferences(boolean, jsonb) to authenticated';
  execute 'grant execute on function public.kicklive_register_notification_device(text, text, text, text, text) to authenticated';
  execute 'grant execute on function public.kicklive_unregister_notification_device(uuid) to authenticated';
  execute 'grant execute on function public.kicklive_notifications_page(integer, timestamptz) to authenticated';
  execute 'grant execute on function public.kicklive_mark_notifications_read(integer) to authenticated';
  execute 'grant execute on function public.kicklive_mark_all_notifications_read() to authenticated';
  execute 'grant execute on function public.kicklive_set_match_interest(integer, boolean) to authenticated';
  execute 'grant execute on function public.kicklive_preference_defaults() to anon, authenticated';
end
$grants$;

-- No `grant … on sequence`: Supabase's default privileges already cover the identity sequences of tables
-- created here, and `grant … on sequence if exists …` is not a thing PostgreSQL accepts — so the correct
-- option was to leave the working default alone rather than invent syntax for it. What *is* checked below is
-- that a service-role insert can allocate an id, because a missing sequence privilege is a 42501 in
-- production and a pass in every test here.

-- ── 9. verification ────────────────────────────────────────────────────────────────────────────────
--
--  Raises on any failure, so the `commit;` at the end is unreachable from a half-applied state. This is the
--  same shape as the Phase 1 and Phase 3 files, and for a reason that matters more here than anywhere: a
--  notification schema with a missing policy is a privacy bug, not a broken feature.
do $verify$
declare
  v_kind_list text;
  v_count     integer;
begin
  -- 9.1 the five tables, RLS enabled and *not* forced.
  select count(*) into v_count from pg_tables
   where schemaname = 'public'
     and tablename in ('notification_preferences','notification_devices','notification_jobs','notification_deliveries','match_interest');
  if v_count <> 5 then
    raise exception 'phase5 verification failed: expected 5 notification tables, found %', v_count;
  end if;

  select count(*) into v_count from pg_class
   where relnamespace = 'public'::regnamespace
     and relname in ('notification_preferences','notification_devices','notification_jobs','notification_deliveries','match_interest')
     and relrowsecurity and not relforcerowsecurity;
  if v_count <> 5 then
    -- A `%` in the message is a substitution slot, not decoration: RAISE counts the specifiers and the
    -- arguments and refuses to compile when they disagree ("too few parameters specified for RAISE"), which
    -- would abort the whole verify block. So the number is passed.
    raise exception 'phase5 verification failed: all 5 tables need RLS enabled and FORCE off (got %), because the SECURITY DEFINER RPCs write as the owner and a forced policy would block them', v_count;
  end if;
  -- The mirror of that check, so a later "harden everything" edit cannot quietly break every notification
  -- RPC: forced RLS here is not a safety improvement, it is the outage.
  select count(*) into v_count from pg_class
   where relnamespace = 'public'::regnamespace
     and relname in ('notification_preferences','notification_devices','notification_jobs','notification_deliveries','match_interest')
     and relforcerowsecurity;
  if v_count > 0 then
    raise exception 'phase5 verification failed: % table(s) have FORCE ROW LEVEL SECURITY; see the comment in §5', v_count;
  end if;

  -- 9.2 the leak this whole migration exists to prevent.
  if exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'notifications' and policyname = 'notifications: public read') then
    raise exception 'phase5 verification failed: notifications: public read still exists — a per-user inbox on a table everyone can read is a leak';
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'notifications' and policyname = 'notifications: owner or broadcast read') then
    raise exception 'phase5 verification failed: the owner-or-broadcast policy is missing, so nobody can read their own inbox';
  end if;
  select count(*) into v_count from pg_policies
   where schemaname = 'public' and tablename = 'notifications' and policyname = 'notifications: owner or broadcast read'
     -- `qual` is the deparsed USING clause as text. The catalog column `polqual` is a node-tree and lives in
     -- pg_policy, not in this view, so `pg_get_expr(polqual, tableoid)` here is a "column does not exist"
     -- error at migration time — the check would abort the file rather than pass.
     and qual like '%auth.uid()%';
  if v_count <> 1 then
    raise exception 'phase5 verification failed: the owner-or-broadcast policy does not reference auth.uid() in its USING clause';
  end if;

  -- 9.3 no client role may read a device token, in any form.
  if public.kicklive_has_grant('authenticated', 'public.notification_devices', 'a')
     or public.kicklive_has_grant('anon', 'public.notification_devices', 'r') then
    raise exception 'phase5 verification failed: a client role can write or read notification_devices directly; registration is an RPC and the token is not selectable';
  end if;
  if public.kicklive_has_grant('authenticated', 'public.notification_jobs', 'a')
     or public.kicklive_has_grant('anon', 'public.notification_jobs', 'r')
     or public.kicklive_has_grant('authenticated', 'public.notification_deliveries', 'a') then
    raise exception 'phase5 verification failed: jobs and deliveries are not client-writable, and that is the only thing standing between an anon key and a mass send';
  end if;

  -- 9.4 the idempotency constraints exist, by name and by shape.
  select count(*) into v_count from pg_indexes
   where schemaname = 'public'
     and indexname in ('notifications_user_dedupe_key','notification_jobs_dedupe_key',
                       -- a table constraint's index is named after the constraint, and all three of these
                       -- are named explicitly above rather than left to Postgres' generated form.
                       'notification_deliveries_job_device_unique','notification_devices_token_unique');
  if v_count <> 4 then
    raise exception 'phase5 verification failed: one of the four idempotency/ownership indexes is missing (% of 4); without them a retried queue message is a duplicate push', v_count;
  end if;

  -- 9.5 the category vocabulary is the same list in all four constraints, and immutable.
  select string_agg(unnest, ',') into v_kind_list from unnest(array['goal','red_card','half_time','full_time','match_start','match_reminder','team_update','competition_update','news','system','announcement']);
  if (select count(*) from pg_constraint where conname in ('notifications_kind_check','notification_preferences_kind_check','notification_jobs_kind_check')) <> 3 then
    raise exception 'phase5 verification failed: a kind CHECK constraint is missing; the vocabulary must be enforced in every table, not in one';
  end if;
  if (select count(distinct pg_get_constraintdef(oid)) from pg_constraint
       where conname in ('notifications_kind_check','notification_preferences_kind_check','notification_jobs_kind_check')) <> 1 then
    raise exception 'phase5 verification failed: the three kind CHECKs do not hold the same list (% of distinct definitions)', (select count(distinct pg_get_constraintdef(oid)) from pg_constraint where conname in ('notifications_kind_check','notification_preferences_kind_check','notification_jobs_kind_check'));
  end if;
  if v_kind_list is null or length(v_kind_list) < 10 then
    raise exception 'phase5 verification failed: the kind list this file declares is unparseable';
  end if;

  -- 9.6 the trigger is attached, and to the table the engine actually writes.
  select count(*) into v_count from pg_trigger t
    join pg_class c on c.oid = t.tgrelid
   where t.tgname = 'kicklive_notification_job' and c.relname = 'match_events' and not t.tgisinternal;
  if v_count <> 1 then
    raise exception 'phase5 verification failed: the match_events trigger is not attached, so no event will ever notify anyone';
  end if;

  -- 9.7 every function exists with the signature the Worker calls.
  select count(*) into v_count from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public'
     and p.proname in ('kicklive_preference_defaults','kicklive_notification_defaults_document','kicklive_notification_preferences','kicklive_set_notification_preferences',
                       'kicklive_register_notification_device','kicklive_unregister_notification_device','kicklive_claim_notification_job',
                       'kicklive_notification_recipients','kicklive_notification_audience','kicklive_materialise_notifications',
                       'kicklive_record_notification_results','kicklive_finish_notification_job','kicklive_notifications_page',
                       'kicklive_mark_notifications_read','kicklive_mark_all_notifications_read','kicklive_set_match_interest',
                       'kicklive_broadcast_notification','kicklive_pending_notification_jobs','kicklive_prune_notification_devices',
                       'kicklive_notification_job_for_event');
  if v_count <> 20 then
    raise exception 'phase5 verification failed: expected 20 notification functions, found %', v_count;
  end if;

  -- 9.8 nothing is SECURITY INVOKER where it must not be, and nothing is DEFINER without a pinned path.
  select count(*) into v_count from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname like 'kicklive_%notification%'
     and p.prosecdef
     and coalesce(array_to_string(p.proconfig, ','), '') not like '%search_path=%';
  if v_count > 0 then
    raise exception 'phase5 verification failed: % SECURITY DEFINER notification function(s) without a pinned search_path — that is search_path hijacking, waiting for an unqualified reference', v_count;
  end if;

  -- 9.9 the view a settings screen may use exists, and does not carry a token column.
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'notification_devices_public' and column_name = 'token') then
    raise exception 'phase5 verification failed: notification_devices_public exposes `token`; the view is the thing that keeps a credential out of the settings screen';
  end if;
  select count(*) into v_count from information_schema.columns
   where table_schema = 'public' and table_name = 'notification_devices_public' and column_name in ('id','platform','provider','active','last_seen_at');
  if v_count <> 5 then
    raise exception 'phase5 verification failed: notification_devices_public is missing columns the settings screen needs (% of 5)', v_count;
  end if;

  -- 9.10 the columns on profiles and notifications, or a client read of a missing column is a 400 at
  --      runtime and a very confusing bug report.
  select count(*) into v_count from information_schema.columns
   where table_schema = 'public' and table_name = 'notifications'
     and column_name in ('user_id','kind','dedupe_key','read_at','metadata','priority','expires_at');
  if v_count <> 7 then
    raise exception 'phase5 verification failed: notifications gained % of the 7 planned columns', v_count;
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'profiles' and column_name = 'notifications_enabled') then
    raise exception 'phase5 verification failed: profiles.notifications_enabled is missing; the global switch is not optional';
  end if;

  -- 9.11 a live functional check: the audience function and the page function must run as an anonymous
  --      caller without raising. auth.uid() is null here, which is exactly the state a signed-out visitor is
  --      in, so this exercises the "no rows, no error" path that a schema-only review cannot see.
  select count(*) into v_count from kicklive_notification_recipients(0);
  if coalesce((select count(*) from information_schema.routines where routine_schema = 'public' and routine_name = 'kicklive_notifications_page'), 0) <> 1 then
    raise exception 'phase5 verification failed: kicklive_notifications_page is not callable';
  end if;

  raise notice 'phase5 verification: ok — 5 tables (RLS on, force off so the owner-role RPCs can write), 20 functions, 1 trigger, notifications extended and owner-scoped, tokens unselectable, 11 categories consistent across 3 CHECKs';
end
$verify$;

-- PostgREST caches the catalogue: without this the new RPCs 404 until a restart, which reads like a Worker bug.
notify pgrst, 'reload schema';

commit;

-- ── VERIFY, by hand, once applied ─────────────────────────────────────────────────────────────────
--  VERIFY:  select count(*) from pg_policies where tablename like 'notification%';
--  VERIFY:  select policyname, cmd, qual from pg_policies where tablename = 'notifications';
--           -- must show "notifications: owner or broadcast read" and NOT "notifications: public read"
--  VERIFY:  select public.kicklive_has_grant('authenticated','public.notification_devices','r');   -- false
--  VERIFY:  select public.kicklive_has_grant('anon','public.notification_jobs','r');                -- false
--  (Use that, not has_table_privilege(): from the superuser session of the SQL editor the latter answers "true"
--   for every role and proves nothing. Same reason the verify block above reads the ACLs.)
--  VERIFY:  select * from kicklive_pending_notification_jobs(5);                                   -- {"jobIds": [], …}
--  VERIFY:  -- register a device as a real user (via the Worker route), then:
--           --   select id, provider, platform, active from notification_devices order by created_at desc limit 1;
--           -- and confirm the token is NOT in the view:
--           --   select * from notification_devices_public limit 1;
--  VERIFY:  -- fire an event through the engine and confirm the job exists without touching the queue:
--           --   select id, kind, dedupe_key, status from notification_jobs order by id desc limit 3;
--           -- then replay the same event and confirm the count did not move.
--
--  ROLLBACK — safe in any order, because this file drops nothing it did not create. Row data is the thing
--  to think about: notifications written after Phase 5 carry a user_id and a dedupe_key, and dropping those
--  columns loses the inbox. So roll back by removing the surface, not the data, unless the inbox is wanted:
--
--    drop trigger if exists kicklive_notification_job on public.match_events;
--    drop function if exists public.kicklive_notification_job_for_event();
--    drop view if exists public.notification_devices_public;
--    drop table if exists public.notification_deliveries, public.notification_jobs,
--                           public.match_interest, public.notification_devices, public.notification_preferences;
--    -- then restore Phase 1's read policy so the broadcast table behaves as it did:
--    drop policy if exists "notifications: owner or broadcast read" on public.notifications;
--    create policy "notifications: public read" on public.notifications
--      for select to anon, authenticated using (true);
--    -- and leave the added columns alone: they are inert, nullable-with-defaults, and dropping them is a
--    -- second destructive step for no benefit.
--
--  Nothing in this file needs `analyze`, and nothing in it should be run against a production database
--  without the checks above being read first on staging.
;

-- <<< END section 5: supabase/migrations/20260911120000_phase5_notifications.sql <<<

-- >>> BEGIN section 6: supabase/migrations/20260912120000_phase6_r2_media.sql >>>
SELECT '6 / 10: supabase/migrations/20260912120000_phase6_r2_media.sql' AS kicklive_sql_section;

-- ============================================================================
-- Kick Live — Phase 6 migration: media registry for R2 storage
-- ============================================================================
-- Apply with:  supabase db reset            (local, destructive by design)
--              supabase db push             (staging, then production)
-- or paste this whole file into the Supabase SQL editor and run it once.
--
-- WHAT THIS MIGRATION DOES
--   * Creates public.media_assets — one row per stored object, the registry that
--     makes R2 keys, versions and ownership queryable instead of being folklore
--     inside a URL column.
--   * Creates public.media_operations — the audit trail for destructive and
--     bulk media actions (delete, purge, migration runs, retention sweeps).
--   * Adds public.can_manage_team(integer), the SQL mirror of
--     workers/src/services/teamAccess.ts. Media authorization is a row predicate
--     ("is this club yours?"), not a role name, and it has to be evaluated in SQL
--     because that is where the write happens.
--   * Adds the kicklive_* functions the Cloudflare Worker calls: reserve an
--     upload slot, finalize it, look a key up for the read-through, list an
--     entity's assets, soft-delete / restore / purge, reconcile orphans,
--     diagnose, and migrate one already-published Supabase Storage object.
--   * Grants media.* only to the service role (the Worker). No client key, no
--     client credential: the browser talks to the Worker and the Worker talks to
--     the database.
--
-- WHAT THIS MIGRATION NEVER DOES
--   * No drop table / drop column / delete. Every one of the eight existing
--     `*_url` columns stays exactly where it is and keeps its current meaning,
--     so all ~35 read sites keep rendering. New rows simply hold
--     /api/media/assets/<key> instead of a storage URL, and legacy absolute
--     URLs keep working because nothing inspects them.
--   * No row in media_assets implies a row elsewhere is deleted. `superseded`
--     and `deleted` are statuses, not destruction: an object that is no longer
--     referenced by a row can still be restored until retention expires, and
--     nothing here deletes an R2 object — the Worker does that, only when asked,
--     and only after recording it in media_operations.
--   * Does not force RLS on any table (see 9.6 of
--     docs/NOTIFICATIONS_ARCHITECTURE.md for why the policy set, not the force
--     flag, is what matters for this app's access paths), and does not add any
--     client-visible policy to media_assets: clients go through the functions.
--
-- Ordering matters. media_assets is created first because the functions depend
-- on the table and the verification block at the bottom depends on the
-- functions. Everything is wrapped in begin/commit so a failure mid-way leaves
-- the schema untouched instead of half-built.
-- ============================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1.  media_assets — the registry
-- ---------------------------------------------------------------------------
-- Two things this table exists to make impossible:
--   * an object with no owner and no reason (every row names the entity it
--     belongs to, the actor who stored it, and the version slot it fills);
--   * a URL that points at nothing (the URL a client renders is derived from a
--     row whose status is 'ready', and finalizing a failed upload never touches
--     the entity row at all).
-- entity_id is TEXT on purpose: teams/players/media ids are serial integers and
-- profile ids are uuids. A polymorphic reference cannot be a foreign key, so
-- referential integrity is enforced by the per-kind authorization queries below
-- and by the reconciliation function, not by a constraint. The alternative —
-- six nullable FK columns — would not be more honest and is much harder to read.
create table if not exists public.media_assets (
  id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entity_kind     TEXT        NOT NULL,
  entity_id       TEXT        NOT NULL,
  bucket          TEXT        NOT NULL,
  object_key      TEXT        NOT NULL,
  variant         TEXT        NOT NULL DEFAULT 'original',
  version         INTEGER     NOT NULL DEFAULT 1,
  content_type    TEXT,
  byte_size       BIGINT,
  width           INTEGER,
  height          INTEGER,
  sha256          TEXT,
  etag            TEXT,
  visibility      TEXT        NOT NULL,
  status          TEXT        NOT NULL DEFAULT 'uploading',
  alt_text        TEXT,
  source_url      TEXT,
  error           TEXT,
  created_by      UUID        REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  ready_at        TIMESTAMPTZ,
  superseded_at   TIMESTAMPTZ,
  deleted_at      TIMESTAMPTZ,
  constraint media_assets_kind_check check (entity_kind in
    ('teams', 'players', 'competitions', 'seasons', 'news', 'team_news', 'matches', 'users')),
  -- sponsors/ and advertisements/ are documented as reserved prefixes in
  -- docs/R2_MEDIA_ARCHITECTURE.md but are deliberately NOT legal here yet:
  -- there is no table to attach them to, and a CHECK that allows a kind nothing
  -- can authorize is how orphaned objects get made. Phase 7 adds them alongside
  -- its own tables with one alter statement.
  constraint media_assets_variant_check    check (variant ~ '^[a-z0-9][a-z0-9_-]{0,31}$'),
  constraint media_assets_visibility_check check (visibility in ('public', 'private')),
  constraint media_assets_status_check     check (status in
    ('uploading', 'ready', 'failed', 'superseded', 'deleted', 'purged')),
  -- Only the terminal, storage-holding states carry a digest or dimensions.
  -- Allowing NULL everywhere instead makes it impossible to tell "not an image"
  -- from "nobody looked", which is exactly the question a media bug asks.
  constraint media_assets_digest_check     check (sha256 is null or sha256 ~ '^[0-9a-f]{64}$'),
  -- The length bound is a separate predicate, not `{2,509}` inside the regex: Postgres' regex engine
  -- refuses a repetition count above 255 (RE_DUP_MAX) with `invalid regular expression: invalid repetition
  -- count(s)` — and it refuses it at *first evaluation*, not at CREATE TABLE, so a CHECK written that way
  -- installs happily and then fails every single insert.
  constraint media_assets_key_check        check (object_key ~ '^[a-z0-9][a-z0-9._/-]{2,}$' and char_length(object_key) between 3 and 512),
  constraint media_assets_size_check       check (byte_size is null or (byte_size > 0 and byte_size <= 26214400)),
  -- Every state transition has a timestamp and no state is silent.
  constraint media_assets_ready_at_check   check (status <> 'ready' or ready_at is not null),
  constraint media_assets_entity_id_check  check (entity_id ~ '^[0-9a-fA-F-]{1,64}$')
);
comment on table public.media_assets is
  'Registry of objects in the R2 media bucket: key, owner entity, version, digest, lifecycle status. Not the render path — the *_url columns on the entities are, and they hold /api/media/assets/<key> for rows created here.';
comment on column public.media_assets.object_key is
  'Full R2 key, unique. Derived by kicklive_asset_object_key, never accepted from a client; the prefix is what authorization decisions are made on.';
comment on column public.media_assets.status is
  'uploading = reserved, no object confirmed. ready = object written and referenced. failed = rejected or write failed. superseded = replaced by a later version, still restorable. deleted = soft-deleted row, object retained. purged = object deleted; terminal.';
comment on column public.media_assets.source_url is
  'The Supabase Storage URL an object was migrated from, kept so migration is idempotent and so a migration can be rolled back by URL rather than by guesswork.';

-- The unique index that makes replacement safe: at most one *ready* asset per
-- entity and variant. Finalizing supersedes the previous one in the same
-- statement, so a retry of the same finalize is a no-op rather than a second
-- logo, and a race between two uploads for the same slot fails on this index
-- instead of silently keeping whichever object landed last.
create unique index if not exists media_assets_one_ready_per_slot_idx
  on public.media_assets (entity_kind, entity_id, variant)
  where status = 'ready';
create index if not exists media_assets_entity_idx
  on public.media_assets (entity_kind, entity_id, status);
create index if not exists media_assets_creator_idx
  on public.media_assets (created_by, status, created_at desc);
-- Two schedulers read this shape: the stale-reservation sweep and the retention
-- sweep. Both ask "which rows have been in a non-ready state since before X".
create index if not exists media_assets_status_created_idx
  on public.media_assets (status, created_at)
  where status in ('uploading', 'failed', 'superseded', 'deleted');

-- ---------------------------------------------------------------------------
-- 2.  media_operations — audit of the destructive and bulk actions
-- ---------------------------------------------------------------------------
-- A media system that can delete user content has to be able to answer "who did
-- this and why" years later. Rows here are insert-only and never updated.
create table if not exists public.media_operations (
  id           BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  actor        UUID        REFERENCES public.profiles(id) ON DELETE SET NULL,
  action       TEXT        NOT NULL,
  asset_id     BIGINT,
  entity_kind  TEXT,
  entity_id    TEXT,
  object_key   TEXT,
  detail       JSONB,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  constraint media_operations_action_check check (action in
    ('reserve', 'finalize', 'failed', 'soft_delete', 'restore', 'purge',
     'retention_sweep', 'migration_run', 'migration_attach', 'reconcile'))
);
comment on table public.media_operations is
  'Insert-only audit trail for media deletes, purges, retention sweeps and migration runs. Never updated, never deleted by application code.';

-- ---------------------------------------------------------------------------
-- 3.  can_manage_team — the row predicate, in SQL
-- ---------------------------------------------------------------------------
create or replace function public.can_manage_team(p_team_id integer)
returns boolean
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- Mirror of managedTeamOrNull(): admin is a bypass, a manager only for their own club.
  select public.is_admin() or exists (
    select 1 from public.teams t where t.id = p_team_id and t.owner_id = auth.uid()
  );
$fn$;
comment on function public.can_manage_team(integer) is
  'SQL mirror of workers/src/services/teamAccess.ts: may the current session act on this club? SECURITY DEFINER so the team owner can see a club they manage without any policy change to teams.';

-- ---------------------------------------------------------------------------
-- 4.  Object key derivation
-- ---------------------------------------------------------------------------
-- The one place a key is assembled. Deterministic, and deliberately not
-- configurable: the browser never sends a key, so a compromise of a client
-- cannot put an object somewhere it should not be. `<hash8>` is the first eight
-- hex characters of the content digest, so re-uploading the same bytes to the
-- same slot produces the same key (and therefore no new row), while a different
-- upload to the same slot produces a different key and can be published before
-- the old one is superseded — the object the entity URL points at always exists.
create or replace function public.kicklive_asset_object_key(
  p_entity_kind text,
  p_entity_id   text,
  p_variant     text,
  p_version     integer,
  p_sha256      text,
  p_extension   text
) returns text
language sql immutable
set search_path = public, pg_temp
as $fn$
  select trim(both '/' from
    p_entity_kind || '/' || p_entity_id || '/'
    || p_variant || '/v' || p_version::text || '-' || left(lower(p_sha256), 8) || '.' || p_extension
  );
$fn$;
comment on function public.kicklive_asset_object_key(text, text, text, integer, text, text) is
  'The only place an R2 key is assembled: <entity-kind>/<entity-id>/<variant>/v<version>-<hash8>.<ext>. Callers pass components, never a key.';

-- ---------------------------------------------------------------------------
-- 5.  Per-kind policy, in SQL
-- ---------------------------------------------------------------------------
-- Mirrors workers/src/lib/mediaPolicy.ts. Two copies is a smell, and the
-- alternative — the Worker telling the database what the rules are — is worse:
-- a policy that can be passed in is a policy that can be passed wrong. The
-- phase6-media test asserts both sides agree, so a drift fails a test rather
-- than shipping a hole.
create or replace function public.kicklive_asset_visibility(p_entity_kind text)
returns text
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- Every kind this app has today is public, and the reason is a browser fact rather
  -- than a judgement about privacy: an <img> tag sends no Authorization header, so an
  -- object that is only fetchable with a token cannot be a logo, an avatar or a news
  -- photo at all. Avatars are the closest call and still public, because a profile
  -- picture is already rendered next to a public username for anonymous fans.
  --
  -- 'private' is therefore a supported *state* — the read route refuses it without a
  -- session, `kicklive_asset_authorized` decides it against auth.uid(), the cache class
  -- says no-store, and retention forgets it in 30 days instead of 30 years — and no
  -- entity kind selects it yet. The first kind that needs it (a verification document,
  -- a contract scan) is one line here, and it must be fetched into a blob URL rather
  -- than dropped in a src attribute.
  select 'public';
$fn$;

create or replace function public.kicklive_asset_url_column(p_entity_kind text)
returns text
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- Which column holds the render path for this kind, or NULL when the kind is
  -- asset-only and the caller keeps the URL wherever it likes.
  select case p_entity_kind
    when 'teams'      then 'logo_url'
    when 'players'    then 'photo_url'
    when 'competitions' then 'logo_url'
    when 'news'       then 'image_url'
    when 'team_news'  then 'image_url'
    when 'users'      then 'avatar_url'
    else null
  end;
$fn$;

create or replace function public.kicklive_upload_quota_bytes(p_role text)
returns bigint
language sql stable
as $fn$
  -- Per rolling 24 h. Admin is unlimited because "admin" here is the club of one
  -- person with a checklist, and a quota that trips during a tournament import
  -- would be a support call rather than a protection.
  select case p_role
    when 'admin' then null
    when 'media' then 268435456::bigint
    when 'team_manager' then 134217728::bigint
    when 'referee' then 33554432::bigint
    else 16777216::bigint
  end;
$fn$;

-- ---------------------------------------------------------------------------
-- 6.  reserve — authorize, check quotas, create the uploading row
-- ---------------------------------------------------------------------------
-- Called BEFORE the bytes are written. The row it returns is the upload's
-- reservation: it carries the key, the version slot and the authorization
-- decision, so the Worker writes to a key the database chose.
--
-- Dedupe: a matching (key, sha256) already ready ⇒ skip_upload, because R2 is
-- content-addressed within a slot and storing the same bytes twice buys nothing.
create or replace function public.kicklive_reserve_asset_upload(
  p_entity_kind text,
  p_entity_id   text,
  p_variant     text,
  p_content_type text,
  p_byte_size   bigint,
  p_sha256      text,
  p_width       integer default null,
  p_height      integer default null,
  p_alt_text    text default null
) returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_uid        uuid := auth.uid();
  v_role       text;
  v_owner      text;
  v_quota      bigint;
  v_used       bigint;
  v_kind       text;
  v_url_col    text;
  v_visibility text;
  v_bucket     text;
  v_version    integer;
  v_key        text;
  v_ext        text;
  v_dup        public.media_assets%rowtype;
  v_row        public.media_assets;
  v_reason     text;
begin
  -- The bucket name is data, not configuration: an environment whose storage is
  -- not bound cannot write a row that claims otherwise.
  v_bucket := nullif(current_setting('kicklive.storage_bucket', true), '');
  if v_bucket is null then
    v_bucket := 'media';
  end if;

  if v_uid is null then
    return jsonb_build_object('status', 'unauthenticated');
  end if;
  if p_variant is distinct from 'original' then
    -- Thumbnails exist in the key space and in the schema, and will be written
    -- by a producer, not by a browser. Accepting a client-supplied variant now
    -- would let a client claim a slot nothing can fill.
    v_reason := 'VARIANT_UNSUPPORTED';
  elsif p_byte_size is null or p_byte_size < 1 or p_byte_size > 26214400 then
    v_reason := 'TOO_LARGE';
  elsif p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    v_reason := 'DIGEST_REQUIRED';
  elsif p_entity_kind not in ('teams', 'players', 'competitions', 'seasons', 'news', 'team_news', 'matches', 'users') then
    v_reason := 'KIND_UNKNOWN';
  end if;
  if v_reason is not null then
    return jsonb_build_object('status', 'rejected', 'reason', v_reason);
  end if;

  v_ext := case lower(coalesce(p_content_type, ''))
    when 'image/png' then 'png'
    when 'image/jpeg' then 'jpg'
    when 'image/webp' then 'webp'
    when 'image/gif' then 'gif'
    when 'video/mp4' then 'mp4'
    else 'bin'
  end;

  select p.role::text into v_role from public.profiles p where p.id = v_uid;
  if v_role is null then
    -- No profile row means no product role; the JWT alone is not a permission.
    return jsonb_build_object('status', 'forbidden', 'reason', 'NO_PROFILE');
  end if;

  -- ── authorization, per kind, as a row predicate ───────────────────────────
  if p_entity_kind = 'users' then
    if p_entity_id <> v_uid::text and not public.is_admin() then
      return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_SELF');
    end if;
  elsif p_entity_kind = 'teams' then
    if not public.can_manage_team(p_entity_id::integer) then
      return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_YOUR_CLUB');
    end if;
  elsif p_entity_kind = 'players' then
    if not exists (
      select 1 from public.players pl
      join public.teams t on t.id = pl.team_id
      where pl.id::text = p_entity_id
        and (public.is_admin() or t.owner_id = v_uid)
    ) then
      return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_YOUR_CLUB');
    end if;
  elsif p_entity_kind = 'team_news' then
    if not exists (
      select 1 from public.team_news tn
      join public.teams t on t.id = tn.team_id
      where tn.id::text = p_entity_id
        and (public.is_admin() or t.owner_id = v_uid)
    ) then
      return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_YOUR_CLUB');
    end if;
  elsif p_entity_kind = 'news' then
    if not exists (
      select 1 from public.media m
      where m.id::text = p_entity_id
        and (public.is_admin_or_media() or m.author_id = v_uid)
    ) then
      return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_YOUR_ARTICLE');
    end if;
  else
    -- competitions, seasons, matches: staff kinds. An upload is a write to
    -- content the club does not own.
    if not public.is_admin_or_media() then
      return jsonb_build_object('status', 'forbidden', 'reason', 'ADMIN_REQUIRED');
    end if;
  end if;

  -- ── duplicate upload: same bytes, same slot ───────────────────────────────
  select * into v_dup from public.media_assets
   where object_key = public.kicklive_asset_object_key(
             p_entity_kind, p_entity_id, p_variant,
             coalesce((select max(a.version) from public.media_assets a
                        where a.entity_kind = p_entity_kind and a.entity_id = p_entity_id), 1),
             p_sha256, v_ext);
  if found then
    return jsonb_build_object('status', 'skip_upload', 'asset', to_jsonb(v_dup));
  end if;

  -- Same content already stored for this entity, any version, any key: nothing
  -- to write, and the entity URL can point at the existing row.
  select * into v_dup from public.media_assets
   where entity_kind = p_entity_kind and entity_id = p_entity_id and variant = p_variant
     and status = 'ready' and sha256 = p_sha256
   order by id desc limit 1;
  if found then
    return jsonb_build_object('status', 'skip_upload', 'asset', to_jsonb(v_dup));
  end if;

  -- ── quota: per role per rolling 24 hours ─────────────────────────────────
  v_quota := public.kicklive_upload_quota_bytes(v_role);
  if v_quota is not null then
    select coalesce(sum(coalesce(byte_size, 0)), 0) into v_used
      from public.media_assets
     where created_by = v_uid and created_at > now() - interval '24 hours'
       and status <> 'failed';
    if v_used + p_byte_size > v_quota then
      return jsonb_build_object(
        'status', 'rejected', 'reason', 'QUOTA_EXCEEDED',
        'quota_bytes', v_quota, 'used_bytes', v_used, 'requested_bytes', p_byte_size
      );
    end if;
  end if;

  v_visibility := public.kicklive_asset_visibility(p_entity_kind);
  v_kind := p_entity_kind;
  select coalesce(max(a.version), 0) + 1 into v_version
    from public.media_assets a
   where a.entity_kind = v_kind and a.entity_id = p_entity_id;

  v_key := public.kicklive_asset_object_key(v_kind, p_entity_id, p_variant, v_version, p_sha256, v_ext);

  insert into public.media_assets (
    entity_kind, entity_id, bucket, object_key, variant, version,
    content_type, byte_size, width, height, sha256, visibility, status, alt_text, created_by
  ) values (
    v_kind, p_entity_id, v_bucket, v_key, p_variant, v_version,
    p_content_type, p_byte_size, p_width, p_height, p_sha256, v_visibility, 'uploading',
    nullif(btrim(coalesce(p_alt_text, '')), ''), v_uid
  ) returning * into v_row;

  insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
  values (v_uid, 'reserve', v_row.id, v_kind, p_entity_id, v_key,
          jsonb_build_object('bytes', p_byte_size, 'content_type', p_content_type, 'version', v_version));

  return jsonb_build_object('status', 'proceed', 'asset', to_jsonb(v_row));
exception
  -- A reserved-but-unused row is a leak, so a refusal that comes from a
  -- constraint or a cast is reported as a rejection, not as a 500: the client
  -- sees the same shape either way and nothing is left in 'ready'.
  when check_violation or invalid_text_representation or numeric_value_out_of_range then
    return jsonb_build_object('status', 'rejected', 'reason', 'RESERVATION_REFUSED');
end;
$fn$;
comment on function public.kicklive_reserve_asset_upload(text, text, text, text, bigint, text, integer, integer, text) is
  'Authorize an upload, apply the per-role 24 h quota, and create the uploading row carrying the key. The browser never chooses a key, a version, a bucket or a visibility.';

-- ---------------------------------------------------------------------------
-- 7.  finalize — record the outcome, then (and only then) publish
-- ---------------------------------------------------------------------------
-- Two shapes of caller: a fresh upload, and a "nothing to write" completion for
-- an object that already exists (which is how a skip_upload reservation is
-- closed out). `p_outcome = 'failed'` records why and leaves the entity row
-- completely alone, which is what "no partially published entity" means in
-- practice: there is no half-published state to roll back because the entity was
-- never touched.
create or replace function public.kicklive_finalize_asset_upload(
  p_asset_id    bigint,
  p_outcome     text,
  p_etag        text default null,
  p_actual_size bigint default null,
  p_reason      text default null
) returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_asset      public.media_assets%rowtype;
  v_uid        uuid := auth.uid();
  v_url        text;
  v_url_col    text;
  v_sql        text;
  v_attached   boolean := false;
begin
  if p_outcome not in ('stored', 'existing', 'failed') then
    return jsonb_build_object('status', 'rejected', 'reason', 'OUTCOME_UNKNOWN');
  end if;

  select * into v_asset from public.media_assets where id = p_asset_id for update;
  if not found then
    return jsonb_build_object('status', 'rejected', 'reason', 'ASSET_NOT_FOUND');
  end if;
  -- The reservation belongs to whoever made it (and to staff). Finalizing
  -- somebody else's slot would be publishing content into their club.
  if v_asset.created_by is distinct from v_uid and not public.is_admin() then
    return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_RESERVER');
  end if;
  if v_asset.status = 'ready' then
    -- Idempotent close: a retried finalize reports the asset it already
    -- published instead of duplicating a version or erroring.
    return jsonb_build_object('status', 'ok', 'asset', to_jsonb(v_asset), 'idempotent', true);
  end if;
  if v_asset.status not in ('uploading', 'failed') then
    return jsonb_build_object('status', 'rejected', 'reason', 'ASSET_NOT_PENDING', 'actual', v_asset.status);
  end if;

  -- The size the client claimed and the size the bucket holds must agree. A
  -- mismatch means the bytes were swapped between sniffing and writing, which
  -- is exactly when a quota stops meaning anything — so it is a failure, not a
  -- warning.
  if p_outcome = 'stored' and p_actual_size is not null and p_actual_size is distinct from v_asset.byte_size then
    p_outcome := 'failed';
    p_reason := 'SIZE_MISMATCH';
  end if;

  if p_outcome = 'failed' then
    update public.media_assets
       set status = 'failed', error = left(coalesce(p_reason, 'CLIENT_REPORTED_FAILURE'), 64),
           updated_at = now()
     where id = v_asset.id;
    insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
    values (v_uid, 'failed', v_asset.id, v_asset.entity_kind, v_asset.entity_id, v_asset.object_key,
            jsonb_build_object('reason', p_reason));
    return jsonb_build_object('status', 'failed', 'asset_id', v_asset.id);
  end if;

  -- Supersede the previous occupant of the slot first: the partial unique index
  -- allows exactly one ready row per (kind, entity, variant), so ordering is
  -- the difference between a replacement and a constraint violation. The
  -- superseded object is not deleted: the old version stays restorable, and any
  -- URL still pointing at it keeps working.
  update public.media_assets a
     set status = 'superseded', superseded_at = now(), updated_at = now()
   where a.entity_kind = v_asset.entity_kind
     and a.entity_id = v_asset.entity_id
     and a.variant = v_asset.variant
     and a.status = 'ready'
     and a.id <> v_asset.id;

  update public.media_assets
     set status = 'ready',
         ready_at = now(),
         updated_at = now(),
         error = null,
         etag = coalesce(nullif(p_etag, ''), etag)
   where id = v_asset.id;

  v_url := '/api/media/assets/' || v_asset.object_key;
  v_url_col := public.kicklive_asset_url_column(v_asset.entity_kind);
  if v_url_col is not null then
    -- `v_url_col` comes from a two-branch CASE over a fixed list, so there is
    -- nothing injectable in it; it is dynamic SQL only because the target table
    -- and column vary per kind.
    v_sql := format('update public.%I set %I = $1 where id::text = $2',
      case v_asset.entity_kind when 'users' then 'profiles' else v_asset.entity_kind end, v_url_col);
    execute v_sql using v_url, v_asset.entity_id;
    get diagnostics v_attached = row_count;
  end if;

  insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
  values (v_uid, 'finalize', v_asset.id, v_asset.entity_kind, v_asset.entity_id, v_asset.object_key,
          jsonb_build_object('url', v_url, 'attached', v_attached, 'outcome', p_outcome));

  select * into v_asset from public.media_assets where id = v_asset.id;
  return jsonb_build_object('status', 'ok', 'asset', to_jsonb(v_asset), 'url', v_url, 'attached', v_attached);
end;
$fn$;
comment on function public.kicklive_finalize_asset_upload(bigint, text, text, bigint, text) is
  'Close out a reservation. On failure nothing outside media_assets changes. On success the previous version is superseded and the entity URL column is repointed at /api/media/assets/<key>.';

-- ---------------------------------------------------------------------------
-- 8.  resolve — what the read-through route needs, and nothing more
-- ---------------------------------------------------------------------------
create or replace function public.kicklive_asset_for_key(p_object_key text)
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- One row, three facts, no metadata a stranger can mine: the route needs to
  -- know whether to serve, for how long to cache, and with what content type.
  -- The outer coalesce matters: a lookup that returns no rows is the common
  -- case for a stale link, and the route should read 'unknown' rather than NULL.
  select coalesce(
    (select jsonb_build_object(
        'status', 'ok',
        'id', a.id,
        'visibility', a.visibility,
        'content_type', a.content_type,
        'byte_size', a.byte_size,
        'etag', a.etag,
        -- No `cache_class` here on purpose. How long a byte string may be held by a
        -- shared cache follows from the shape of the key (a versioned key is
        -- immutable), which is an HTTP concern and lives in
        -- workers/src/lib/mediaPolicy.ts. Duplicating it in SQL would give two
        -- answers to one question and only one of them would be the header a client
        -- actually receives.
        'entity_kind', a.entity_kind,
        'entity_id', a.entity_id
      )
      from public.media_assets a
      -- A superseded object stays readable on purpose: old documents, old push
      -- payloads and old shared links still reference it, and it is immutable by
      -- key, so serving it is both safe and the point of keeping it.
      where a.object_key = p_object_key
        and a.status in ('ready', 'superseded')),
    jsonb_build_object('status', 'unknown')
  );
$fn$;
comment on function public.kicklive_asset_for_key(text) is
  'Read-through lookup for GET /media/assets/*: status, visibility, content type, size, etag and the cache class. Returns unknown/gone rather than metadata for anything not serveable.';

create or replace function public.kicklive_asset_authorized(p_object_key text)
returns boolean
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- Private means private: the owner and staff, never the world, and the check
  -- runs on every request rather than being baked into an unguessable URL.
  select case a.visibility
           when 'public' then true
           else a.created_by = auth.uid() or public.is_admin()
         end
  from public.media_assets a
  where a.object_key = p_object_key and a.status in ('ready', 'superseded');
$fn$;

-- ---------------------------------------------------------------------------
-- 9.  list / delete / restore / purge
-- ---------------------------------------------------------------------------
create or replace function public.kicklive_entity_assets(p_entity_kind text, p_entity_id text)
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- Every version the caller is allowed to see, newest first. `deleted_ok`
  -- decides whether the caller may even ask about this entity, which is the same
  -- predicate reserve used, so the list cannot leak a club somebody else owns.
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', a.id, 'version', a.version, 'variant', a.variant, 'status', a.status,
        'object_key', a.object_key, 'content_type', a.content_type, 'byte_size', a.byte_size,
        'width', a.width, 'height', a.height, 'visibility', a.visibility,
        'created_at', a.created_at, 'ready_at', a.ready_at, 'superseded_at', a.superseded_at
      ) order by a.version desc, a.id desc
    ), '[]'::jsonb
  )
  from public.media_assets a
  where a.entity_kind = p_entity_kind
    and a.entity_id = p_entity_id
    and (
      public.is_admin()
      or (p_entity_kind = 'users' and (a.entity_id = auth.uid()::text or a.created_by = auth.uid()))
      or (p_entity_kind = 'teams' and public.can_manage_team(a.entity_id::integer))
      or (p_entity_kind in ('players', 'team_news') and exists (
            select 1 from public.teams t
            where t.owner_id = auth.uid()
              and t.id = case when p_entity_kind = 'players'
                              then (select pl.team_id from public.players pl where pl.id::text = a.entity_id)
                              else (select tn.team_id from public.team_news tn where tn.id::text = a.entity_id)
                          end))
      or (p_entity_kind = 'news' and exists (
            select 1 from public.media m where m.id::text = a.entity_id and m.author_id = auth.uid()))
      or (a.created_by = auth.uid() and a.status = 'uploading')
    );
$fn$;
comment on function public.kicklive_entity_assets(text, text) is
  'Version history for one entity, filtered by the same ownership predicate that authorizes uploads. Returns [] rather than an error when the caller may not see the entity.';

create or replace function public.kicklive_delete_asset(p_asset_id bigint, p_purge boolean default false)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_asset public.media_assets%rowtype;
  v_uid   uuid := auth.uid();
  v_sql   text;
begin
  select * into v_asset from public.media_assets where id = p_asset_id for update;
  if not found then
    return jsonb_build_object('status', 'rejected', 'reason', 'ASSET_NOT_FOUND');
  end if;
  if v_asset.created_by is distinct from v_uid and not public.is_admin() then
    return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_OWNER');
  end if;
  if p_purge and not public.is_admin() then
    return jsonb_build_object('status', 'forbidden', 'reason', 'PURGE_ADMIN_ONLY');
  end if;
  if v_asset.status = 'purged' then
    return jsonb_build_object('status', 'ok', 'idempotent', true, 'action', 'purged');
  end if;

  update public.media_assets
     set status = 'deleted', deleted_at = now(), updated_at = now()
   where id = v_asset.id and v_asset.status <> 'deleted';

  if p_purge then
    update public.media_assets set status = 'purged', updated_at = now() where id = v_asset.id;
    insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
    values (v_uid, 'purge', v_asset.id, v_asset.entity_kind, v_asset.entity_id, v_asset.object_key,
            jsonb_build_object('bytes', v_asset.byte_size));
    -- The registry row survives with status 'purged' rather than being deleted:
    -- "we stored this, it is gone now, here is who removed it" is the answer an
    -- investigation needs, and the row costs nothing.
  else
    insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
    values (v_uid, 'soft_delete', v_asset.id, v_asset.entity_kind, v_asset.entity_id, v_asset.object_key, null);
  end if;

  -- Deleting the current version must not leave the entity pointing at an
  -- object that is being purged. The partial unique index guarantees no other
  -- ready row for this slot, so the honest behaviour is to clear the column and
  -- let the UI fall back to its placeholder — inventing a "previous" URL here
  -- would mean guessing which superseded version the owner wanted back.
  if v_asset.status = 'ready' and public.kicklive_asset_url_column(v_asset.entity_kind) is not null then
    v_sql := format('update public.%I set %I = null where id::text = $1',
      case v_asset.entity_kind when 'users' then 'profiles' else v_asset.entity_kind end,
      public.kicklive_asset_url_column(v_asset.entity_kind));
    execute v_sql using v_asset.entity_id;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'action', case when p_purge then 'purged' else 'soft_deleted' end,
    'object_key', v_asset.object_key,
    'bucket', v_asset.bucket,
    'delete_object', p_purge,
    'restore_days', case when p_purge then 0 else 30 end
  );
end;
$fn$;
comment on function public.kicklive_delete_asset(bigint, boolean) is
  'Soft delete by default: the row and the object both stay, the URL stops resolving to it, and restore is available for 30 days. Purge (admin only) marks the row purged and asks the caller to delete the object; nothing here deletes an object.';

create or replace function public.kicklive_restore_asset(p_asset_id bigint)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_asset public.media_assets%rowtype;
  v_uid   uuid := auth.uid();
begin
  select * into v_asset from public.media_assets where id = p_asset_id for update;
  if not found then
    return jsonb_build_object('status', 'rejected', 'reason', 'ASSET_NOT_FOUND');
  end if;
  if v_asset.created_by is distinct from v_uid and not public.is_admin() then
    return jsonb_build_object('status', 'forbidden', 'reason', 'NOT_OWNER');
  end if;
  if v_asset.status not in ('deleted', 'superseded') then
    return jsonb_build_object('status', 'rejected', 'reason', 'NOT_RESTORABLE', 'actual', v_asset.status);
  end if;

  -- Restoring supersedes whatever took the slot, because "one current version"
  -- is the invariant the render path relies on.
  update public.media_assets a set status = 'superseded', superseded_at = now(), updated_at = now()
   where a.entity_kind = v_asset.entity_kind and a.entity_id = v_asset.entity_id
     and a.variant = v_asset.variant and a.status = 'ready' and a.id <> v_asset.id;

  update public.media_assets
     set status = 'ready', ready_at = coalesce(ready_at, now()), superseded_at = null,
         deleted_at = null, updated_at = now()
   where id = v_asset.id;

  insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
  values (v_uid, 'restore', v_asset.id, v_asset.entity_kind, v_asset.entity_id, v_asset.object_key, null);

  return jsonb_build_object('status', 'ok', 'asset_id', v_asset.id);
end;
$fn$;

-- ---------------------------------------------------------------------------
-- 10.  retention sweep and orphan reconciliation
-- ---------------------------------------------------------------------------
-- Which rows are old enough to forget is a database decision (it needs created_at
-- and status); which objects to actually delete is a storage decision (it needs
-- the bucket). So the function returns keys and the Worker deletes them, once
-- per hour, inside a batch.
create or replace function public.kicklive_sweep_media(p_limit integer default 500)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_rows jsonb;
  v_n    integer;
begin
  if not public.is_admin() then
    return jsonb_build_object('status', 'forbidden');
  end if;

  -- Abandoned reservations: 'uploading' rows older than 24 h are a client that
  -- never came back. They expire to 'failed' rather than being deleted, because
  -- the object may well exist and an unexplained disappearance is worse than a
  -- recorded failure. Bounded, because this runs on a cron next to everything
  -- else the Worker does at :00.
  update public.media_assets
     set status = 'failed', error = 'RESERVATION_EXPIRED', updated_at = now()
   where id in (
     select a.id from public.media_assets a
      where a.status = 'uploading' and a.created_at < now() - interval '24 hours'
      order by a.id limit p_limit
   );
  get diagnostics v_n = row_count;

  -- Expired soft deletes and superseded versions, past their retention window.
  -- Private objects are forgotten sooner than public ones: "delete" for a private
  -- upload has to mean the bytes stop being served, not just that the URL moved.
  -- No kind is private today, so this branch is the mechanism waiting for the first
  -- one rather than a rule anybody can observe, which is why the media tests
  -- exercise it directly against a fake registry.
  update public.media_assets
     set status = 'purged', updated_at = now()
   where id in (
     select a.id from public.media_assets a
      where (a.status in ('deleted', 'superseded')
             and coalesce(a.deleted_at, a.superseded_at) < now() - interval '30 days')
         or (a.status in ('ready', 'deleted', 'superseded')
             and a.visibility = 'private'
             and a.created_at < now() - interval '30 days')
      order by a.id limit p_limit
   );

  select coalesce(jsonb_agg(jsonb_build_object('object_key', x.object_key, 'id', x.id)), '[]'::jsonb) into v_rows
  from (
    select a.id, a.object_key from public.media_assets a
     where a.status = 'purged' and a.updated_at > now() - interval '10 minutes'
     order by a.id limit p_limit
  ) x;

  insert into public.media_operations (actor, action, detail)
  values (auth.uid(), 'retention_sweep', jsonb_build_object('expired_reservations', v_n, 'purged', v_rows));

  return jsonb_build_object('status', 'ok', 'expired_reservations', v_n, 'keys_to_delete', v_rows);
end;
$fn$;
comment on function public.kicklive_sweep_media(integer) is
  'Hourly retention step: expires stale reservations, retires objects past their retention window, and returns the object keys the Worker must delete from R2. Admin-only because it is the only function that decides something should stop existing.';

-- The other half of reconciliation: the Worker lists the bucket, the database
-- says which of those keys are known and which registry rows have no object.
-- Doing the set difference in SQL keeps the comparison exact instead of
-- "downloaded a few hundred rows and eyeballed it".
create or replace function public.kicklive_reconcile_assets(p_live_keys jsonb, p_prefix text default null)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_orphans jsonb;
  v_missing jsonb;
begin
  if not public.is_admin() then
    return jsonb_build_object('status', 'forbidden');
  end if;

  select coalesce(jsonb_agg(k.value), '[]'::jsonb) into v_orphans
  from jsonb_array_elements_text(coalesce(p_live_keys, '[]'::jsonb)) as k(value)
  where not exists (select 1 from public.media_assets a where a.object_key = k.value);

  select coalesce(jsonb_agg(a.object_key), '[]'::jsonb) into v_missing
  from public.media_assets a
  where a.status in ('ready', 'superseded')
    and (p_prefix is null or a.object_key like replace(p_prefix, '*', '') || '%')
    and not exists (
      select 1 from jsonb_array_elements_text(coalesce(p_live_keys, '[]'::jsonb)) as k(value)
      where k.value = a.object_key
    );

  return jsonb_build_object(
    'status', 'ok',
    'objects_without_rows', v_orphans,
    'rows_without_objects', v_missing,
    'compared', jsonb_array_length(coalesce(p_live_keys, '[]'::jsonb))
  );
end;
$fn$;

-- ---------------------------------------------------------------------------
-- 11.  diagnostics
-- ---------------------------------------------------------------------------
create or replace function public.kicklive_asset_diagnostics()
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  select jsonb_build_object(
    'status', 'ok',
    'by_status', (
      select coalesce(jsonb_object_agg(s.status, s.n), '{}'::jsonb)
      from (select a.status, count(*) n from public.media_assets a group by a.status) s
    ),
    'by_kind', (
      select coalesce(jsonb_object_agg(k.entity_kind, k.n), '{}'::jsonb)
      from (select a.entity_kind, count(*) n from public.media_assets a where a.status = 'ready' group by a.entity_kind) k
    ),
    'total_bytes', (select coalesce(sum(a.byte_size), 0) from public.media_assets a where a.status in ('ready', 'superseded')),
    'uploading_over_1h', (select count(*) from public.media_assets a where a.status = 'uploading' and a.created_at < now() - interval '1 hour'),
    'ready_missing_digest', (select count(*) from public.media_assets a where a.status = 'ready' and a.sha256 is null),
    'still_url_pointing_at_storage', (
      select coalesce(jsonb_object_agg(t.kind, t.n), '{}'::jsonb)
      from (
        select 'media' kind, count(*) n from public.media where image_url like '%/storage/v1/object/%'
        union all select 'team_news', count(*) from public.team_news where image_url like '%/storage/v1/object/%'
        union all select 'teams', count(*) from public.teams where logo_url like '%/storage/v1/object/%'
        union all select 'players', count(*) from public.players where photo_url like '%/storage/v1/object/%'
        union all select 'competitions', count(*) from public.competitions where logo_url like '%/storage/v1/object/%'
        union all select 'profiles', count(*) from public.profiles where avatar_url like '%/storage/v1/object/%'
      ) t
    ),
    'operations_last_24h', (
      select coalesce(jsonb_object_agg(o.action, o.n), '{}'::jsonb)
      from (select m.action, count(*) n from public.media_operations m where m.created_at > now() - interval '24 hours' group by m.action) o
    )
  );
$fn$;

-- The migration's cheap question. `failed` rows are deliberately *not* an answer:
-- a re-run is the recovery step for an object whose copy broke halfway, so only a
-- settled state (in the bucket, or consciously skipped) counts as "seen".
create or replace function public.kicklive_migration_seen(p_source_url text)
returns text
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  select a.object_key
  from public.media_assets a
  where a.source_url = p_source_url and a.status in ('ready', 'deleted')
  order by a.id desc
  limit 1;
$fn$;

-- ---------------------------------------------------------------------------
-- 12.  migration record — one row per already-published object
-- ---------------------------------------------------------------------------
-- The migration itself reads and writes the bucket, which only the Worker can
-- do. What the database owns is the *record*: this function is idempotent on the
-- source URL, so a migration run that dies halfway can be re-run and only the
-- objects that are actually in R2 become attached to entities.
create or replace function public.kicklive_record_migrated_asset(
  p_entity_kind text,
  p_entity_id   text,
  p_object_key  text,
  p_content_type text,
  p_byte_size   bigint,
  p_sha256      text,
  p_source_url  text,
  p_outcome     text,
  p_reason      text default null
) returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_asset   public.media_assets%rowtype;
  v_uid     uuid := auth.uid();
  v_url     text;
  v_url_col text;
begin
  if not public.is_admin() then
    return jsonb_build_object('status', 'forbidden', 'reason', 'ADMIN_REQUIRED');
  end if;
  if p_outcome not in ('migrated', 'skipped', 'failed') then
    return jsonb_build_object('status', 'rejected', 'reason', 'OUTCOME_UNKNOWN');
  end if;

  -- Same source URL, seen before: report it, change nothing. This is what makes
  -- re-running the migration safe rather than merely unlikely to duplicate.
  select * into v_asset from public.media_assets
   where source_url = p_source_url and entity_kind = p_entity_kind and entity_id = p_entity_id
   order by id desc limit 1;
  if found then
    return jsonb_build_object('status', 'ok', 'idempotent', true, 'asset', to_jsonb(v_asset),
                              'prior_status', v_asset.status);
  end if;

  if p_outcome = 'failed' then
    insert into public.media_assets (
      entity_kind, entity_id, bucket, object_key, variant, content_type, byte_size, sha256,
      visibility, status, source_url, error, created_by
    ) values (
      p_entity_kind, p_entity_id, 'media', p_object_key, 'original', p_content_type, p_byte_size, p_sha256,
      public.kicklive_asset_visibility(p_entity_kind), 'failed', p_source_url,
      left(coalesce(p_reason, 'MIGRATION_FAILED'), 64), v_uid
    );
    return jsonb_build_object('status', 'recorded', 'state', 'failed');
  end if;

  if p_outcome = 'skipped' then
    -- A skipped object is recorded as 'deleted' rather than inventing a status:
    -- it is registered, not in R2, and must not be counted as an orphan.
    insert into public.media_assets (
      entity_kind, entity_id, bucket, object_key, variant, content_type, byte_size, sha256,
      visibility, status, source_url, error, created_by
    ) values (
      p_entity_kind, p_entity_id, 'supabase-storage', p_object_key, 'original', p_content_type, p_byte_size, p_sha256,
      public.kicklive_asset_visibility(p_entity_kind), 'deleted', p_source_url,
      left(coalesce(p_reason, 'SKIPPED'), 64), v_uid
    );
    return jsonb_build_object('status', 'recorded', 'state', 'skipped');
  end if;

  insert into public.media_assets (
    entity_kind, entity_id, bucket, object_key, variant, version, content_type, byte_size, sha256,
    visibility, status, source_url, ready_at, created_by
  ) values (
    p_entity_kind, p_entity_id, 'media', p_object_key, 'original', 1, p_content_type, p_byte_size, p_sha256,
    public.kicklive_asset_visibility(p_entity_kind), 'ready', p_source_url, now(), v_uid
  ) returning * into v_asset;

  v_url := '/api/media/assets/' || v_asset.object_key;
  v_url_col := public.kicklive_asset_url_column(p_entity_kind);
  if v_url_col is not null then
    execute format('update public.%I set %I = $1 where id::text = $2',
      case p_entity_kind when 'users' then 'profiles' else p_entity_kind end, v_url_col)
      using v_url, p_entity_id;
    insert into public.media_operations (actor, action, asset_id, entity_kind, entity_id, object_key, detail)
    values (v_uid, 'migration_attach', v_asset.id, p_entity_kind, p_entity_id, p_object_key,
            jsonb_build_object('from', p_source_url, 'to', v_url));
  end if;

  return jsonb_build_object('status', 'migrated', 'asset', to_jsonb(v_asset), 'url', v_url);
end;
$fn$;
comment on function public.kicklive_record_migrated_asset(text, text, text, text, bigint, text, text, text, text) is
  'Idempotent record of one migrated Supabase Storage object. Attaches the entity URL only for outcome=migrated, so a failure leaves the working legacy URL in place.';

-- ---------------------------------------------------------------------------
-- 13.  RLS posture + grants
-- ---------------------------------------------------------------------------
-- media_assets has no policies and no direct grants: it is readable only through
-- the functions above, which carry their own authorization. Enabling RLS anyway
-- means "deny by default" is true even if a later migration grants `select` and
-- forgets a policy — the failure mode that RLS exists to catch.
alter table public.media_assets enable row level security;
alter table public.media_operations enable row level security;

revoke all on table public.media_assets from anon, authenticated, service_role;
revoke all on table public.media_operations from anon, authenticated, service_role;

-- The Worker uses the service role and cannot be denied by a client policy, but
-- it does need the grant, and it is deliberately narrow: insert and select, no
-- update and no delete. `update` and `delete` on the registry belong to the
-- functions, which is what keeps a status transition from skipping its
-- bookkeeping. media_operations is insert/select only for the same reason — an
-- audit trail an application can edit is a suggestion.
grant select, insert on table public.media_assets to service_role;
grant select, insert on table public.media_operations to service_role;

-- Deliberately no grant to `anon` or `authenticated`: every client-facing read
-- of the registry is a function that filters by owner, and every write is a
-- function that authorizes per kind. A table grant would be a second, unfiltered
-- door that the checks above would then have to police.
do $grant$
declare
  r record;
  n integer := 0;
begin
  for r in
    select p.proname,
           pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    where ns.nspname = 'public'
      and p.prokind = 'f'
      -- The sweep and the migration pre-check are named for what they do, not for
      -- `media_assets`, and a grant loop that misses a function is a 401 on a
      -- route that typechecks — so the list is explicit instead of pattern-only.
      and (p.proname like 'kicklive_%asset%' or p.proname in
           ('kicklive_sweep_media', 'kicklive_migration_seen', 'kicklive_upload_quota_bytes'))
  loop
    -- `from public` alone would have been the Phase 7 mistake: with the default privileges Supabase creates, anon and
    -- authenticated hold their own EXECUTE entries, so the revoke has to name them to mean anything.
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated', r.proname, r.args);
    execute format('grant execute on function public.%I(%s) to service_role', r.proname, r.args);
    -- The four the browser calls directly, with identity from auth.uid() inside.
    if r.proname in ('kicklive_reserve_asset_upload', 'kicklive_finalize_asset_upload',
                     'kicklive_entity_assets', 'kicklive_delete_asset', 'kicklive_restore_asset') then
      execute format('grant execute on function public.%I(%s) to authenticated', r.proname, r.args);
    end if;
    -- The one anonymous write in the product, re-granted by name because the revoke above now takes it too.
    if r.proname in ('kicklive_record_media_view', 'kicklive_asset_url_column') then
      execute format('grant execute on function public.%I(%s) to anon, authenticated', r.proname, r.args);
    end if;
    n := n + 1;
  end loop;
  raise notice 'kicklive: media grants applied to % asset functions', n;
end
$grant$;

-- ---------------------------------------------------------------------------
-- 14.  verification
-- ---------------------------------------------------------------------------
-- The Phase 5 lesson, applied: every check below is derived from the catalog, so
-- a function that was renamed or forgotten fails this block rather than shipping.
do $verify$
declare
  r record;
  n bigint;
  expected text[] := array[
    'kicklive_asset_object_key', 'kicklive_asset_visibility', 'kicklive_asset_url_column',
    'kicklive_upload_quota_bytes', 'kicklive_reserve_asset_upload', 'kicklive_finalize_asset_upload',
    'kicklive_asset_for_key', 'kicklive_asset_authorized', 'kicklive_entity_assets',
    'kicklive_delete_asset', 'kicklive_restore_asset', 'kicklive_sweep_media',
    'kicklive_reconcile_assets', 'kicklive_asset_diagnostics', 'kicklive_record_migrated_asset',
    'kicklive_migration_seen'
  ];
begin
  for r in select unnest(expected) as name loop
    if to_regclass('public.media_assets') is null then
      raise exception 'kicklive migration verification failed: public.media_assets does not exist (function %)', r.name;
    end if;
    select count(*) into n from pg_proc p
      join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public' and p.proname = r.name;
    if n = 0 then
      raise exception 'kicklive migration verification failed: public.% is missing', r.name;
    end if;
  end loop;

  -- The definer invariant, the same one as Phase 5: a function that reads the
  -- registry on a client's behalf must pin its search_path or a malicious
  -- `media_assets` in another schema wins.
  for r in
    select p.proname
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    where ns.nspname = 'public'
      and p.prokind = 'f'
      and (p.proname like 'kicklive_%asset%' or p.proname in ('kicklive_sweep_media', 'kicklive_migration_seen', 'can_manage_team'))
      and p.prosecdef = false
      -- The four pure helpers have no privilege to inherit and nothing to leak.
      and p.proname not in ('kicklive_asset_object_key', 'kicklive_asset_visibility',
                            'kicklive_asset_url_column', 'kicklive_upload_quota_bytes')
  loop
    raise exception 'kicklive migration verification failed: % must be security definer', r.proname;
  end loop;
  for r in
    select p.proname
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    where ns.nspname = 'public'
      and p.prokind = 'f'
      and p.proname like 'kicklive_%asset%'
      and p.proconfig::text not like '%search_path=public%'
  loop
    raise exception 'kicklive migration verification failed: % must pin search_path', r.proname;
  end loop;

  -- No policy on media_assets: the table is reachable only through functions.
  select count(*) into n from pg_policies where schemaname = 'public' and tablename = 'media_assets';
  if n <> 0 then
    raise exception 'kicklive migration verification failed: media_assets must have no policies, found %', n;
  end if;

  -- The invariant that makes replacement safe, and the one that makes an
  -- idempotent finalize possible.
  select count(*) into n from pg_indexes where schemaname = 'public' and tablename = 'media_assets'
   and indexname = 'media_assets_one_ready_per_slot_idx';
  if n <> 1 then
    raise exception 'kicklive migration verification failed: media_assets_one_ready_per_slot_idx missing';
  end if;

  -- No client role holds any table privilege on the registry: writes go through
  -- the functions, which is what keeps a status transition from skipping its
  -- bookkeeping, and reads go through functions that filter by owner. If this
  -- ever fires, a later migration has handed the browser a path around the
  -- authorization checks.
  select count(*) into n from information_schema.role_table_grants
   where table_schema = 'public' and table_name = 'media_assets'
     and grantee in ('anon', 'authenticated');
  if n <> 0 then
    raise exception 'kicklive migration verification failed: client roles hold % grant(s) on media_assets', n;
  end if;

  raise notice 'kicklive: media registry verified (% functions, % policies on media_assets)',
    array_length(expected, 1), n;
end
$verify$;

commit;

notify pgrst, 'reload schema';
;

-- <<< END section 6: supabase/migrations/20260912120000_phase6_r2_media.sql <<<

-- >>> BEGIN section 7: supabase/migrations/20260913120000_phase7_advertising.sql >>>
SELECT '7 / 10: supabase/migrations/20260913120000_phase7_advertising.sql' AS kicklive_sql_section;

-- ═══════════════════════════════════════════════════════════════════════════
--  Kick Live · Phase 7 migration 1/1 — advertising and sponsorship infrastructure
--  Target: Postgres 15+ (Supabase). Idempotent. Additive.
--  No DROP TABLE, no DROP COLUMN, no DELETE against any pre-existing table, and no policy that gives a
--  browser role a path into these rows. The one destructive-looking statement is the swap of
--  `media_assets_kind_check` (drop + re-add) to admit the `advertisements` kind, which is the widening
--  Phase 6's own comment reserved for this file; it replaces a CHECK with a strictly larger one, so no
--  existing row can become invalid and nothing stored is touched.
--
--  WHAT THIS IS. A controlled placement platform, not an ad network. Seven tables (advertisers,
--  advertisement_campaigns, advertisements, ad_placements, advertisement_placements, ad_events,
--  advertisement_analytics) plus a status matrix, one deliberate widening of Phase 6's media registry so a
--  creative can be stored with its versioning, retention and reconciliation intact, and 28 `kicklive_ad_*`
--  functions that own every decision a client must not make: who may be an advertiser, when an
--  advertisement is eligible, what a public reader is allowed to see, whether a click or an impression
--  counts, and when the raw event log is forgotten.
--
--  WHAT THIS IS NOT, and each absence is a decision rather than an omission:
--    · no billing, invoicing or payment processing. `budget_amount` is a *reference* figure an admin
--      types, and nothing computes money from it. A number in this schema is never an invoice.
--    · no auction, no bidding, no realtime ranking. Rotation is a weighted lottery drawn once per cache
--      interval (§ROTATION), the cheapest thing that stops one advertiser monopolising a slot: one `md5`
--      per candidate and no state.
--    · no behavioural profiling. Targeting is per-request *content* context (page, competition, season,
--      team, match, time of day) over a closed key set. `ad_events` holds no IP, no user agent, no
--      account, no device and no cookie; its deduplication key is a per-day salted digest, deleted after
--      30 days.
--    · no client-side authority: the browser never decides that an advertisement is active, eligible or
--      countable. It asks for a placement and receives what the database says may be shown.
--
--  THE PLACEMENT RULE, which is what makes this infrastructure rather than a feature: no page contains an
--  advertisement. A page contains a *slot*, named by a code in `ad_placements`, and the slot renders
--  nothing at all until an administrator activates an advertisement for it. Apply this migration with zero
--  active campaigns and the app is pixel-identical to today — which is the property the brief asks for
--  when it says advertising must not cost performance, UX, live-match reliability, privacy or security.
--  The default state of this system is off, and it is off in the data, not behind a flag.
--
--  WHY A FUNCTION AND NOT RLS POLICIES FOR THE PUBLIC READ. Serving needs a decision no policy can
--  express — "of the twelve eligible creatives in this slot, show these three, rotated, and never one
--  whose daily cap is spent" — so it is a function: `kicklive_ad_serve`, granted to `anon`, whose result
--  is a hand-built object with exactly the keys a stranger may see. `budget_amount`, `internal_notes`,
--  `contact_*`, `priority`, `weight`, every non-`active` status and every row of `advertisers` are
--  unreachable from it, and no ad table grants a client role any privilege at all: with RLS on and no
--  policies, a read grant would be a door rather than a view, so the only thing a browser may do to
--  advertising is ask for a placement and report what it saw, both through a function. The verify block
--  refuses to install a leak.
--
--  APPLIES AFTER: 20260912120000 (Phase 6, media on R2). Phase 6 reserved the `advertisements/` key
--  prefix and said in its own comment that "Phase 7 adds it alongside its own tables with one alter
--  statement" — this is that statement. Nothing in Phase 6's file is edited: a fresh install runs both
--  files in timestamp order and converges, and so does a database that already applied Phase 6.
-- ═══════════════════════════════════════════════════════════════════════════

begin;

-- ─────────────────────────────────────────────────────────────────────────────
-- 0. VALIDATION PRIMITIVES — FIRST, because the table CHECKs below call them
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Three small IMMUTABLE predicates, defined ahead of the tables and functions that use them so each rule
-- is stated once. They are immutable and do no lookup, which is what lets a table CHECK call
-- `kicklive_ad_http_url_ok` without the CHECK turning into a query.

create or replace function public.kicklive_ad_http_url_ok(p_url text)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- Step 19: "malicious destination URLs where practical". Practical here is four things this function can
  -- decide with no network and no blocklist that rots:
  --   · https only. Not "http is fine on staging": an ad that links to http is a downgrade an attacker
  --     finishes on the same wifi as the club's fans, and every sponsor landing page has had https for a
  --     decade.
  --   · a host with a dot in it, and no userinfo before the first path slash — because
  --     `https://kicklive.football@evil.test/` is a valid URL whose host is not the one a reader sees, and
  --     rejecting `@` there makes that unconstructible rather than filtered.
  --   · no scheme a browser executes (javascript:, data:, vbscript:, file:) and no protocol-relative form,
  --     which would inherit whatever scheme the page happens to be on.
  --   · a length bound, because `href` is a string a template interpolates and 2 kB of base64 in a data:
  --     URL is only refused here, not downstream.
  -- What is deliberately NOT done: no domain allowlist and no reachability probe. An allowlist turns every
  -- new sponsor into a migration, and a probe from a write path is an SSRF request with a friendly face.
  -- Host reputation is a human approval decision — which is what `approved_by` is for.
  select p_url is null
      or (
        char_length(p_url) <= 2000
        and p_url ~* '^https://[^\s<>"'']+$'
        -- Only the one scheme above, so no second-colon form and no `http:` slipped in as a suffix.
        and (length(p_url) - length(replace(p_url, ':', ''))) = 1
        and position('@' in split_part(split_part(p_url, '//', 2), '/', 1)) = 0
        and split_part(split_part(p_url, '//', 2), '/', 1) like '%.%'
        and position('..' in p_url) = 0
      )
$fn$;

create or replace function public.kicklive_ad_image_ref_ok(p_url text)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- Two legal shapes, and the difference between them is not cosmetic:
  --   · a managed asset path — what Phase 6's upload returns, relative on purpose (the same decision as
  --     `mediaPolicy.ts#assetPathFor`) so one row works on dev, staging and production. This is the shape
  --     that has a content hash, a size cap, a format sniff, a version and a retention window behind it.
  --   · an external https URL, for the sponsor who already hosts its banner elsewhere. It gets none of
  --     those things from us, which is why an admin has to approve it, and why `media_asset_id` — not
  --     this column — is what an integrity statement can be made about.
  -- No protocol-relative `//host/path` and no `http:`, for the same reason as above: a stored URL is a URL
  -- every visitor loads, forever.
  select p_url is null
      -- No `{2,509}` inside the pattern: Postgres' regex engine caps a repetition count at 255, and the
      -- complaint arrives at the first insert rather than at CREATE TABLE. The length rule is a predicate.
      or (p_url ~ '^/api/media/assets/[a-z0-9][a-z0-9._/-]{2,}$' and char_length(p_url) <= 600)
      or public.kicklive_ad_http_url_ok(p_url)
$fn$;

create or replace function public.kicklive_ad_targeting_ok(p_targeting jsonb)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- §TARGETING, and the closed key set *is* the privacy control. Six content dimensions: which
  -- competition, which season, which teams, which match, which page type, and which part of the day
  -- (the pharmacy that only wants evening fixtures is the whole reason that last one exists). There is
  -- no key for age, gender, interest, device, history or identity, so an advertiser cannot ask for one —
  -- and changing that is a schema migration somebody has to review, rather than a jsonb value nobody
  -- looked at.
  --
  -- Values are non-empty arrays of ids or labels: a set, not an expression. Deliberately unsupported:
  -- operators, SQL fragments, regexes, and negation — the last one because an exclusion list turns a
  -- filter into "never show my competitor's placement", which is a different product with a different
  -- argument to have.
  select p_targeting is null
      or (
        jsonb_typeof(p_targeting) = 'object'
        and (
          select count(1) from jsonb_object_keys(p_targeting) k
           where k not in ('competition_ids', 'season_ids', 'team_ids', 'match_ids', 'page_types', 'day_parts')
        ) = 0
        and (
          select count(1) from jsonb_each(p_targeting) e
           where jsonb_typeof(e.value) <> 'array'
              or jsonb_array_length(e.value) = 0
              or jsonb_array_length(e.value) > 64
        ) = 0
        and (
          select count(1) from jsonb_each(p_targeting) e, jsonb_array_elements(e.value) v
           where jsonb_typeof(v.value) not in ('string', 'number')
              or char_length(v.value #>> '{}') > 64
        ) = 0
      )
$fn$;


-- ─────────────────────────────────────────────────────────────────────────────
-- 1. PLACEMENTS — the registry of slots a page may ask for
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Step 3 says "do not hardcode advertisements directly into page components; use placement
-- configuration". That is only true if the slot is a row: an admin can retire `HOME_MIDDLE` or cap
-- `MATCH_PAGE` at one item without a deploy, and a page that asks for a code that is not here gets an
-- empty list rather than an error. The eight codes are the eight a template actually renders — this table
-- never invents a slot the UI cannot show, and the UI never invents a slot the database has not sized
-- (both directions are asserted in tests/unit/phase7-advertising.test.ts).

create table if not exists public.ad_placements (
  code              text        primary key check (code ~ '^[A-Z][A-Z0-9_]{1,31}$'),
  label             text        not null check (char_length(label) between 1 and 60),
  description       text        check (description is null or char_length(description) <= 240),
  page              text        not null check (page in ('home', 'match', 'team', 'news', 'standings', 'any')),
  -- A cap on items, not on desire: a slot that would take six creatives and shows three is still a
  -- slot whose layout was designed for three.
  max_items         integer     not null default 1 check (max_items between 1 and 6),
  -- Height budget in CSS pixels. Recorded because it is the number that makes "must not destroy mobile
  -- usability" checkable when somebody later wants a 970×250 creative in a slot designed for 90.
  height_budget_px  integer     check (height_budget_px is null or height_budget_px between 40 and 600),
  allowed_formats   text[]      not null default array['banner','square','story','sponsor_billboard'],
  -- Slots that sit beside live content carry an extra duty. Nothing enforces this flag in code — the
  -- enforcement is where the slot is placed in the template — but it is stored so that "may this slot
  -- move the scoreboard?" is a query and not a memory.
  yields_to_live    boolean     not null default true,
  is_active         boolean     not null default true,
  sort_order        integer     not null default 0,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
comment on table public.ad_placements is
  'The slots a template may ask for, and the budget each has. A slot that is inactive here answers empty '
  'everywhere, which is how a placement is retired without a deploy.';

-- Seeded, never re-seeded: an admin who sets `max_items` to 1 on `HOME_MIDDLE` must not have it reset to
-- 2 by a re-run. `on conflict do nothing` is the whole of that protection, which is why this table has no
-- upsert function.
insert into public.ad_placements (code, label, description, page, max_items, height_budget_px, allowed_formats, yields_to_live, sort_order) values
  ('HOME_TOP',        'Home — top band',         'Slim band under the header, above the live strip. Renders nothing when no campaign is eligible, and its height is capped so it cannot push live content.', 'home',      1,  90, array['banner','leaderboard','sponsor_billboard'], true,  10),
  ('HOME_MIDDLE',     'Home — between sections', 'Between the live matches and the news rail, inside the scroll.',                              'home',      2, 250, array['banner','square','story'],                      true,  20),
  ('MATCH_PAGE',      'Match page',              'Below the scoreboard on a match page. The scoreboard, the clock and any control are never inside it.', 'match',  1, 160, array['banner','square'],                                true,  30),
  ('TEAM_PAGE',       'Team page',               'Team profile, under the squad block.',                                                        'team',      2, 250, array['banner','square','story'],                      true,  40),
  ('NEWS_PAGE',       'News list',               'The news index, between article cards.',                                                      'news',      2, 250, array['banner','square','story'],                      true,  50),
  ('STANDINGS',       'Standings',               'Beside or under the table on /tables.',                                                       'standings', 1, 250, array['square','story','banner'],                      true,  60),
  ('BETWEEN_CONTENT', 'Inline between content',  'One item inside an article body or a list. The only slot allowed to interrupt reading, so it is capped at one and always labelled.', 'any', 1, 300, array['inline','square','banner'], true, 70),
  ('SPONSOR_BANNER',  'Sponsor strip',           'The league/club sponsor strip. Persistent by design, so the format is a billboard rather than a rotating banner.', 'any', 4, 120, array['sponsor_billboard','square'],           true,  80)
on conflict (code) do nothing;

-- ─────────────────────────────────────────────────────────────────────────────
-- 2. ADVERTISERS
-- ─────────────────────────────────────────────────────────────────────────────
--
-- A business, an organisation, a pharmacy, a brand, an event organiser, a local business, or a sponsor:
-- one table with a `kind`, because they are one workflow (someone proposes, someone approves, something
-- runs, something is measured). A separate `sponsors` table beside this one would differ only in which
-- columns are nullable, and that is how a schema grows a second path to the same approval. `contact_*`
-- and `internal_notes` are admin-only by construction: no function a browser can call mentions them.

create table if not exists public.advertisers (
  id              uuid          primary key default gen_random_uuid(),
  business_name   text          not null check (char_length(business_name) between 2 and 120),
  kind            text          not null default 'business'
                  check (kind in ('business', 'organization', 'pharmacy', 'brand', 'event_organizer', 'local_business', 'sponsor')),
  contact_name    text          check (contact_name   is null or char_length(contact_name)   <= 120),
  contact_email   text          check (contact_email  is null or char_length(contact_email)  <= 320),
  contact_phone   text          check (contact_phone  is null or char_length(contact_phone)  <= 40),
  website_url     text          check (website_url is null or public.kicklive_ad_http_url_ok(website_url)),
  logo_url        text          check (logo_url is null or public.kicklive_ad_image_ref_ok(logo_url)),
  city            text          check (city     is null or char_length(city)     <= 80),
  region          text          check (region    is null or char_length(region)  <= 80),
  -- A sponsorship tier as text, because there is no `sponsor_packages` table yet (deferred; see the
  -- architecture note §Deferred). The legacy free-text sponsor field maps here when that data is moved.
  tier            text          check (tier     is null or char_length(tier)     <= 40),
  status          text          not null default 'draft'
                  check (status in ('draft', 'pending', 'approved', 'suspended', 'archived')),
  internal_notes  text          check (internal_notes is null or char_length(internal_notes) <= 2000),
  created_by      uuid          references public.profiles(id) on delete set null,
  approved_by     uuid          references public.profiles(id) on delete set null,
  approved_at     timestamptz,
  created_at      timestamptz   not null default now(),
  updated_at      timestamptz   not null default now(),
  -- An approval without a person and a time is a claim with no evidence. This is the audit trail, not
  -- decoration: `approved` cannot be stored at all without both.
  constraint advertisers_approval_consistent check (
    status <> 'approved' or (approved_by is not null and approved_at is not null)
  )
);
create index if not exists advertisers_status_idx on public.advertisers (status, created_at desc);

-- ─────────────────────────────────────────────────────────────────────────────
-- 3. CAMPAIGNS
-- ─────────────────────────────────────────────────────────────────────────────
--
-- The *flight*: dates, a budget as a reference figure, and a status that can stop everything under it at
-- once. The campaign window is the hard bound — an advertisement is never eligible outside its campaign's--  dates, even if its own dates allow it — because "pause the campaign" has to mean stop today, and a
-- system where a paused campaign's ads can still serve is a system where an advertiser's complaint has no
-- answer.

create table if not exists public.advertisement_campaigns (
  id                uuid          primary key default gen_random_uuid(),
  advertiser_id     uuid          not null references public.advertisers(id) on delete restrict,
  name              text          not null check (char_length(name) between 2 and 120),
  starts_at         timestamptz   not null,
  ends_at           timestamptz   not null,
  -- Reference figures. `numeric(12,2)` with a free ISO code because the value has to survive both GHS and
  -- USD without a currency table nobody asked for. Nothing here converts, aggregates toward an invoice,
  -- or rounds: the column exists so "we agreed 4000 for the season" is written down somewhere the admin
  -- can read, and it is *not* the basis of a charge.
  budget_amount     numeric(12,2) check (budget_amount is null or budget_amount >= 0),
  budget_currency   text          check (budget_currency is null or budget_currency ~ '^[A-Z]{3}$'),
  billing_reference text          check (billing_reference is null or char_length(billing_reference) <= 80),
  status            text          not null default 'draft'
                    check (status in ('draft', 'pending', 'active', 'paused', 'completed', 'archived')),
  internal_notes    text          check (internal_notes is null or char_length(internal_notes) <= 2000),
  created_by        uuid          references public.profiles(id) on delete set null,
  created_at        timestamptz   not null default now(),
  updated_at        timestamptz   not null default now(),
  constraint campaign_window_ordered check (ends_at > starts_at),
  constraint campaign_currency_needs_amount check (budget_currency is null or budget_amount is not null),
  -- Only an ordering rule lives here. "A flight may not be marked completed before its end date" is *also* a
  -- rule about time, but writing it as a CHECK would freeze `now()` into a permanent invariant: the row is
  -- legal when it is written and, since `ends_at` is in the past by then, still legal forever — so the
  -- constraint can never catch the thing it appears to guard, while a restore into a database with an
  -- older clock would reject it for no reason. The rule belongs to the act of setting the status, and it
  -- lives in `kicklive_ad_set_campaign_status` as `FLIGHT_HAS_NOT_ENDED`.
  constraint campaign_window_has_dates check (ends_at is not null or starts_at is null)
);
create index if not exists campaigns_advertiser_idx on public.advertisement_campaigns (advertiser_id, status, ends_at);
create index if not exists campaigns_status_window_idx on public.advertisement_campaigns (status, starts_at, ends_at);

-- ─────────────────────────────────────────────────────────────────────────────
-- 4. ADVERTISEMENTS
-- ─────────────────────────────────────────────────────────────────────────────
--
-- The creative, its schedule, its priority/weight and its targeting. Two design points worth the
-- paragraph:
--
-- (a) `status` and *eligibility* are different questions and the app must never confuse them. Status is
--     what an admin last left it as; eligibility is status ∧ window ∧ campaign ∧ placement ∧ advertiser
--     approval ∧ cap ∧ targeting, computed by `kicklive_ad_eligibility`. The serving path asks only the
--     second, so a row that says `active` but ended an hour ago cannot be shown — which is the exact case
--     a status-only system gets wrong silently, and why `status` is not indexed for serving.
-- (b) `destination_url` is validated rather than trusted, because it is the one string in this schema a
--     browser will navigate to on a click. `rel="sponsored nofollow noopener noreferrer"` and
--     `target="_blank"` are set by the template and are NOT stored here: the disclosure label's
--     *rendering* and the link relationship are presentation rules, and a presentation rule kept in data
--     is a presentation rule that can be edited away. `label` is the one exception, and only because the
--     brief wants four approved wordings rather than free text.

create table if not exists public.advertisements (
  id                  uuid          primary key default gen_random_uuid(),
  campaign_id         uuid          not null references public.advertisement_campaigns(id) on delete restrict,
  title               text          not null check (char_length(title) between 2 and 90),
  body                text          check (body is null or char_length(body) <= 240),
  format              text          not null default 'banner'
                      check (format in ('banner', 'square', 'story', 'inline', 'leaderboard', 'sponsor_billboard')),
  -- The creative. `media_asset_id` is the R2-backed asset (the normal case, and the only one with
  -- versioning, retention, a content hash and a size cap behind it); `image_url` is what gets rendered —
  -- a `/api/media/assets/<key>` path when the asset was published through Phase 6, or an external https
  -- URL for the "we already host it" case. Both are stored because the render path must not need a join,
  -- and `media_asset_id` is kept because integrity and retention must be able to name the asset.
  -- `media_assets.id` is a bigint identity, not a uuid: the FK follows the referenced column's type.
  media_asset_id      bigint        references public.media_assets(id) on delete set null,
  image_url           text          check (image_url is null or public.kicklive_ad_image_ref_ok(image_url)),
  video_url           text          check (video_url is null or public.kicklive_ad_http_url_ok(video_url)),
  destination_url     text          not null check (public.kicklive_ad_http_url_ok(destination_url)),
  destination_host    text generated always as (
                        lower(split_part(split_part(destination_url, '//', 2), '/', 1))
                      ) stored,
  alt_text            text          check (alt_text is null or char_length(alt_text) <= 300),
  status              text          not null default 'draft'
                      check (status in ('draft', 'pending', 'active', 'paused', 'expired', 'archived')),
  -- Priority is the deterministic half of the order (a paid season-long sponsor outranks a one-week
  -- experiment); weight is the proportional half (see §ROTATION). Both are 0..100 so an admin can reason
  -- about them without a manual, and neither is a bid.
  priority            integer       not null default 50 check (priority between 0 and 100),
  weight              integer       not null default 10 check (weight between 1 and 100),
  starts_at           timestamptz,
  ends_at             timestamptz,
  targeting           jsonb         not null default '{}'::jsonb,
  daily_impression_cap integer       check (daily_impression_cap is null or daily_impression_cap between 1 and 10000000),
  -- Step 18's disclosure. A closed set, so a creative cannot be labelled "News" or left unlabelled: the
  -- four values are all admissions that this is paid.
  label               text          not null default 'Sponsored'
                      check (label in ('Sponsored', 'Advertisement', 'Promoted', 'Partner content')),
  internal_notes      text          check (internal_notes is null or char_length(internal_notes) <= 2000),
  created_by          uuid          references public.profiles(id) on delete set null,
  approved_by         uuid          references public.profiles(id) on delete set null,
  approved_at         timestamptz,
  -- The last reason activation was refused, on the row, so the list can answer "why can't I turn this
  -- on?" without re-running the check or reading a log line that has already rolled away.
  activation_error    text,
  created_at          timestamptz   not null default now(),
  updated_at          timestamptz   not null default now(),
  constraint ad_window_ordered check (ends_at is null or starts_at is null or ends_at > starts_at),
  -- A creative that is *being served* has to be complete. A draft may be a placeholder; an active row
  -- with no image, no alt text and no approver is a broken or unattributable advertisement on a public
  -- page, and this CHECK is the last line after `kicklive_ad_set_status`'s friendlier preconditions.
  -- (The window-vs-campaign containment is enforced in the functions instead: a CHECK cannot contain a
  -- subquery, and a trigger that re-validates on campaign edit would be a third place to keep in sync.)
  constraint ad_activation_complete check (
    status <> 'active' or (
      (image_url is not null or media_asset_id is not null)
      and alt_text is not null
      and char_length(trim(alt_text)) >= 3
      and approved_by is not null
      and approved_at is not null
    )
  ),
  -- (The one-title-per-flight rule is a unique *index* below rather than a table constraint: Postgres
  -- accepts only column lists in `unique (...)`, and `lower(title)` is an expression.)
  constraint ad_targeting_object check (jsonb_typeof(targeting) = 'object')
);
-- Two copies of the same creative in one flight is never deliberate; it is a duplicate that halves each
-- one's measured performance and doubles the impression cap's meaning. Case-insensitive, because "Ramadan
-- Sale" and "RAMADAN SALE" entered on two days is the same banner.
create unique index if not exists advertisements_one_title_per_campaign_idx
  on public.advertisements (campaign_id, lower(title));
create index if not exists advertisements_status_window_idx on public.advertisements (status, starts_at, ends_at);
create index if not exists advertisements_campaign_idx on public.advertisements (campaign_id, status);
-- What the serving path filters on, as one partial index: everything not being served stays out of it.
create index if not exists advertisements_serving_idx on public.advertisements (status, campaign_id) where status = 'active';

-- ─────────────────────────────────────────────────────────────────────────────
-- 5. ADVERTISEMENT ↔ PLACEMENT
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Which slots a creative runs in, and the overrides that only make sense per slot (a tighter cap on the
-- busy one, a different priority in the strip). Without this table an ad would have to be one row per
-- slot, and its analytics would be split by an accident of data entry.

create table if not exists public.advertisement_placements (
  advertisement_id     uuid        not null references public.advertisements(id) on delete cascade,
  placement_code       text        not null references public.ad_placements(code) on delete restrict,
  priority             integer     check (priority is null or priority between 0 and 100),
  weight               integer     check (weight is null or weight between 1 and 100),
  daily_impression_cap integer     check (daily_impression_cap is null or daily_impression_cap between 1 and 10000000),
  starts_at            timestamptz,
  ends_at              timestamptz,
  is_active            boolean     not null default true,
  created_at           timestamptz not null default now(),
  primary key (advertisement_id, placement_code),
  constraint placement_window_ordered check (ends_at is null or starts_at is null or ends_at > starts_at)
);
create index if not exists ad_placements_by_code_idx on public.advertisement_placements (placement_code, is_active);
comment on table public.advertisement_placements is
  'Which slot a creative runs in. The format/slot compatibility rule lives in a trigger rather than a '
  'CHECK, because a CHECK may not read another table and a format can change after the assignment.';

-- The compatibility rule, as a trigger: a `story` creative cannot be pointed at a slot that only accepts
-- `banner`, and a slot's `allowed_formats` cannot be narrowed from under a creative already assigned to
-- it. Two directions, one function, because the second one is the case that would otherwise leave
-- eligibility refusing something an admin can see as "active in HOME_TOP" in the UI.
create or replace function public.kicklive_ad_guard_placement_format()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $fn$
declare
  v_format text;
begin
  -- One trigger per table, and this one is only ever attached to `advertisement_placements`, which is why
  -- `new.advertisement_id` can be read unconditionally: a shared function would have to dispatch on
  -- tg_relid to avoid referencing a column the other table does not have, and that is a much worse way to
  -- say "these are two rules".
  select a.format into v_format from public.advertisements a where a.id = new.advertisement_id;
  if not exists (
    select 1 from public.ad_placements p
     where p.code = new.placement_code
       and coalesce(v_format, 'banner') = any (p.allowed_formats)
  ) then
    raise exception 'placement % does not accept format %', new.placement_code, coalesce(v_format, 'banner')
      using hint = 'Change the creative''s format, or pick a slot that accepts it.';
  end if;
  return new;
end
$fn$;

-- The other direction, as its own function: narrowing a slot's formats must not strand the creatives
-- already assigned to it, because eligibility would then refuse rows the admin can see as "active in
-- HOME_TOP" and nothing in the UI would say why.
create or replace function public.kicklive_ad_guard_slot_formats()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $fn$
begin
  if exists (
    select 1 from public.advertisement_placements x
      join public.advertisements a on a.id = x.advertisement_id
     where x.placement_code = new.code
       and not (a.format = any (new.allowed_formats))
  ) then
    raise exception 'a creative assigned to this slot uses a format the new allowed_formats list drops'
      using hint = 'Move the creative out of the slot first, or keep the format in allowed_formats.';
  end if;
  return new;
end
$fn$;

create or replace function public.kicklive_ad_guard_advertisement_format()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $fn$
begin
  -- A creative being edited to a format its slots reject: refuse the edit rather than let eligibility
  -- silently stop serving something the admin believes is live.
  if pg_trigger_depth() > 1 then
    return new;
  end if;
  if new.format is distinct from old.format and exists (
    select 1 from public.advertisement_placements x
    join public.ad_placements p on p.code = x.placement_code
     where x.advertisement_id = new.id and not (new.format = any (p.allowed_formats))
  ) then
    raise exception 'format % is not allowed by a slot this creative is assigned to', new.format
      using hint = 'Remove the slot first, or choose a format the slot accepts.';
  end if;
  return new;
end
$fn$;

-- `on delete restrict` from here: an ad with a history is archived, not removed. Cascade would take the
-- rollups with it, and the rollups are the only thing that outlives the raw log.
-- `drop trigger if exists` first, exactly as Phase 6's triggers do: `create trigger` has no `or replace`
-- form, so a file that is meant to be re-runnable cannot simply create one — and a migration that fails on
-- the second run is a migration nobody can apply twice.
drop trigger if exists trg_ad_placement_format_guard on public.advertisement_placements;
create trigger trg_ad_placement_format_guard
  before insert or update on public.advertisement_placements
  for each row execute function public.kicklive_ad_guard_placement_format();
drop trigger if exists trg_ad_slot_formats_guard on public.ad_placements;
create trigger trg_ad_slot_formats_guard
  before update of allowed_formats on public.ad_placements
  for each row execute function public.kicklive_ad_guard_slot_formats();
drop trigger if exists trg_ad_advertisement_format_guard on public.advertisements;
create trigger trg_ad_advertisement_format_guard
  before update on public.advertisements
  for each row execute function public.kicklive_ad_guard_advertisement_format();

-- ─────────────────────────────────────────────────────────────────────────────
-- 6. EVENTS AND ANALYTICS
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Two tables, because they answer different questions on different lifetimes:
--
--   · `ad_events` is the raw log, and it is disposable. What makes it disposable rather than a privacy
--     liability is that there is nothing in it worth keeping: no IP, no user agent, no account, no
--     device, and `occurred_at` exists only to bound dedupe windows (the day is the grain anything
--     aggregates at). `viewer_key` is a 16-hex truncated digest whose salt changes daily, so it cannot be
--     joined across days even by somebody holding the table. Deleted after 30 days by `kicklive_ad_sweep`.
--   · `advertisement_analytics` is what the admin screens read: one row per (creative, slot, UTC day),
--     counts only. It stands on its own after the log is gone, which is why the rollup moves in the same
--     statement as the insert rather than being derived from a table that is being deleted from.
--
-- Deliberately absent: `user_id`. Recording *who* saw an ad is a different product, with a different
-- legal posture, and no requirement in this brief. The dedupe that needs a viewer identity is served by a
-- per-session digest instead, and the consequence is stated plainly in the architecture note: the
-- impression count is a floor, not an exact number.

create table if not exists public.ad_events (
  id               bigint generated always as identity primary key,
  advertisement_id uuid        not null references public.advertisements(id) on delete cascade,
  -- Denormalised on purpose: "how many impressions did this flight get" is the first question anyone
  -- asks, and it must not need a join into a table that is being pruned.
  campaign_id      uuid        not null,
  -- No FK to ad_placements by design: a retired slot code must keep its history readable, and a
  -- dangling-but-labelled code is the honest shape for that.
  placement_code   text        not null check (placement_code ~ '^[A-Z][A-Z0-9_]{1,31}$'),
  event            text        not null check (event in ('impression', 'click')),
  occurred_at      timestamptz not null default now(),
  day              date        not null default ((now() at time zone 'utc')::date),
  viewer_key       text        not null check (viewer_key ~ '^[0-9a-f]{16}$'),
  -- Computed by the insert functions and never accepted from a caller.
  dedupe_key       text        not null,
  counted          boolean     not null default true,
  created_at       timestamptz not null default now(),
  constraint ad_events_dedupe_unique unique (dedupe_key)
);
create index if not exists ad_events_ad_day_idx on public.ad_events (advertisement_id, day, placement_code);
-- The retention delete is `where occurred_at < now() - interval '30 days'`; this partial index is what
-- keeps that from being a scan of the largest table in this migration.
create index if not exists ad_events_retention_idx on public.ad_events (occurred_at) where counted;
comment on table public.ad_events is
  'Impression and click events, deduplicated, with no personal data in them. Raw rows are retained 30 '
  'days by public.kicklive_ad_sweep(); the numbers that outlive them are in advertisement_analytics.';

create table if not exists public.advertisement_analytics (
  advertisement_id uuid        not null references public.advertisements(id) on delete cascade,
  placement_code   text        not null,
  day              date        not null,
  impressions      bigint      not null default 0 check (impressions >= 0),
  -- No upper bound relating clicks to impressions, and that is a real decision rather than an omission:
  -- a click is honoured on a wider window than an impression (see §COUNTING), so clicks legitimately can
  -- exceed impressions when the impression was deduped or refused. A CHECK here would silently discard
  -- the most meaningful number in the system.
  clicks           bigint      not null default 0 check (clicks >= 0),
  updated_at       timestamptz not null default now(),
  primary key (advertisement_id, placement_code, day)
);
create index if not exists analytics_day_idx on public.advertisement_analytics (day desc);
comment on table public.advertisement_analytics is
  'The rollup the admin screens read. Counts only; CTR is computed when asked for and stored nowhere, '
  'because a stored ratio is a second truth that can disagree with the counts it came from.';

-- ─────────────────────────────────────────────────────────────────────────────
-- 7. ELIGIBILITY — the one definition, used by serving, by counting and by the admin screens
-- ─────────────────────────────────────────────────────────────────────────────
--
-- One function owns "may this creative be shown, right now, in this slot, for this context". Step 5 says
-- the server decides whether an advertisement is active; the way to make that true rather than local is
-- to let nothing else compute it. The serving RPC, the event validator, the admin list's `serving`
-- column and the "why isn't this showing?" answer all go through here, and the reason is returned so a
-- refusal is explainable to the operator instead of being a mystery behind a cache.
--
-- It returns a single jsonb object rather than a row, so it can be called from a WHERE clause as a scalar
-- (a set-returning function there is an error in Postgres) and so every caller reads the same vocabulary.
--
-- `p_now` and `p_horizon_seconds` are parameters rather than `now()` and a constant, which is
-- load-bearing three times over: a test can prove an ad is eligible at 14:59:59 and not at 15:00:01
-- without waiting for anything; the horizon can be set to zero by the event validator (which wants
-- "is it live" rather than "will it survive a cache"); and the expiry sweep and the serving path are then
-- provably asking the same question.

create or replace function public.kicklive_ad_eligibility(
  p_advertisement_id uuid,
  p_placement_code   text,
  p_context          jsonb default '{}'::jsonb,
  p_now              timestamptz default now(),
  p_horizon_seconds  integer default 90
)
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  with ad as (
    -- The join chain is inner rather than left, so a campaign or advertiser that has gone makes the
    -- creative invisible rather than visible with a null status. The FKs make that unreachable by normal
    -- means (nothing here can delete an advertiser), which is exactly why the conservative direction is
    -- cheap enough to prefer anyway.
    select a.id, a.status, a.format, a.priority, a.weight, a.image_url, a.media_asset_id,
           a.starts_at, a.ends_at, a.targeting, a.daily_impression_cap,
           c.status as campaign_status, c.starts_at as campaign_starts, c.ends_at as campaign_ends,
           av.status as advertiser_status
      from public.advertisements a
      join public.advertisement_campaigns c on c.id = a.campaign_id
      join public.advertisers av              on av.id = c.advertiser_id
     where a.id = p_advertisement_id
  ),
  ap as (
    select x.priority, x.weight, x.daily_impression_cap, x.is_active, x.starts_at, x.ends_at
      from public.advertisement_placements x
     where x.advertisement_id = p_advertisement_id and x.placement_code = p_placement_code
  ),
  slot as (
    select p.is_active, p.allowed_formats, p.max_items
      from public.ad_placements p where p.code = p_placement_code
  ),
  today as (
    select coalesce(sum(an.impressions), 0)::bigint as impressions
      from public.advertisement_analytics an
     where an.advertisement_id = p_advertisement_id
       and an.placement_code = p_placement_code
       and an.day = (p_now at time zone 'utc')::date
  ),
  verdict as (
    -- The order below is the order an operator reads a refusal in: your data is wrong, then your
    -- schedule, then the switches above you, then "nothing you did".
    select case
      when (select count(1) from ad) = 0                then 'advertisement_not_found'
      when (select count(1) from ap) = 0                then 'not_placed_in_slot'
      when (select count(1) from slot) = 0              then 'slot_unknown'
      when not coalesce((select is_active from slot), false)      then 'slot_disabled'
      when not coalesce((select is_active from ap),  false)       then 'placement_disabled'
      when (select status from ad) <> 'active'                    then 'not_active'
      when (select campaign_status from ad) <> 'active'          then 'campaign_not_active'
      when (select advertiser_status from ad) <> 'approved'      then 'advertiser_not_approved'
      when (select image_url from ad) is null
       and (select media_asset_id from ad) is null               then 'no_creative'
      when (select campaign_starts from ad) > p_now             then 'campaign_not_started'
      when (select campaign_ends  from ad) <= p_now             then 'campaign_ended'
      when (select starts_at from ad) is not null and (select starts_at from ad) > p_now
                                                                then 'not_started'
      -- The horizon rather than `p_now`, and this is the line that makes Step 9 safe: a serving response
      -- may live in a cache for up to `horizon` seconds, so a creative that ends inside that window is
      -- already too late to put in it. An expired advertisement therefore cannot hide behind the cache,
      -- because it can never enter it — no purge, no invalidation, no trust in the CDN.
      when (select ends_at from ad) is not null
           and (select ends_at from ad) <= p_now + make_interval(secs => greatest(coalesce(p_horizon_seconds, 0), 0))
                                                                then 'ends_inside_cache_window'
      when (select starts_at from ap) is not null and (select starts_at from ap) > p_now
                                                                then 'placement_not_started'
      when (select ends_at from ap) is not null and (select ends_at from ap) <= p_now
                                                                then 'placement_ended'
      when not coalesce((select coalesce(a.format, 'banner') = any (s.allowed_formats)
                           from ad a, slot s), false)          then 'slot_refuses_this_format'
      when (select daily_impression_cap from ad) is not null
           and (select impressions from today) >= (select daily_impression_cap from ad)
                                                                then 'daily_cap_reached'
      when (select daily_impression_cap from ap) is not null
           and (select impressions from today) >= (select daily_impression_cap from ap)
                                                                then 'placement_daily_cap_reached'
      when not public.kicklive_ad_targeting_matches((select targeting from ad), p_context, p_now)
                                                                then 'targeting_excludes'
      else 'eligible'
    end as reason
  )
  select jsonb_build_object(
    'advertisement_id', p_advertisement_id,
    'placement_code',   p_placement_code,
    'eligible',         (select reason from verdict) = 'eligible',
    'reason',           (select reason from verdict),
    'slot_max_items',   (select max_items from slot),
    'effective_priority', coalesce((select priority from ap), (select priority from ad)),
    'effective_weight',   coalesce((select weight  from ap), (select weight  from ad)),
    'effective_cap',      coalesce((select daily_impression_cap from ap), (select daily_impression_cap from ad)),
    'impressions_today',  (select impressions from today)
  )
$fn$;

-- The targeting predicate, separate because the admin preview, the serving path and the event validator
-- must evaluate it identically, and because a nested EXISTS inside the CASE above is unreadable.
--
-- A context is what the *page* knows about itself ("match page, match 431, competition 12, season 2026,
-- teams 7 and 9"), never what it knows about the visitor. An empty targeting object matches everything. A
-- targeting key the context cannot answer (a team page has no `match_ids`) does NOT match: the
-- conservative direction, because "targeted at team 7" must not quietly become "shown everywhere" just
-- because the page did not know what a match id was.
create or replace function public.kicklive_ad_targeting_matches(p_targeting jsonb, p_context jsonb, p_now timestamptz default now())
returns boolean
language sql stable
set search_path = public, pg_temp
as $fn$
  with required as (
    select e.key, v.value #>> '{}' as wanted
      from jsonb_each(coalesce(nullif(p_targeting, 'null'::jsonb), '{}'::jsonb)) e,
           jsonb_array_elements(e.value) v
  ),
  supplied as (
    select e.key, v.value #>> '{}' as got
      from jsonb_each(coalesce(nullif(p_context, 'null'::jsonb), '{}'::jsonb)) e,
           jsonb_array_elements(e.value) v
  )
  select case
           when (select count(1) from required) = 0 then true
           when exists (
                    select 1 from (select distinct key from required) rk
                     where not exists (select 1 from supplied s where s.key = rk.key)
                  ) then false
           when exists (
                    select 1 from required r
                     where not exists (select 1 from supplied s where s.key = r.key and s.got = r.wanted)
                  ) then false
           -- `day_parts` is the one derived key, and the *server's* clock decides it. A client-supplied
           -- local time would be both spoofable and wrong for a 22:00 kickoff watched from another
           -- timezone, and "evening" is a statement about the match schedule, not about the viewer.
           when exists (
                    select 1 from required r
                     where r.key = 'day_parts'
                       and r.wanted <> case
                             when extract(hour from p_now) between 5  and 11 then 'morning'
                             when extract(hour from p_now) between 12 and 16 then 'afternoon'
                             when extract(hour from p_now) between 17 and 21 then 'evening'
                             else 'night'
                           end
                  ) then false
           else true
         end
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 8. ROTATION
-- ─────────────────────────────────────────────────────────────────────────────
--
-- The brief asks for controlled rotation and explicitly not an auction, and this is the whole mechanism:
-- each advertisement gets `weight` tickets, every ticket is hashed with the current time bucket, and the
-- lowest hash wins — after priority. So:
--
--   · it is a lottery, not a queue. Nobody gets an exact share; everyone gets a proportional chance. For a
--     banner on a football site that is the difference that does not matter, and it is why there is no
--     scheduler, no counter and no per-viewer state here;
--   · it is stable within a cache interval and changes at the boundary, which is what makes "we rotate"
--     compatible with "we cache for 30 seconds". Those two mechanisms otherwise fight, and the loser is
--     whichever one you noticed second;
--   · it needs no write on a read path. The bucket comes from the clock, so the same request in the same
--     interval answers the same list — which is also what makes a cache hit and a cache miss
--     indistinguishable to a fan, a property you want before you need it;
--   · it is testable: with a pinned bucket the function is pure, so "weight 3 gets roughly three times the
--     exposure of weight 1" is a unit test over a lattice of ids rather than a runtime experiment.
--
-- What is deliberately absent: no learned weighting, no per-advertiser pacing, no bid, no floor, no
-- second-price anything, and no per-person frequency cap — that last one would need per-person state,
-- which is precisely what `ad_events` refuses to hold.

create or replace function public.kicklive_ad_rotation_key(
  p_advertisement_id uuid,
  p_weight integer,
  p_bucket bigint
)
returns text
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- `min` over one hash per ticket: weight 3 gets three chances to land low, so ~3× the exposure of
  -- weight 1 — proportional, not guaranteed. md5 rather than a real RNG because the value only has to be
  -- uniformly spread and reproducible for a bucket; a deterministic draw is what makes the cached and
  -- uncached paths agree, and `random()` would make every cache miss reshuffle the page.
  select min(md5(p_advertisement_id::text || ':' || p_bucket::text || ':' || g::text))
    from generate_series(1, greatest(1, coalesce(p_weight, 1))) g
$fn$;

create or replace function public.kicklive_ad_bucket(p_now timestamptz, p_seconds integer)
returns bigint
language sql immutable
set search_path = public, pg_temp
as $fn$
  -- The interval must equal the serving response's max-age or the two mechanisms argue. `adPolicy.ts`
  -- states the number once, and a test asserts this default agrees with it, so the equality is not a
  -- comment.
  select floor(extract(epoch from p_now) / greatest(coalesce(p_seconds, 30), 1))::bigint
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 9. THE PUBLIC SURFACE
-- ─────────────────────────────────────────────────────────────────────────────
--
-- `kicklive_ad_serve` is the only thing an anonymous browser may ask about advertising. Note what it does
-- NOT take: an advertiser id, a status, a budget, a "show me expired" flag, a limit above the slot's own
-- cap, or a placement that is not active. Everything a caller could use to widen its own view is absent
-- from the signature rather than refused inside it, because a parameter that is refused is one more thing
-- a future refactor can forget to refuse.

create or replace function public.kicklive_ad_serve(
  p_placement_code  text,
  p_context         jsonb default '{}'::jsonb,
  p_limit           integer default null,
  p_now             timestamptz default now(),
  p_horizon_seconds integer default 90
)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_slot   public.ad_placements;
  v_limit  integer;
  v_bucket bigint;
  v_rows   jsonb;
begin
  select * into v_slot from public.ad_placements ap
   where ap.code = p_placement_code and ap.is_active;
  if not found then
    -- Not an error, and that is a deliberate API decision: a page may render a slot that has been
    -- retired, or one that an environment has not seeded yet. The answer in both cases is "nothing", and
    -- a 404 would turn a configuration change into a broken page — with a client-side cache of the 404
    -- for good measure.
    return jsonb_build_object(
      'ok', true,
      'reason', 'slot_unavailable',
      'placement', p_placement_code,
      'items', '[]'::jsonb,
      'rotationBucket', public.kicklive_ad_bucket(coalesce(p_now, now()), 30)
    );
  end if;

  -- A caller may ask for fewer, never more. `max_items` is the slot's promise to the layout; a client
  -- that could raise it could make a page taller than its own design.
  v_limit  := least(coalesce(p_limit, v_slot.max_items), v_slot.max_items);
  v_bucket := public.kicklive_ad_bucket(coalesce(p_now, now()), greatest(coalesce(p_horizon_seconds, 30), 1));

  select coalesce(
    jsonb_agg(jsonb_build_object(
      -- §EXPOSURE. This is the entire public vocabulary of an advertisement: `title`, `body`, an image, an
      -- alt text, a destination, the disclosure label, the slot it belongs to, and the asset version so a
      -- replacement (a new key) is distinguishable without invalidating anything. Not here, and
      -- unreachable by any other client-callable function: the advertiser's name (being named is the
      -- advertiser's choice, and it appears in the copy when they want it), campaign or advertiser ids,
      -- priority, weight, caps, dates, statuses, notes, contacts, budgets, and every row of `advertisers`.
      'id',              e.advertisement_id,
      'title',           e.title,
      'body',            e.body,
      'format',          e.format,
      'image_url',       e.image_url,
      'alt_text',        e.alt_text,
      'destination_url', e.destination_url,
      'label',           e.label,
      'placement',       p_placement_code,
      'asset_version',   e.asset_version
    ) order by e.priority desc nulls last, e.rotation_key),
    '[]'::jsonb
  ) into v_rows
  from (
    select a.id as advertisement_id, a.title, a.body, a.format,
           coalesce(a.image_url, '/api/media/assets/' || ma.object_key) as image_url,
           a.alt_text, a.destination_url, a.label,
           coalesce(ma.version, 1) as asset_version,
           coalesce(ap.priority, a.priority) as priority,
           public.kicklive_ad_rotation_key(a.id, coalesce(ap.weight, a.weight), v_bucket) as rotation_key
      from public.advertisements a
      join public.advertisement_campaigns c    on c.id  = a.campaign_id
      join public.advertisers av               on av.id = c.advertiser_id
      join public.advertisement_placements ap  on ap.advertisement_id = a.id and ap.placement_code = p_placement_code
      left  join public.media_assets ma        on ma.id = a.media_asset_id
     where a.status = 'active'
       and ap.is_active
       and c.status = 'active'
       and av.status = 'approved'
       and (a.starts_at is null or a.starts_at <= p_now)
       and (a.ends_at   is null or a.ends_at   >  p_now + make_interval(secs => coalesce(p_horizon_seconds, 0)))
       and (ap.starts_at is null or ap.starts_at <= p_now)
       and (ap.ends_at   is null or ap.ends_at   >  p_now)
       and (a.daily_impression_cap is null or coalesce((
              select sum(an.impressions) from public.advertisement_analytics an
               where an.advertisement_id = a.id and an.placement_code = p_placement_code
                 and an.day = (p_now at time zone 'utc')::date), 0) < a.daily_impression_cap)
       and public.kicklive_ad_targeting_matches(a.targeting, p_context, p_now)
       -- Whatever the WHERE clause above can express in one pass, the eligibility function re-checks, so
       -- the serving list and the "why is this not showing?" answer cannot disagree about what eligible
       -- means. In a slot with single-digit candidates, one extra call per candidate is the cheap side of
       -- that trade; the expensive side is two definitions drifting.
       and (public.kicklive_ad_eligibility(a.id, p_placement_code, p_context, p_now, p_horizon_seconds)->>'eligible') = 'true'
     order by coalesce(ap.priority, a.priority) desc nulls last,
              public.kicklive_ad_rotation_key(a.id, coalesce(ap.weight, a.weight), v_bucket)
     limit v_limit
  ) e;

  return jsonb_build_object(
    'ok', true,
    'reason', 'served',
    'placement', p_placement_code,
    'items', v_rows,
    'rotationBucket', v_bucket,
    'maxItems', v_slot.max_items
  );
end
$fn$;

-- The operator's answer to "it is not showing": the same eligibility function, kept refusal and all,
-- including statuses a browser cannot see. Written against the same predicate so the two can never
-- disagree about what eligible means, which is the property that makes this screen trustworthy.
create or replace function public.kicklive_ad_explain(
  p_advertisement_id uuid,
  p_placement_code   text default null,
  p_context          jsonb default '{}'::jsonb,
  p_now              timestamptz default now()
)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_code text;
  v_rows jsonb := '[]'::jsonb;
  v_one  jsonb;
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;

  if p_placement_code is not null then
    v_one := public.kicklive_ad_eligibility(p_advertisement_id, p_placement_code, p_context, p_now);
    return jsonb_build_object('ok', true, 'advertisement_id', p_advertisement_id,
                              'placements', jsonb_build_array(v_one));
  end if;

  for v_code in
    select ap.placement_code from public.advertisement_placements ap
     where ap.advertisement_id = p_advertisement_id
     order by ap.placement_code
  loop
    v_rows := v_rows || jsonb_build_array(
      public.kicklive_ad_eligibility(p_advertisement_id, v_code, p_context, p_now)
    );
  end loop;

  return jsonb_build_object(
    'ok', true,
    'advertisement_id', p_advertisement_id,
    'placements', v_rows,
    'note', 'An empty placements list means no slot assignment exists, so nothing can serve this creative whatever its status.'
  );
end
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 10. WRITES — validated here, never by a patch endpoint
-- ─────────────────────────────────────────────────────────────────────────────
--
-- `service_role` gets no DELETE on the ad tables, and the grant block below says so out loud. There is
-- therefore no path from "the Worker can write these rows" to "the Worker can write them however it
-- likes": every mutation is a function that names the columns it accepts, the role that may call it, and
-- the state transitions it honours. A future route that wants a new column has to add it here, which is
-- the reviewable version of adding an endpoint.
--
-- All three save functions accept a jsonb payload rather than 20 parameters, and that is a shape choice
-- with a reason: `kicklive_asset`-style positional signatures make an optional column a signature
-- change, which breaks every caller of a `security definer` function; a payload lets a column be added
-- with `coalesce` while the signature — and therefore the grant — stays put.

create or replace function public.kicklive_ad_save_advertiser(p_data jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row public.advertisers;
  v_id  uuid := nullif(p_data->>'id', '')::uuid;
begin
  -- The role check is inside the function, not only on the route. A route that forgets is one pull
  -- request away from existing; a function the wrong person cannot call is not.
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  -- Required on create only. Every column here is `coalesce`d on the update path, so demanding the name
  -- again in a patch that only fixes a phone number would make partial edits impossible — and the Worker's
  -- admin route sends exactly those.
  if v_id is null and nullif(p_data->>'business_name', '') is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'business_name', 'reason', 'REQUIRED');
  end if;
  if p_data ? 'kind' and p_data->>'kind' not in
     ('business','organization','pharmacy','brand','event_organizer','local_business','sponsor') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'kind', 'reason', 'UNKNOWN_KIND');
  end if;
  if p_data ? 'status' and p_data->>'status' not in ('draft','pending','approved','suspended','archived') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'status', 'reason', 'UNKNOWN_STATUS');
  end if;
  if p_data ? 'website_url' and not public.kicklive_ad_http_url_ok(nullif(p_data->>'website_url','')) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'website_url', 'reason', 'HTTPS_REQUIRED');
  end if;
  if p_data ? 'logo_url' and not public.kicklive_ad_image_ref_ok(nullif(p_data->>'logo_url','')) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'logo_url', 'reason', 'MANAGED_ASSET_PATH_OR_HTTPS');
  end if;

  select * into v_row from public.advertisers a where a.id = v_id;
  if found then
    update public.advertisers set
      business_name  = coalesce(nullif(p_data->>'business_name', ''), business_name),
      kind           = coalesce(nullif(p_data->>'kind', ''), kind),
      contact_name   = coalesce(nullif(p_data->>'contact_name', ''), contact_name),
      contact_email  = coalesce(nullif(lower(p_data->>'contact_email'), ''), contact_email),
      contact_phone  = coalesce(nullif(p_data->>'contact_phone', ''), contact_phone),
      website_url    = coalesce(nullif(p_data->>'website_url', ''), website_url),
      logo_url       = coalesce(nullif(p_data->>'logo_url', ''), logo_url),
      city           = coalesce(nullif(p_data->>'city', ''), city),
      region         = coalesce(nullif(p_data->>'region', ''), region),
      tier           = coalesce(nullif(p_data->>'tier', ''), tier),
      -- Approval fields are NOT settable here, and that is the whole point of the split: `approved_by`
      -- and `approved_at` are written only by `kicklive_ad_set_advertiser_status`, so a save cannot
      -- launder an approval.
      status         = coalesce(nullif(p_data->>'status', ''), status),
      internal_notes = coalesce(nullif(p_data->>'internal_notes', ''), internal_notes),
      updated_at     = now()
     where id = v_id
     returning * into v_row;
    return jsonb_build_object('ok', true, 'advertiser', to_jsonb(v_row), 'created', false);
  end if;

  insert into public.advertisers (
    business_name, kind, contact_name, contact_email, contact_phone, website_url, logo_url,
    city, region, tier, status, internal_notes, created_by
  ) values (
    trim(p_data->>'business_name'),
    coalesce(nullif(p_data->>'kind', ''), 'business'),
    nullif(p_data->>'contact_name', ''),
    lower(nullif(p_data->>'contact_email', '')),
    nullif(p_data->>'contact_phone', ''),
    nullif(p_data->>'website_url', ''),
    nullif(p_data->>'logo_url', ''),
    nullif(p_data->>'city', ''),
    nullif(p_data->>'region', ''),
    nullif(p_data->>'tier', ''),
    -- A new advertiser starts at `pending` unless the caller explicitly asked for `draft`:
    -- self-approval is the one thing an approval workflow must not accept from the person being
    -- approved. Today an admin is both halves of that exchange, which is precisely why the explicit
    -- approve call exists and why it stamps `approved_by` with the caller rather than trusting this one.
    case when nullif(p_data->>'status','') = 'draft' then 'draft' else 'pending' end,
    nullif(p_data->>'internal_notes', ''),
    auth.uid()
  ) returning * into v_row;
  return jsonb_build_object('ok', true, 'advertiser', to_jsonb(v_row), 'created', true);
end
$fn$;

create or replace function public.kicklive_ad_save_campaign(p_data jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row public.advertisement_campaigns;
  v_adv uuid := nullif(p_data->>'advertiser_id', '')::uuid;
  v_id  uuid := nullif(p_data->>'id', '')::uuid;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if v_id is null and nullif(p_data->>'name', '') is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'name', 'reason', 'REQUIRED');
  end if;
  -- The advertiser is required on create and, when present, must exist; an update that omits it keeps the
  -- campaign where it is (moving a flight between advertisers is a re-contracting event, not an edit).
  if v_id is null and v_adv is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'advertiser_id', 'reason', 'REQUIRED');
  end if;
  if v_adv is not null and not exists (select 1 from public.advertisers a where a.id = v_adv) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'advertiser_id', 'reason', 'ADVERTISER_UNKNOWN');
  end if;
  if v_id is null then
    -- A new flight needs dates. `starts_at`/`ends_at` are not optional, because a campaign with no
    -- window is a campaign that never ends, and the whole point of a flight is that it ends.
    if nullif(p_data->>'starts_at','') is null or nullif(p_data->>'ends_at','') is null then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'ends_at', 'reason', 'WINDOW_REQUIRED');
    end if;
    if (p_data->>'ends_at')::timestamptz <= (p_data->>'starts_at')::timestamptz then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'ends_at', 'reason', 'WINDOW_NOT_ORDERED');
    end if;
  elsif (p_data ? 'starts_at' and p_data ? 'ends_at')
        and (p_data->>'ends_at')::timestamptz <= (p_data->>'starts_at')::timestamptz then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'ends_at', 'reason', 'WINDOW_NOT_ORDERED');
  end if;
  if p_data ? 'budget_currency' and nullif(p_data->>'budget_currency','') is not null
     and not (p_data ? 'budget_amount') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'budget_amount',
                              'reason', 'AMOUNT_REQUIRED_FOR_CURRENCY');
  end if;
  if p_data ? 'budget_currency' and nullif(p_data->>'budget_currency','') is not null
     and p_data->>'budget_currency' !~ '^[A-Za-z]{3}$' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'budget_currency', 'reason', 'ISO4217_REQUIRED');
  end if;
  if p_data ? 'status' and p_data->>'status' not in ('draft','pending','active','paused','completed','archived') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'status', 'reason', 'UNKNOWN_STATUS');
  end if;

  select * into v_row from public.advertisement_campaigns c where c.id = v_id;
  if found then
    update public.advertisement_campaigns set
      name              = coalesce(nullif(p_data->>'name',''), name),
      advertiser_id     = coalesce(v_adv, advertiser_id),
      starts_at         = coalesce(nullif(p_data->>'starts_at','')::timestamptz, starts_at),
      ends_at           = coalesce(nullif(p_data->>'ends_at','')::timestamptz, ends_at),
      budget_amount     = coalesce(nullif(p_data->>'budget_amount','')::numeric, budget_amount),
      budget_currency   = coalesce(nullif(upper(p_data->>'budget_currency'),''), budget_currency),
      billing_reference = coalesce(nullif(p_data->>'billing_reference',''), billing_reference),
      internal_notes    = coalesce(nullif(p_data->>'internal_notes',''), internal_notes),
      status            = coalesce(nullif(p_data->>'status',''), status),
      updated_at        = now()
     where id = v_id
     returning * into v_row;
    return jsonb_build_object('ok', true, 'campaign', to_jsonb(v_row), 'created', false);
  end if;

  insert into public.advertisement_campaigns (
    advertiser_id, name, starts_at, ends_at, budget_amount, budget_currency, billing_reference,
    internal_notes, status, created_by
  ) values (
    v_adv, trim(p_data->>'name'),
    (p_data->>'starts_at')::timestamptz, (p_data->>'ends_at')::timestamptz,
    nullif(p_data->>'budget_amount','')::numeric,
    upper(nullif(p_data->>'budget_currency','')),
    nullif(p_data->>'billing_reference',''),
    nullif(p_data->>'internal_notes',''),
    case when nullif(p_data->>'status','') = 'pending' then 'pending' else 'draft' end,
    auth.uid()
  ) returning * into v_row;
  return jsonb_build_object('ok', true, 'campaign', to_jsonb(v_row), 'created', true);
end
$fn$;

create or replace function public.kicklive_ad_save_advertisement(p_data jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row     public.advertisements;
  v_id      uuid := nullif(p_data->>'id', '')::uuid;
  v_campaign uuid := nullif(p_data->>'campaign_id', '')::uuid;
  v_target   uuid;
  v_codes   text[] := '{}';
  v_window  timestamptz[];
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  -- Which flight this creative belongs to. On insert it must be named; on update an omitted
  -- campaign_id means "unchanged", so the row's own campaign is what the window check below compares
  -- against. Reading `v_campaign` alone would make every partial edit fail with CAMPAIGN_UNKNOWN — which
  -- is the kind of bug only a real UPDATE reveals, since every creation path supplies the field.
  select coalesce(v_campaign, a.campaign_id) into v_target from public.advertisements a where a.id = nullif(p_data->>'id','')::uuid;
  v_target := coalesce(v_campaign, v_target);
  if v_target is null or not exists (select 1 from public.advertisement_campaigns c where c.id = v_target) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'campaign_id', 'reason', 'CAMPAIGN_UNKNOWN');
  end if;
  v_campaign := v_target;
  if v_id is null and nullif(p_data->>'title','') is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'title', 'reason', 'REQUIRED');
  end if;
  -- A new creative must name a destination; an edit may leave it alone. Validated in both cases when
  -- present, because `destination_url` is the one value here a browser will navigate to.
  if (p_data ? 'destination_url' or v_id is null)
     and not public.kicklive_ad_http_url_ok(nullif(p_data->>'destination_url','')) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'destination_url',
                              'reason', 'HTTPS_URL_WITH_HOST_REQUIRED');
  end if;
  if p_data ? 'image_url' and not public.kicklive_ad_image_ref_ok(nullif(p_data->>'image_url','')) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'image_url',
                              'reason', 'MANAGED_ASSET_PATH_OR_HTTPS');
  end if;
  if p_data ? 'video_url' and not public.kicklive_ad_http_url_ok(nullif(p_data->>'video_url','')) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'video_url', 'reason', 'HTTPS_REQUIRED');
  end if;
  if p_data ? 'targeting' and not public.kicklive_ad_targeting_ok(nullif(p_data->'targeting', 'null'::jsonb)) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'targeting',
                              'reason', 'UNKNOWN_KEY_OR_NON_ARRAY',
                              'detail', 'allowed keys: competition_ids, season_ids, team_ids, match_ids, page_types, day_parts; values must be non-empty arrays of ids');
  end if;
  if p_data ? 'label' and p_data->>'label' not in ('Sponsored','Advertisement','Promoted','Partner content') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'label', 'reason', 'UNKNOWN_LABEL');
  end if;
  if p_data ? 'format' and p_data->>'format' not in ('banner','square','story','inline','leaderboard','sponsor_billboard') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'format', 'reason', 'UNKNOWN_FORMAT');
  end if;

  if jsonb_typeof(nullif(p_data->'placements', 'null'::jsonb)) = 'array' then
    select array_agg(distinct trim(x)) into v_codes
      from jsonb_array_elements_text(nullif(p_data->'placements', 'null'::jsonb)) x;
    v_codes := coalesce(v_codes, '{}');
    if exists (select 1 from unnest(v_codes) c where not exists (select 1 from public.ad_placements p where p.code = c)) then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'placements',
                                'reason', 'UNKNOWN_PLACEMENT',
                                'allowed', (select coalesce(jsonb_agg(code), '[]'::jsonb) from public.ad_placements));
    end if;
    -- Refused here rather than left to the trigger so the answer is a field name and a list of slots, not
    -- a Postgres exception travelling through an API envelope.
    --
    -- The join is written this way for a reason: `x = any (select allowed_formats from …)` puts a whole
    -- text[] in each *row* of the subquery, and Postgres then tries to compare a text against an array and
    -- answers `operator does not exist: text = text[]` — even with the subquery wrapped in extra
    -- parentheses, which the grammar still reads as an ANY-subquery. Joining to the row makes
    -- `p.allowed_formats` an ordinary array column again, which is the form `= any (...)` means.
    if exists (
      select 1
        from unnest(v_codes) c
        join public.ad_placements p on p.code = c
       where not (coalesce(nullif(p_data->>'format',''), 'banner') = any (p.allowed_formats))
    ) then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'placements',
                                'reason', 'FORMAT_NOT_ALLOWED_IN_SLOT');
    end if;
  end if;

  -- Ad dates must sit inside the campaign's window. Checked rather than constrained, because a CHECK
  -- cannot contain a subquery and a trigger would be a third place to keep the rule (see the note on the
  -- table above).
  select array[c.starts_at, c.ends_at] into v_window from public.advertisement_campaigns c where c.id = v_campaign;
  if (nullif(p_data->>'starts_at','') is not null or nullif(p_data->>'ends_at','') is not null) then
    if coalesce(nullif(p_data->>'starts_at','')::timestamptz, v_window[1]) < v_window[1]
       or coalesce(nullif(p_data->>'ends_at','')::timestamptz, v_window[2]) > v_window[2] then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'ends_at',
                                'reason', 'OUTSIDE_CAMPAIGN_WINDOW',
                                'detail', jsonb_build_object('campaign_starts', v_window[1], 'campaign_ends', v_window[2]));
    end if;
  end if;

  select * into v_row from public.advertisements a where a.id = v_id;
  if found then
    -- `status` is NOT settable here. Activation belongs to `kicklive_ad_set_status`, which runs the
    -- preconditions; if a save could also flip it, the preconditions would be a suggestion.
  begin
    update public.advertisements set
      title                = coalesce(nullif(p_data->>'title',''), title),
      body                 = coalesce(nullif(p_data->>'body',''), body),
      format               = coalesce(nullif(p_data->>'format',''), format),
      image_url            = coalesce(nullif(p_data->>'image_url',''), image_url),
      video_url            = coalesce(nullif(p_data->>'video_url',''), video_url),
      destination_url      = coalesce(nullif(p_data->>'destination_url',''), destination_url),
      alt_text             = coalesce(nullif(p_data->>'alt_text',''), alt_text),
      priority             = coalesce(nullif(p_data->>'priority','')::integer, priority),
      weight               = coalesce(nullif(p_data->>'weight','')::integer, weight),
      starts_at            = coalesce(nullif(p_data->>'starts_at','')::timestamptz, starts_at),
      ends_at              = coalesce(nullif(p_data->>'ends_at','')::timestamptz, ends_at),
      targeting            = coalesce(nullif(p_data->'targeting', 'null'::jsonb), targeting),
      daily_impression_cap = coalesce(nullif(p_data->>'daily_impression_cap','')::integer, daily_impression_cap),
      label                = coalesce(nullif(p_data->>'label',''), label),
      internal_notes       = coalesce(nullif(p_data->>'internal_notes',''), internal_notes),
      updated_at           = now()
     where id = v_id
     returning * into v_row;
  exception
    when unique_violation then
      -- The one title-per-flight index (§4). A raw 23505 would reach the client as a Postgres sentence,
      -- and every caller would have to pattern-match it; here it is a field name and a reason instead.
      return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'title',
                                'reason', 'DUPLICATE_TITLE_IN_CAMPAIGN',
                                'detail', 'Two creatives with the same name in one flight split both the exposure and the measured numbers.');
  end;

    -- Setting placements is a replace, not an add: a UI that shows three slots and submits two means the
    -- admin removed one. An absent key means "I did not touch placements", which is why the delete is
    -- guarded by `p_data ? 'placements'` and the insert above is not.
    if p_data ? 'placements' then
      delete from public.advertisement_placements x
       where x.advertisement_id = v_id and not (x.placement_code = any (v_codes));
      insert into public.advertisement_placements (advertisement_id, placement_code)
      select v_id, c from unnest(v_codes) c
      on conflict (advertisement_id, placement_code) do nothing;
    end if;

    return jsonb_build_object(
      'ok', true,
      'advertisement', to_jsonb(v_row),
      'placements', coalesce((select jsonb_agg(x.placement_code order by x.placement_code)
                                from public.advertisement_placements x where x.advertisement_id = v_id), '[]'::jsonb),
      'created', false
    );
  end if;

  begin
    insert into public.advertisements (
      campaign_id, title, body, format, image_url, video_url, destination_url, alt_text,
    priority, weight, starts_at, ends_at, targeting, daily_impression_cap, label, internal_notes, created_by
  ) values (
    v_campaign, trim(p_data->>'title'), nullif(p_data->>'body',''),
    coalesce(nullif(p_data->>'format',''), 'banner'),
    nullif(p_data->>'image_url',''), nullif(p_data->>'video_url',''),
    nullif(p_data->>'destination_url',''), nullif(p_data->>'alt_text',''),
    coalesce(nullif(p_data->>'priority','')::integer, 50),
    coalesce(nullif(p_data->>'weight','')::integer, 10),
    nullif(p_data->>'starts_at','')::timestamptz, nullif(p_data->>'ends_at','')::timestamptz,
    coalesce(nullif(p_data->'targeting', 'null'::jsonb), '{}'::jsonb),
    nullif(p_data->>'daily_impression_cap','')::integer,
    coalesce(nullif(p_data->>'label',''), 'Sponsored'),
    nullif(p_data->>'internal_notes',''), auth.uid()
    ) returning * into v_row;
  exception
    when unique_violation then
      return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'title',
                                'reason', 'DUPLICATE_TITLE_IN_CAMPAIGN',
                                'detail', 'Two creatives with the same name in one flight split both the exposure and the measured numbers.');
  end;

  insert into public.advertisement_placements (advertisement_id, placement_code)
  select v_row.id, c from unnest(v_codes) c
  on conflict (advertisement_id, placement_code) do nothing;

  return jsonb_build_object(
    'ok', true,
    'advertisement', to_jsonb(v_row),
    'placements', coalesce((select jsonb_agg(x.placement_code order by x.placement_code)
                              from public.advertisement_placements x where x.advertisement_id = v_row.id), '[]'::jsonb),
    'created', true
  );
end
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 11. THE STATUS MACHINE
-- ─────────────────────────────────────────────────────────────────────────────
--
-- One VALUES list and one function, so "can active go to pending?" has exactly one answer in the
-- database, and the admin UI *reads that answer* instead of mirroring it. This is the same move Phase 5
-- made with `kicklive_notification_kind_policy`, for the same reason: a matrix that lives in a component
-- is a matrix that can be changed by a pull request that only touched the component.
--
--   draft    → pending | archived
--   pending  → active | draft | archived        (activate = the approval; preconditions run there)
--   active   → paused | expired | archived
--   paused   → active | expired | archived        (re-activation re-runs the preconditions)
--   expired  → active | archived                  (an extension is legitimate; eligibility re-checks the window)
--   archived → ∅                                  nothing serves from archived, and reopening it would
--                                                  put a creative nobody re-reviewed back on a public page
--
-- `pending → active` is the only arc that reaches the public, and it is the only one with preconditions.

create table if not exists public.ad_status_transitions (
  from_status text not null check (from_status in ('draft','pending','active','paused','expired','archived','approved','suspended','completed')),
  to_status   text not null check (to_status   in ('draft','pending','active','paused','expired','archived','approved','suspended','completed')),
  note        text,
  primary key (from_status, to_status)
);

insert into public.ad_status_transitions (from_status, to_status, note) values
  ('draft',   'pending',  'ready for review'),
  ('draft',   'archived', 'nothing sent'),
  ('pending', 'active',   'the approval act; activation preconditions run here'),
  ('pending', 'draft',    'back to editing'),
  ('pending', 'archived', 'declined'),
  ('active',  'paused',   'immediate for the next uncached read; the serving cache holds for at most its max-age'),
  ('active',  'expired',  'normal end of flight (also set by kicklive_ad_expire_due)'),
  ('active',  'archived', 'withdrawn'),
  ('paused',  'active',   're-activation re-runs the preconditions'),
  ('paused',  'expired',  null),
  ('paused',  'archived', null),
  ('expired', 'active',   'an extension moves the window; eligibility re-checks it'),
  ('expired', 'archived', null),
  -- `completed` is the flight's word for the same moment `expired` is the creative's, and the two tables share
  -- this matrix, so the arc has to be here for a campaign to reach it at all. Without it, "the operator closed
  -- this flight by hand" is impossible and `completed` is a state only `kicklive_ad_expire_due` can produce —
  -- which would make the cascade below this table (a flight leaving `active` parks its creatives) the only
  -- thing that ever archives a sponsorship's worth of copy. Adding the arc costs an advertisement nothing:
  -- `kicklive_ad_set_status` validates `p_status` against the *per-table* status list first, and an
  -- advertisement has no `completed` in its list, so the row is unreachable for it by validation rather than
  -- by omission — which is the difference between a matrix that is shared and a rule that is lost.
  ('active',  'completed', 'the flight ended on purpose; `kicklive_ad_set_campaign_status` still refuses it before the date arrives'),
  ('paused',  'completed', 'closing a flight that was paused rather than running down')
  -- `archived` has no outgoing row at all, and that absence IS the rule: this table is read with
  -- `exists (… from_status = current and to_status = wanted)`, so a row written to document a prohibition
  -- ('archived' -> 'active', 'never') would *permit* it. A matrix that doubles as documentation has to
  -- contain only the arcs that are allowed; the prose above is where the never-again rule is stated.
on conflict (from_status, to_status) do nothing;

create or replace function public.kicklive_ad_status_transitions(p_table text)
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- The statuses are per-kind (an advertiser has `approved`/`suspended` and no `expired`; a campaign has
  -- `completed` and no `expired`), and the *transitions* are shared, filtered to the states each table can
  -- be in. One matrix, three vocabularies, and the UI draws its buttons from here — which is how
  -- "PAUSED → ACTIVE is allowed but DRAFT → ACTIVE is not" cannot be re-decided in a component.
  select jsonb_build_object(
    'table', p_table,
    'statuses', case p_table
      when 'advertisers'             then array['draft','pending','approved','suspended','archived']
      when 'advertisement_campaigns' then array['draft','pending','active','paused','completed','archived']
      else array['draft','pending','active','paused','expired','archived']
    end,
    'transitions', coalesce((
      select jsonb_agg(jsonb_build_object('from', t.from_status, 'to', t.to_status, 'note', t.note)
                       order by t.from_status, t.to_status)
        from public.ad_status_transitions t
       where t.from_status = any (case p_table
               when 'advertisers'             then array['draft','pending','approved','suspended','archived']
               when 'advertisement_campaigns' then array['draft','pending','active','paused','completed','archived']
               else array['draft','pending','active','paused','expired','archived'] end)
         and t.to_status = any (case p_table
               when 'advertisers'             then array['draft','pending','approved','suspended','archived']
               when 'advertisement_campaigns' then array['draft','pending','active','paused','completed','archived']
               else array['draft','pending','active','paused','expired','archived'] end)
    ), '[]'::jsonb)
  )
$fn$;

create or replace function public.kicklive_ad_set_advertiser_status(p_id uuid, p_status text)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row public.advertisers;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_row from public.advertisers a where a.id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'ADVERTISER_UNKNOWN');
  end if;
  if p_status not in ('draft','pending','approved','suspended','archived') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'status', 'reason', 'UNKNOWN_STATUS');
  end if;
  if v_row.status = 'archived' and p_status <> 'archived' then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'ARCHIVED_IS_TERMINAL',
                              'detail', 'create a new advertiser record instead; history is not reopened');
  end if;
  -- Approving is the one transition that needs the *current* caller rather than any write: `approved_by`
  -- is evidence, and evidence stamped by a background job is not evidence.
  update public.advertisers set
    status      = p_status,
    approved_by = case when p_status = 'approved' then auth.uid() else approved_by end,
    approved_at = case when p_status = 'approved' then now()      else approved_at end,
    updated_at  = now()
   where id = p_id
   returning * into v_row;

  -- A suspended advertiser stops its flights serving, immediately and without touching them: eligibility
  -- requires `advertiser_status = 'approved'`, so nothing here has to cascade. What IS cascaded is
  -- approval — an advertiser that is no longer approved cannot keep advertising that was approved under
  -- its old status, so those creatives go back to `pending` rather than staying `active`.
  if p_status in ('suspended', 'archived') then
    update public.advertisements a set status = 'pending', updated_at = now()
     where a.status = 'active'
       and a.campaign_id in (select c.id from public.advertisement_campaigns c where c.advertiser_id = p_id);
  end if;

  return jsonb_build_object('ok', true, 'advertiser', to_jsonb(v_row));
end
$fn$;

create or replace function public.kicklive_ad_set_campaign_status(p_id uuid, p_status text)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row     public.advertisement_campaigns;
  v_allowed boolean;
  v_affected integer := 0;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_row from public.advertisement_campaigns c where c.id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'CAMPAIGN_UNKNOWN');
  end if;
  select exists (
    select 1 from public.ad_status_transitions t
     where t.from_status = v_row.status and t.to_status = p_status
  ) into v_allowed;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'TRANSITION_NOT_ALLOWED',
                              'detail', v_row.status || ' -> ' || coalesce(p_status, 'null'));
  end if;
  if p_status = 'active' and v_row.ends_at <= now() then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'CAMPAIGN_WINDOW_PAST',
                              'detail', 'extend the flight first; an active campaign that has already ended is a number nobody can reconcile');
  end if;
  -- The other half of the window rule, stated as a decision rather than as a constraint: `completed` is a
  -- claim about the flight's dates, so the date has to have arrived. A day of grace, because completing on the
  -- last day of a flight is normal clerical work and refusing it would teach an operator to set the date
  -- wrong. Everything else about a finished flight is allowed from anywhere in the flow — that is what
  -- `paused` and `archived` are for.
  if p_status = 'completed' and v_row.ends_at > now() + interval '1 day' then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'ends_at', 'reason', 'FLIGHT_HAS_NOT_ENDED',
                              'detail', 'a flight that has not reached its end date is paused, not completed');
  end if;
  if p_status = 'active' and not exists (
       select 1 from public.advertisers a where a.id = v_row.advertiser_id and a.status = 'approved'
  ) then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'ADVERTISER_NOT_APPROVED');
  end if;

  update public.advertisement_campaigns set status = p_status, updated_at = now() where id = p_id
   returning * into v_row;

  -- A flight leaving `active` must not strand its creatives in `active`: that is how a dashboard ends up
  -- showing "3 live advertisements" for a campaign nobody is paying for. They go to `paused` when the
  -- campaign might resume (a resumed flight should not require re-approving every creative) and to
  -- `archived` when it cannot.
  if p_status in ('paused', 'completed', 'archived') then
    update public.advertisements a
       set status = case when p_status = 'paused' then 'paused' else 'archived' end,
           updated_at = now()
     where a.campaign_id = p_id and a.status = 'active';
    get diagnostics v_affected = row_count;
  end if;

  return jsonb_build_object('ok', true, 'campaign', to_jsonb(v_row),
                            'advertisements_affected', v_affected);
end
$fn$;

create or replace function public.kicklive_ad_set_status(p_id uuid, p_status text)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row     public.advertisements;
  v_allowed boolean;
  v_missing text[];
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_row from public.advertisements a where a.id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'ADVERTISEMENT_UNKNOWN');
  end if;

  select exists (
    select 1 from public.ad_status_transitions t
     where t.from_status = v_row.status and t.to_status = p_status
  ) into v_allowed;
  if not v_allowed then
    -- The refusal carries what IS allowed, because the admin screen's job is to say what to do next and
    -- 'TRANSITION_NOT_ALLOWED' with no list of alternatives is a dead end with a status code.
    return jsonb_build_object(
      'ok', false, 'code', 'CONFLICT', 'reason', 'TRANSITION_NOT_ALLOWED',
      'detail', v_row.status || ' -> ' || coalesce(p_status, 'null'),
      'allowed', coalesce((select jsonb_agg(t.to_status order by t.to_status)
                             from public.ad_status_transitions t
                            where t.from_status = v_row.status), '[]'::jsonb)
    );
  end if;

  if p_status = 'active' then
    -- ── activation preconditions ─────────────────────────────────────────
    -- Each of these is also a CHECK or an eligibility clause. They are repeated here so the admin gets a
    -- list of field names instead of a constraint violation to interpret: the CHECK is the guarantee, this
    -- is the explanation. And the row records the refusal, so the list page can say it again tomorrow.
    v_missing := '{}';
    -- `array_append`, not `|| 'text'`: Postgres has no text[] || text operator, and the error it
    -- raises (`malformed array literal`) reads like a bug in the caller rather than in this line.
    if v_row.image_url is null and v_row.media_asset_id is null then
      v_missing := array_append(v_missing, 'creative');
    end if;
    if v_row.alt_text is null or char_length(trim(v_row.alt_text)) < 3 then
      -- Alt text is required *to activate* rather than to draft because a decorative ad with no
      -- description is a screen-reader user getting nothing at all, on a page they came to for the score.
      v_missing := array_append(v_missing, 'alt_text');
    end if;
    if not public.kicklive_ad_http_url_ok(v_row.destination_url) then
      v_missing := array_append(v_missing, 'destination_url');
    end if;
    if not exists (
      select 1 from public.advertisement_placements ap
      join public.ad_placements pl on pl.code = ap.placement_code and pl.is_active
       where ap.advertisement_id = p_id and ap.is_active
    ) then
      v_missing := array_append(v_missing, 'placement');
    end if;
    if v_row.ends_at is not null and v_row.ends_at <= now() then
      v_missing := array_append(v_missing, 'window');
    end if;
    if not exists (
      select 1 from public.advertisement_campaigns c
      join public.advertisers av on av.id = c.advertiser_id
       where c.id = v_row.campaign_id and c.status = 'active' and av.status = 'approved'
    ) then
      v_missing := array_append(v_missing, 'campaign');
    end if;
    if array_length(v_missing, 1) > 0 then
      update public.advertisements a
         set activation_error = array_to_string(v_missing, ','), updated_at = now()
       where a.id = p_id;
      return jsonb_build_object(
        'ok', false, 'code', 'CONFLICT', 'reason', 'ACTIVATION_PRECONDITIONS',
        'missing', to_jsonb(v_missing),
        'detail', 'Refused to activate. Nothing was published, so there is nothing to roll back.'
      );
    end if;

    update public.advertisements set
      status = 'active', activation_error = null,
      approved_by = auth.uid(), approved_at = now(), updated_at = now()
     where id = p_id
     returning * into v_row;
  else
    update public.advertisements set status = p_status,
           activation_error = case when p_status = 'archived' then activation_error else null end,
           updated_at = now()
     where id = p_id
     returning * into v_row;
  end if;

  return jsonb_build_object(
    'ok', true,
    'advertisement', to_jsonb(v_row),
    'placements', coalesce((select jsonb_agg(x.placement_code order by x.placement_code)
                              from public.advertisement_placements x where x.advertisement_id = p_id), '[]'::jsonb),
    'note', case p_status
      when 'paused'  then 'Eligibility is per request, so a pause takes effect on the next uncached read; the serving cache holds for at most 30s.'
      when 'expired' then 'The row stays readable for history. The creative is untouched in R2 and Phase 6 retention starts from the next status change, not from here.'
      when 'archived' then 'The creative stays in R2 until the media retention sweep retires it, so an archive is always undoable inside the window.'
      else null
    end
  );
end
$fn$;

-- The two placement operations Step 15 asks for: retire a slot (everything in it stops serving at once,
-- which is the emergency brake this whole design keeps available) and change its cap. Nothing else about
-- a slot is editable from the app, on purpose: a slot whose `max_items` or formats an advertiser could
-- reach is a slot with no administrator, and the codes themselves are a deploy-time decision because a
-- page has to contain the element before a row can fill it.
create or replace function public.kicklive_ad_set_placement(p_code text, p_is_active boolean default null, p_max_items integer default null)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row public.ad_placements;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if p_is_active is null and p_max_items is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'reason', 'NOTHING_TO_DO');
  end if;
  if p_max_items is not null and p_max_items not between 1 and 6 then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'max_items', 'reason', 'OUT_OF_RANGE');
  end if;
  update public.ad_placements set
    is_active = coalesce(p_is_active, is_active),
    max_items = coalesce(p_max_items, max_items),
    updated_at = now()
   where code = p_code
   returning * into v_row;
  if v_row.code is null then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'PLACEMENT_UNKNOWN');
  end if;
  return jsonb_build_object('ok', true, 'placement', to_jsonb(v_row),
                            'note', 'Deactivating a slot stops it serving within one cache interval and leaves every assignment intact.');
end
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 12. CREATIVES THROUGH THE PHASE 6 PLANE
-- ─────────────────────────────────────────────────────────────────────────────
--
-- Step 10: advertisement assets use the R2 architecture, and nothing is uploaded with unrestricted
-- browser credentials. The pipeline is Phase 6's — `publishAsset`: sniff → hash → reserve → put → head →
-- publish — so this file adds only the two things specific to an advertisement: who may reserve a slot
-- for one, and the vocabulary the reservation answers in.
--
-- `kicklive_ad_reserve_creative` deliberately mirrors `kicklive_reserve_asset_upload`'s *outcome shape*
-- (proceed / skip_upload / rejected / forbidden, with the same reason strings) so the Worker's pipeline
-- can drive either without knowing which, and so the two reservations cannot drift into two protocols.
-- Only the authorization differs: media uploads are per-entity-owner, ad creatives are admin-only, and an
-- ad that is being measured cannot be edited by whoever uploaded its image.

-- The two edits Phase 6 left for this file.
--
-- (a) The registry accepts the kind. Phase 6's comment says "sponsors/ and advertisements/ are
--     documented as reserved prefixes but are deliberately NOT legal here yet: there is no table to attach
--     them to, and a CHECK that allows a kind nothing can authorize is how orphaned objects get made".
--     `advertisements` now has a table *and* an authorizing function, so it becomes legal. `sponsors`
--     does **not**: it still has neither, and adding it "for symmetry" would be exactly the orphan-making
--     Phase 6 refused. It gets added the same way, in the migration that creates the table.
-- (b) `kicklive_asset_url_column` answers `image_url`, which is what makes Phase 6's own `finalize`
--     attach the published path to the advertisement row inside the same transaction. Without this arm
--     the asset would be stored and ready but no page would ever render it.
alter table public.media_assets drop constraint if exists media_assets_kind_check;
alter table public.media_assets add constraint media_assets_kind_check check (
  entity_kind in ('teams','players','competitions','seasons','news','team_news','matches','users','advertisements')
);

create or replace function public.kicklive_asset_url_column(p_entity_kind text)
returns text
language sql immutable
set search_path = public, pg_temp
as $fn$
  select case p_entity_kind
    when 'teams'        then 'logo_url'
    when 'players'      then 'photo_url'
    when 'competitions' then 'logo_url'
    when 'news'         then 'image_url'
    when 'team_news'    then 'image_url'
    when 'users'        then 'avatar_url'
    -- The one Phase 7 adds. `seasons` and `matches` stay absent: their assets exist to be *read* from the
    -- media registry, not copied onto a row that has no image column.
    when 'advertisements' then 'image_url'
    else null
  end
$fn$;

comment on function public.kicklive_asset_url_column(text) is
  'Which entity column a published asset is copied into, or null when the registry is the only place the '
  'path lives. Extended by 20260913120000 to add `advertisements`; the Phase 6 definition is superseded, '
  'not edited, so a database that already ran Phase 6 converges by re-running this name.';

create or replace function public.kicklive_ad_reserve_creative(
  p_advertisement_id uuid,
  p_content_type     text,
  p_byte_size        bigint,
  p_sha256           text,
  p_width            integer default null,
  p_height           integer default null,
  p_alt_text         text    default null
)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_ad  public.advertisements;
  v_ext text;
  v_ver integer;
  v_key text;
  v_dup public.media_assets%rowtype;
  v_new public.media_assets;
begin
  if not public.is_admin() then
    return jsonb_build_object('status', 'forbidden', 'reason', 'ADMIN_ONLY');
  end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('status', 'rejected', 'reason', 'DIGEST_REQUIRED');
  end if;
  if p_byte_size is null or p_byte_size < 1 or p_byte_size > 10485760 then
    -- 10 MB, the same ceiling as `news`: a 2×-for-retina leaderboard PNG is around 3 MB, and a 10 MB
    -- banner for a 300 px slot is a file that was never meant for this page. The Worker applies the
    -- per-kind cap before this line is reached, so this is the ceiling that holds when it is not.
    return jsonb_build_object('status', 'rejected', 'reason', 'TOO_LARGE');
  end if;
  v_ext := case lower(coalesce(p_content_type, ''))
    when 'image/png'  then 'png'
    when 'image/jpeg' then 'jpg'
    when 'image/webp' then 'webp'
    when 'image/gif'  then 'gif'
    else 'bin'
  end;
  if v_ext = 'bin' then
    -- The Worker sniffed this bytes-first already. Re-deriving the extension from the *content type the
    -- Worker settled on* (not from a filename, never) is what keeps the key's extension honest if a
    -- future caller arrives with a sniffed type the media plane did not have.
    return jsonb_build_object('status', 'rejected', 'reason', 'UNSUPPORTED_TYPE');
  end if;

  select * into v_ad from public.advertisements a where a.id = p_advertisement_id;
  if not found then
    return jsonb_build_object('status', 'rejected', 'reason', 'ADVERTISEMENT_UNKNOWN');
  end if;
  if v_ad.status = 'archived' then
    return jsonb_build_object('status', 'forbidden', 'reason', 'ADVERTISEMENT_ARCHIVED');
  end if;

  -- Dedupe before anything else: re-uploading the same bytes is a no-op rather than a new version, so an
  -- admin who double-clicks save neither doubles the stored bytes nor moves the creative to a second
  -- identical key.
  select * into v_dup from public.media_assets a
   where a.entity_kind = 'advertisements' and a.entity_id = p_advertisement_id::text
     and a.status = 'ready' and a.sha256 = p_sha256
   order by a.version desc limit 1;
  if found then
    return jsonb_build_object('status', 'skip_upload', 'asset', jsonb_build_object(
      'id', v_dup.id, 'object_key', v_dup.object_key, 'version', v_dup.version,
      'visibility', v_dup.visibility, 'status', v_dup.status
    ));
  end if;

  select coalesce(max(a.version), 0) + 1 into v_ver from public.media_assets a
   where a.entity_kind = 'advertisements' and a.entity_id = p_advertisement_id::text;
  v_key := public.kicklive_asset_object_key('advertisements', p_advertisement_id::text, 'original', v_ver, p_sha256, v_ext);

  insert into public.media_assets (
    entity_kind, entity_id, bucket, object_key, variant, version, content_type, byte_size,
    width, height, sha256, visibility, status, alt_text, created_by
  ) values (
    'advertisements', p_advertisement_id::text,
    -- The bucket name is data, not configuration — same rule and same setting as Phase 6, so an
    -- environment whose storage is not bound cannot write a row that claims otherwise.
    coalesce(nullif(current_setting('kicklive.storage_bucket', true), ''), 'media'),
    v_key, 'original', v_ver, p_content_type, p_byte_size, p_width, p_height, p_sha256,
    -- Public, and it has to be: an advertisement is rendered to anonymous visitors from an <img> tag that
    -- carries no Authorization header. Marking a creative private here would produce a broken image on a
    -- public page, not a protection.
    'public', 'uploading', p_alt_text, auth.uid()
  ) returning * into v_new;

  return jsonb_build_object('status', 'proceed', 'asset', jsonb_build_object(
    'id', v_new.id, 'object_key', v_new.object_key, 'version', v_new.version,
    'visibility', v_new.visibility, 'status', v_new.status
  ));
end
$fn$;

-- After the bytes are in R2 and head-confirmed, Phase 6's `kicklive_finalize_asset_upload` marks the row
-- `ready` and — because `kicklive_asset_url_column` below now answers `image_url` for the
-- `advertisements` kind — moves the creative's URL onto the advertisement row in that same transaction.
-- This function is the *undo* half, which Phase 6 has no equivalent of because no other entity has a
-- second copy of the path: `advertisements.media_asset_id` is the provenance link, and it must be set and
-- cleared explicitly so an archived ad cannot point at an asset somebody else now owns.
create or replace function public.kicklive_ad_attach_creative(p_advertisement_id uuid, p_asset_id bigint)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_asset public.media_assets;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_asset from public.media_assets a where a.id = p_asset_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'ASSET_UNKNOWN');
  end if;
  -- The asset has to belong to THIS advertisement. Without this line, "attach asset 42" is a way to point
  -- a new creative at somebody else's stored object and read it back through a public page.
  if v_asset.entity_kind <> 'advertisements' or v_asset.entity_id <> p_advertisement_id::text then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'ASSET_BELONGS_TO_ANOTHER_ENTITY');
  end if;
  if v_asset.status not in ('ready', 'uploading') then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'ASSET_NOT_READY', 'actual', v_asset.status);
  end if;

  update public.advertisements set
    media_asset_id = p_asset_id,
    -- The rendered path is derived from the same key Phase 6 published, so the two columns cannot
    -- disagree: `image_url` is never accepted from a caller on this path.
    image_url = '/api/media/assets/' || v_asset.object_key,
    updated_at = now()
   where id = p_advertisement_id;

  return jsonb_build_object('ok', true, 'asset_id', p_asset_id, 'version', v_asset.version,
                            'image_url', '/api/media/assets/' || v_asset.object_key);
end
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 13. COUNTING, DEDUPLICATED
-- ─────────────────────────────────────────────────────────────────────────────
--
-- IMPRESSION (the definition the brief asks to be written down): one advertisement, one slot, one
-- viewer-key, one UTC day, counted the first time the creative is *observed on screen* — not fetched, not
-- mounted. Re-renders, refetches, tab re-activation, a component that mounts twice and a retry of the
-- report all collapse onto one row, because the dedupe key is
-- `imp|<advertisement>|<placement>|<viewer_key>|<day>`. That single choice is what makes "do not count
-- every React render" a property of the database rather than a promise about `useEffect` dependencies.
--
-- The honest consequence, stated in the architecture note as well as here: a viewer who starts a new
-- session gets a new key, so the count is a **floor**, not an exact number. For an aggregate this is
-- measured for — "did the banner do better on the match page than on /tables" — a floor is enough, and
-- it is the right direction to err in. It is also why these numbers must not become an invoice before
-- somebody builds a real verification path.
--
-- CLICK: one advertisement, one slot, one viewer-key, one UTC *hour*, counted once — same shape, shorter
-- window, because a person legitimately taps a sponsor twice in an afternoon and should not be flattened
-- into one, while a script hammering the endpoint cannot get more than 24 counted clicks a day per key.
--
-- CTR is clicks ÷ impressions, computed when asked for. It is stored nowhere: a stored ratio is a second
-- truth that disagrees with the counts it came from the moment a count is corrected.

create or replace function public.kicklive_ad_record_event(
  p_advertisement_id uuid,
  p_placement_code   text,
  p_event            text,
  p_viewer_key       text,
  p_now              timestamptz default now()
)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_day      date := (p_now at time zone 'utc')::date;
  v_hour     text := to_char(p_now at time zone 'utc', 'YYYY-MM-DD HH24');
  v_dedupe   text;
  v_campaign uuid;
  v_ad       public.advertisements;
  v_state    jsonb;
  v_reason   text;
  v_grace    interval;
begin
  if p_event not in ('impression', 'click') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'event', 'reason', 'UNKNOWN_EVENT');
  end if;
  -- Shape, not provenance. The key is a caller-chosen 16 hex characters and it is NOT a credential: an
  -- attacker who wants to spend somebody else's daily allowance can, and gains nothing beyond a row they
  -- cannot read back. What the shape check buys is that a caller cannot smuggle an identifier into a
  -- column named viewer_key — `^[0-9a-f]{16}$` does not hold an email address, a device id or a phone
  -- number, which is the privacy property that matters here.
  if p_viewer_key is null or p_viewer_key !~ '^[0-9a-f]{16}$' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'viewerKey', 'reason', 'MALFORMED_VIEWER_KEY');
  end if;

  select * into v_ad from public.advertisements a where a.id = p_advertisement_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'ADVERTISEMENT_UNKNOWN');
  end if;
  v_campaign := v_ad.campaign_id;

  -- An event has to be about something that could actually have been on screen in this slot. Horizon 0
  -- rather than the serving horizon: the cache question is not the counting question, and asking the same
  -- function with a different parameter is cheaper than a second predicate that can drift.
  v_state  := public.kicklive_ad_eligibility(p_advertisement_id, p_placement_code, '{}'::jsonb, p_now, 0);
  v_reason := coalesce(v_state->>'reason', 'advertisement_not_found');

  if v_reason in ('advertisement_not_found', 'not_placed_in_slot', 'slot_unknown', 'slot_disabled',
                  'placement_disabled', 'no_creative', 'slot_refuses_this_format') then
    -- Nothing like this was ever served, so nothing here can be true about it.
    return jsonb_build_object('ok', true, 'counted', false, 'reason', 'NEVER_SERVABLE', 'detail', v_reason);
  end if;

  if v_reason not in ('eligible', 'daily_cap_reached', 'placement_daily_cap_reached', 'targeting_excludes') then
    -- Anything else means the creative is not currently servable for a reason of *status or schedule*. That
    -- is exactly the trailing-event case: an impression or click that arrives a moment after a pause, an
    -- expiry or a campaign stop refers to something the person really did see. The grace window is what
    -- makes that legitimate late event countable without making a permanently retired creative countable,
    -- and `updated_at` is the only record of when the status changed — which is why the window is coarse
    -- (10 minutes for an impression, 1 hour for a click) rather than tight.
    v_grace := case when p_event = 'impression' then interval '10 minutes' else interval '1 hour' end;
    if v_ad.updated_at < p_now - v_grace then
      return jsonb_build_object('ok', true, 'counted', false, 'reason', 'OUTSIDE_GRACE', 'detail', v_reason);
    end if;
  end if;

  v_dedupe := case when p_event = 'impression'
                   then 'imp|' || p_advertisement_id::text || '|' || p_placement_code || '|' || p_viewer_key || '|' || v_day::text
                   else 'clk|' || p_advertisement_id::text || '|' || p_placement_code || '|' || p_viewer_key || '|' || v_hour end;

  insert into public.ad_events (advertisement_id, campaign_id, placement_code, event, occurred_at, day, viewer_key, dedupe_key, counted)
  values (p_advertisement_id, v_campaign, p_placement_code, p_event, p_now, v_day, p_viewer_key, v_dedupe, true)
  on conflict (dedupe_key) do nothing;

  if not found then
    -- A duplicate: the honest answer is `counted: false`, and the rollup is left alone. Returning an
    -- error here would teach every client to stop retrying a *legitimate* second event.
    return jsonb_build_object('ok', true, 'counted', false, 'reason', 'ALREADY_COUNTED');
  end if;

  -- The rollup moves in the same statement, so `ad_events` and `advertisement_analytics` can only be
  -- apart if something dies between them — which, in one transaction, it cannot.
  insert into public.advertisement_analytics (advertisement_id, placement_code, day, impressions, clicks)
  values (p_advertisement_id, p_placement_code, v_day,
          case when p_event = 'impression' then 1 else 0 end,
          case when p_event = 'click' then 1 else 0 end)
  on conflict (advertisement_id, placement_code, day)
    do update set
      impressions = public.advertisement_analytics.impressions + case when p_event = 'impression' then 1 else 0 end,
      clicks      = public.advertisement_analytics.clicks      + case when p_event = 'click' then 1 else 0 end,
      updated_at  = now();

  return jsonb_build_object('ok', true, 'counted', true, 'event', p_event, 'day', v_day::text);
end
$fn$;

-- The batch form, for the queue consumer and only for it: one call per batch rather than one per event,
-- because a consumer that issues 25 RPCs for a 25-message batch has made the queue the bottleneck it
-- exists to remove. Refusals are per item and reported, never fatal for the batch — a poison event must
-- not stall the ninety-nine behind it. `exception when others` is what makes that true for a row that
-- fails at *parse* time (a uuid that is not one), which the per-item checks above cannot see.
create or replace function public.kicklive_ad_record_events(p_events jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  e          jsonb;
  v_res      jsonb;
  v_counted  integer := 0;
  v_deduped  integer := 0;
  v_refused  integer := 0;
  v_reasons  jsonb := '{}'::jsonb;
  v_key      text;
begin
  if jsonb_typeof(p_events) <> 'array' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'reason', 'ARRAY_REQUIRED');
  end if;
  if jsonb_array_length(p_events) > 500 then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'reason', 'BATCH_TOO_LARGE');
  end if;

  for e in select * from jsonb_array_elements(p_events)
  loop
    begin
      v_res := public.kicklive_ad_record_event(
        nullif(e->>'advertisementId','')::uuid,
        coalesce(nullif(e->>'placement',''), 'HOME_TOP'),
        coalesce(nullif(e->>'event',''), 'impression'),
        nullif(e->>'viewerKey',''),
        coalesce(nullif(e->>'occurredAt','')::timestamptz, now())
      );
    exception when others then
      v_refused := v_refused + 1;
      v_reasons := jsonb_set(v_reasons, array['invalid_row'],
                            to_jsonb(coalesce((v_reasons->>'invalid_row')::integer, 0) + 1));
      continue;
    end;
    if coalesce((v_res->>'counted')::boolean, false) then
      v_counted := v_counted + 1;
    elsif v_res->>'reason' = 'ALREADY_COUNTED' then
      v_deduped := v_deduped + 1;
    else
      v_refused := v_refused + 1;
      v_key := coalesce(v_res->>'reason', 'UNKNOWN');
      v_reasons := jsonb_set(v_reasons, array[v_key],
                             to_jsonb(coalesce((v_reasons->>v_key)::integer, 0) + 1));
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'counted', v_counted, 'deduped', v_deduped,
                            'refused', v_refused, 'reasons', v_reasons);
end
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 14. ANALYTICS READ, SCHEDULING, RETENTION, DIAGNOSTICS
-- ─────────────────────────────────────────────────────────────────────────────

create or replace function public.kicklive_ad_analytics(
  p_from date default ((now() at time zone 'utc')::date - 29),
  p_to   date default ((now() at time zone 'utc')::date),
  p_advertiser_id uuid default null,
  p_campaign_id   uuid default null,
  p_placement_code text default null,
  p_group_by text default 'advertisement'
)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_rows jsonb;
begin
  -- Staff-only. The rollups are aggregate counts and look harmless, but they are the numbers a business
  -- relationship gets argued over, and "how many impressions did the pharmacy get last week" is
  -- commercially sensitive whether or not it contains a person.
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  -- Re-derive the defaults here rather than trusting the parameter defaults, because a caller that passes
  -- an explicit null — which is what an absent field in a JSON body becomes over RPC — does NOT get the
  -- default. Left alone, `between null and null` matches nothing and the screen shows an honest-looking
  -- empty table for a system full of numbers.
  p_from := coalesce(p_from, ((now() at time zone 'utc')::date - 29));
  p_to   := coalesce(p_to, ((now() at time zone 'utc')::date));
  p_group_by := coalesce(p_group_by, 'advertisement');
  if p_group_by not in ('advertisement', 'campaign', 'placement', 'day') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'groupBy', 'reason', 'UNKNOWN_GROUP_BY');
  end if;
  if p_to < p_from then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'to', 'reason', 'WINDOW_NOT_ORDERED');
  end if;
  -- A bounded window rather than "give me everything": the rollup is small per day but a two-year query
  -- over every creative is how a reporting screen becomes the slowest route in the Worker.
  if p_to - p_from > 92 then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'from',
                              'reason', 'WINDOW_TOO_WIDE', 'detail', 'a quarter at a time; anything longer is an export job, not a request');
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'key', r.key,
           'title', r.title,
           'impressions', r.impressions,
           'clicks', r.clicks,
           -- Rounded here rather than in the client: 0.037% and 0.04% are the same number for every
           -- purpose this table exists for, and one rounding rule means one place to argue about it.
           'ctr_percent', case when r.impressions = 0 then 0
                               else round(r.clicks::numeric * 100 / r.impressions, 2) end,
           'days', r.days
         ) order by r.impressions desc), '[]'::jsonb)
    into v_rows
  from (
    select
      case p_group_by
        when 'campaign'  then a.campaign_id::text
        when 'placement' then an.placement_code
        when 'day'       then an.day::text
        else an.advertisement_id::text
      end as key,
      case p_group_by
        when 'campaign'  then c.name
        when 'placement' then an.placement_code
        when 'day'       then an.day::text
        else a.title
      end as title,
      sum(an.impressions)::bigint as impressions,
      sum(an.clicks)::bigint      as clicks,
      count(distinct an.day)      as days
    from public.advertisement_analytics an
    join public.advertisements a         on a.id = an.advertisement_id
    join public.advertisement_campaigns c on c.id = a.campaign_id
    join public.advertisers av           on av.id = c.advertiser_id
    where an.day between p_from and p_to
      and (p_advertiser_id  is null or av.id = p_advertiser_id)
      and (p_campaign_id    is null or c.id  = p_campaign_id)
      and (p_placement_code is null or an.placement_code = p_placement_code)
    group by 1, 2
  ) r;

  return jsonb_build_object('ok', true, 'rows', v_rows, 'from', p_from::text, 'to', p_to::text,
                            'group_by', p_group_by,
                            'definition', 'impressions = distinct viewer-days per creative per slot (a floor, not an exact count); clicks = distinct viewer-hours; ctr = clicks/impressions');
end
$fn$;

-- Step 5's other half. Eligibility already ignores a creative whose window has passed, so nothing is
-- *served* wrongly; this is about what the tables say. An `active` row whose flight ended three weeks
-- ago is a lie on the admin screen, a CTR whose denominator is frozen under a status that implies it is
-- running, and a row nobody will ever pause. Flipping it to `expired` touches nothing a public reader
-- sees, because a public reader never asked about status.
--
-- `for update ... skip locked` inside a cursor loop, not in a CTE: a lock clause in a WITH is an error in
-- Postgres, and `skip locked` is what stops two overlapping runs from fighting over the same rows
-- instead of one of them failing.
create or replace function public.kicklive_ad_expire_due(p_limit integer default 500)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  r record;
  v_ads integer := 0;
  v_campaigns integer := 0;
begin
  for r in
    select a.id from public.advertisements a
     where a.status = 'active' and a.ends_at is not null and a.ends_at <= now()
     order by a.ends_at
     limit least(greatest(coalesce(p_limit, 500), 1), 2000)
     for update skip locked
  loop
    update public.advertisements set status = 'expired', updated_at = now() where id = r.id;
    v_ads := v_ads + 1;
  end loop;

  for r in
    select c.id from public.advertisement_campaigns c
     where c.status = 'active' and c.ends_at <= now()
     order by c.ends_at
     limit least(greatest(coalesce(p_limit, 500), 1), 2000)
     for update skip locked
  loop
    update public.advertisement_campaigns set status = 'completed', updated_at = now() where id = r.id;
    update public.advertisements a set status = 'expired', updated_at = now()
      where a.campaign_id = r.id and a.status = 'active';
    v_campaigns := v_campaigns + 1;
  end loop;

  return jsonb_build_object('ok', true, 'advertisements_expired', v_ads, 'campaigns_completed', v_campaigns);
end
$fn$;

-- Retention. It is the one DELETE in this file, and the reason is the same one that makes an
-- analytics log with no expiry a surveillance log nobody switched off: 30 days is long enough to settle a
-- dispute about last week and short enough that this table cannot become where the app keeps history about
-- who saw what. The rollups stay, and they hold no key that could be joined to a person.
--
-- The identity guard is the same shape as Phase 6's sweep and it is only safe for the same reason: the
-- function is not granted to `anon`/`authenticated`, so an identified caller who is not an admin has no
-- way to reach it at all.
create or replace function public.kicklive_ad_sweep(p_days integer default 30, p_limit integer default 20000)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_cutoff  timestamptz := now() - make_interval(days => greatest(coalesce(p_days, 30), 1));
  v_ids     bigint[];
  v_deleted integer := 0;
begin
  if auth.uid() is not null and not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_REQUIRED');
  end if;

  select array_agg(x.id) into v_ids from (
    select e.id from public.ad_events e
     where e.occurred_at < v_cutoff
     order by e.occurred_at
     limit least(greatest(coalesce(p_limit, 20000), 1), 50000)
     for update of e skip locked
  ) x;

  if v_ids is not null then
    delete from public.ad_events e where e.id = any (v_ids);
    get diagnostics v_deleted = row_count;
  end if;

  return jsonb_build_object('ok', true, 'events_deleted', v_deleted, 'cutoff', v_cutoff::text,
                            'note', 'Rollups in advertisement_analytics are retained; they contain no viewer key.');
end
$fn$;

create or replace function public.kicklive_ad_admin_list(
  p_status text default null,
  p_placement_code text default null,
  p_limit integer default 50
)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_rows jsonb;
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  -- A function rather than a REST read of the tables, for one column: `serving` is the eligibility answer,
  -- and a browser joining a set-returning function per row is a request per row. Everything else on this
  -- list is a straight projection, including the columns the *public* never sees — which is fine here and
  -- only here, because the caller has been checked against the capability in the route table.
  select coalesce(jsonb_agg(to_jsonb(r) order by r.updated_at desc), '[]'::jsonb) into v_rows
  from (
    select a.id, a.title, a.body, a.status, a.format, a.priority, a.weight, a.label,
           a.starts_at, a.ends_at, a.activation_error, a.updated_at, a.approved_at,
           a.image_url, a.destination_host, a.alt_text, a.daily_impression_cap, a.media_asset_id,
           c.id as campaign_id, c.name as campaign_name, c.status as campaign_status,
           av.id as advertiser_id, av.business_name, av.status as advertiser_status,
           coalesce((select jsonb_agg(x.placement_code order by x.placement_code)
                       from public.advertisement_placements x where x.advertisement_id = a.id), '[]'::jsonb) as placements,
           coalesce((select sum(an.impressions) from public.advertisement_analytics an
                      where an.advertisement_id = a.id and an.day = ((now() at time zone 'utc')::date)), 0) as impressions_today,
           coalesce((select sum(an.clicks) from public.advertisement_analytics an
                      where an.advertisement_id = a.id and an.day = ((now() at time zone 'utc')::date)), 0) as clicks_today,
           coalesce((select bool_or(el.eligible) from (
                       select (public.kicklive_ad_eligibility(a.id, x.placement_code, '{}'::jsonb, now(), 90)->>'eligible')::boolean as eligible
                         from public.advertisement_placements x where x.advertisement_id = a.id
                     ) el), false) as serving
      from public.advertisements a
      join public.advertisement_campaigns c on c.id = a.campaign_id
      join public.advertisers av            on av.id = c.advertiser_id
     where (p_status is null or a.status = p_status)
       and (p_placement_code is null or exists (
              select 1 from public.advertisement_placements x
               where x.advertisement_id = a.id and x.placement_code = p_placement_code))
     order by a.updated_at desc
     limit least(greatest(coalesce(p_limit, 50), 1), 200)
  ) r;
  return jsonb_build_object('ok', true, 'advertisements', v_rows);
end
$fn$;

-- The slot registry, for the admin screen. A function and not a table grant because RLS is enabled with
-- no policies on every table here: a `grant select` would be a privilege that answers zero rows, which is
-- the worst possible shape for a permission — it looks granted and reads as empty. So the registry has an
-- owner (this function), and the caller is checked instead of the row.
create or replace function public.kicklive_ad_placements()
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  select jsonb_build_object(
    'ok', true,
    'placements', coalesce((
      select jsonb_agg(jsonb_build_object(
               'code', p.code, 'label', p.label, 'description', p.description, 'page', p.page,
               'maxItems', p.max_items, 'heightBudgetPx', p.height_budget_px,
               'allowedFormats', to_jsonb(p.allowed_formats), 'yieldsToLive', p.yields_to_live,
               'isActive', p.is_active, 'sortOrder', p.sort_order,
               'assigned', coalesce((select count(1) from public.advertisement_placements x where x.placement_code = p.code), 0),
               'serving', coalesce((
                 select count(1) from public.advertisements a
                   join public.advertisement_campaigns c on c.id = a.campaign_id and c.status = 'active'
                   join public.advertisers av on av.id = c.advertiser_id and av.status = 'approved'
                  where a.status = 'active'
                    and exists (select 1 from public.advertisement_placements y
                                 where y.advertisement_id = a.id and y.placement_code = p.code and y.is_active)
                ), 0)
             ) order by p.sort_order, p.code)
        from public.ad_placements p
    ), '[]'::jsonb)
  )
$fn$;

create or replace function public.kicklive_ad_diagnostics()
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- Counts only. No creative bytes, no event row, no viewer key and no contact detail ever appears in this
  -- response, which is what lets it be a route rather than a privilege escalation.
  select jsonb_build_object(
    'ok', true,
    'schema', jsonb_build_object(
      'advertisers',       (select count(1) from public.advertisers),
      'advertisers_by_status', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (
                                  select status k, count(1) n from public.advertisers group by 1) s),
      'campaigns',         (select count(1) from public.advertisement_campaigns),
      'advertisements',    (select count(1) from public.advertisements),
      'advertisements_by_status', (select coalesce(jsonb_object_agg(k, n), '{}'::jsonb) from (
                                  select status k, count(1) n from public.advertisements group by 1) s),
      'placements',        (select count(1) from public.ad_placements),
      'placements_active', (select count(1) from public.ad_placements where is_active)
    ),
    'serving', jsonb_build_object(
      'eligible_by_placement', (
        select coalesce(jsonb_object_agg(x.code, x.n), '{}'::jsonb) from (
          select pl.code, (
            select count(1) from public.advertisements a
             join public.advertisement_placements ap on ap.advertisement_id = a.id and ap.placement_code = pl.code and ap.is_active
             join public.advertisement_campaigns c on c.id = a.campaign_id and c.status = 'active'
             join public.advertisers av on av.id = c.advertiser_id and av.status = 'approved'
             where a.status = 'active'
               and (a.starts_at is null or a.starts_at <= now())
               and (a.ends_at   is null or a.ends_at   >  now())
          ) as n
          from public.ad_placements pl where pl.is_active
        ) x
      )
    ),
    'events', jsonb_build_object(
      'total',       (select count(1) from public.ad_events),
      'last_24h',    (select count(1) from public.ad_events where occurred_at > now() - interval '24 hours'),
      'oldest',      (select min(occurred_at) from public.ad_events),
      'rollup_days', (select count(distinct day) from public.advertisement_analytics)
    ),
    'integrity', jsonb_build_object(
      -- The shapes that must not exist, counted rather than asserted. The CHECKs and triggers make them
      -- unwritable, so a non-zero count means a row predates this migration — a thing to know about, not a
      -- thing to discover through a page that shows a broken banner.
      'active_without_creative', (select count(1) from public.advertisements where status = 'active' and image_url is null and media_asset_id is null),
      'active_outside_campaign', (select count(1) from public.advertisements a
                                   join public.advertisement_campaigns c on c.id = a.campaign_id
                                  where a.status = 'active' and c.status <> 'active'),
      'unplaced_active',         (select count(1) from public.advertisements a
                                   where a.status = 'active'
                                     and not exists (select 1 from public.advertisement_placements x where x.advertisement_id = a.id)),
      'expired_but_active',      (select count(1) from public.advertisements a
                                   where a.status = 'active' and a.ends_at is not null and a.ends_at <= now()),
      'destination_not_https',   (select count(1) from public.advertisements a where a.destination_url !~* '^https://'),
      'active_advertiser_not_approved', (select count(1) from public.advertisements a
                                   join public.advertisement_campaigns c on c.id = a.campaign_id
                                   join public.advertisers av on av.id = c.advertiser_id
                                  where a.status = 'active' and av.status <> 'approved')
    ),
    'media', jsonb_build_object(
      'advertisements_assets', (select count(1) from public.media_assets where entity_kind = 'advertisements'),
      -- A creative whose advertisement is gone is Phase 6's orphan case, and it is reported here rather
      -- than silently deleted here: reconciliation is the Worker's job, in both directions, in one place.
      'orphan_ad_assets',      (select count(1) from public.media_assets ma
                                 where ma.entity_kind = 'advertisements' and ma.status in ('ready','superseded')
                                   and not exists (select 1 from public.advertisements a where a.id::text = ma.entity_id))
    ),
    'config', jsonb_build_object(
      'note', 'Diagnostics counts only. Nothing in this response names a person, a device or a file.'
    )
  )
$fn$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 15. GRANTS, RLS, TRIGGERS
-- ─────────────────────────────────────────────────────────────────────────────
--
-- RLS enabled, no policies, on every table in this file. The reasoning is Phase 5's and Phase 6's and is
-- written once rather than per table: the only access path the app has is through the functions above, a
-- client role holds no table privilege except `select` on the placement registry, and `service_role`
-- holds no DELETE on the ad tables. `force row level security` is absent on purpose — see
-- docs/NOTIFICATIONS_ARCHITECTURE.md §9.6 for the three reasons it is worse than useless here.

do $rls$
declare
  t text;
begin
  foreach t in array array[
    'advertisers', 'advertisement_campaigns', 'advertisements', 'ad_placements',
    'advertisement_placements', 'ad_events', 'advertisement_analytics', 'ad_status_transitions'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated, service_role', t);
  end loop;
end
$rls$;

do $grant$
declare
  r record;
  n integer := 0;
begin
  -- Explicit names plus a pattern, because a grant loop driven by one LIKE silently omits the function
  -- named for what it does instead of what it touches — which is a 401 at runtime that no typechecker
  -- sees (Phase 6 learned this the expensive way).
  for r in
    select p.proname,
           pg_get_function_identity_arguments(p.oid) as args
      from pg_proc p
      join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public'
       and p.prokind = 'f'
       and (p.proname like 'kicklive_ad_%'
            or p.proname in ('kicklive_asset_url_column', 'kicklive_ad_guard_placement_format',
                             'kicklive_ad_guard_advertisement_format', 'touch_updated_at'))
  loop
    -- Every client role by name. `from public` only would leave the anon/authenticated EXECUTE entries that
    -- the default privileges Supabase creates, which is precisely the hole the block below asserts against.
    execute format('revoke all on function public.%I(%s) from public, anon, authenticated', r.proname, r.args);
    execute format('grant execute on function public.%I(%s) to service_role', r.proname, r.args);
    n := n + 1;
  end loop;

  -- The ENTIRE client-callable surface: two functions, both of which return nothing a caller was not
  -- already allowed to see. `kicklive_ad_serve` because an anonymous visitor is the normal reader of an
  -- advertisement, and `kicklive_ad_record_event` because the person who saw the banner is the only
  -- witness to it — the function's eligibility check and dedupe are the whole of its protection, and a
  -- write this cheap is bounded by the Worker's `public` budget in front of it rather than by an
  -- identity. Everything else in this file, including every status change, every analytics read and the
  -- batch ingest (which would turn one request into 500 events from an anonymous socket), is service-role
  -- only: reachable through a route that has already checked a capability.
  for r in
    select p.proname, pg_get_function_identity_arguments(p.oid) as args
      from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public'
       and p.proname in ('kicklive_ad_serve', 'kicklive_ad_record_event')
  loop
    execute format('grant execute on function public.%I(%s) to anon, authenticated', r.proname, r.args);
  end loop;

  -- Table privileges, and what each one excludes. Read the exclusions as the design:
  --   · `ad_placements`: writable by the service role, but `kicklive_ad_set_placement` is the only thing
  --     that writes it, so the columns it cannot change are unchangeable in practice too.
  --   · `ad_status_transitions`: select only. The matrix is this migration's, not an API.
  --   · `ad_events`: insert and select, no update and no delete. Only the record functions write it and
  --     only the retention sweep prunes it.
  --   · advertisers / campaigns / advertisements / placements: select, insert, update. No DELETE, so a
  --     row cannot vanish while an event row or a rollup still points at it. Archiving is this system's
  --     delete, and it is the reason an audit of "what ran when" survives an admin's bad afternoon.
  grant select, insert, update, delete on table public.ad_placements           to service_role;
  grant select                        on table public.ad_status_transitions     to service_role;
  grant select, insert, update        on table public.advertisers              to service_role;
  grant select, insert, update        on table public.advertisement_campaigns  to service_role;
  grant select, insert, update        on table public.advertisements           to service_role;
  grant select, insert, update, delete on table public.advertisement_placements to service_role;
  grant insert, select                on table public.ad_events                to service_role;
  grant select, insert, update        on table public.advertisement_analytics   to service_role;
  -- `ad_events.id` is an identity column, so the insert needs the sequence.
  grant usage, select on sequence public.ad_events_id_seq to service_role;

  raise notice 'kicklive: advertising grants applied to % functions', n;
end
$grant$;

-- `updated_at` for every mutable table, as one trigger (Phase 3's pattern; a dozen copies of the same
-- eight lines is how one of them ends up missing). Phase 6 has no equivalent because its timestamps are
-- per-transition rather than one shared column, which is the right choice for a media registry and the
-- wrong one for a status table an admin edits.
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $fn$
begin
  new.updated_at := now();
  return new;
end
$fn$;

do $trig$
declare
  t text;
begin
  foreach t in array array[
    'advertisers', 'advertisement_campaigns', 'advertisements', 'ad_placements', 'advertisement_analytics'
  ] loop
    execute format('drop trigger if exists trg_touch_updated_at on public.%I', t);
    execute format('create trigger trg_touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()', t);
  end loop;
end
$trig$;

-- A creative is never orphaned by its advertisement's deletion: `advertisement_placements` cascades and
-- `media_asset_id` sets null. The R2 object itself is NOT deleted from here, on purpose — Phase 6's
-- retention window is what decides when stored bytes are forgotten, and putting a second, irreversible
-- deletion path inside an application table's trigger is the failure its Step 15 was written to avoid.

-- ─────────────────────────────────────────────────────────────────────────────
-- 16. VERIFY
-- ─────────────────────────────────────────────────────────────────────────────
--
-- The same discipline as Phase 6: the list below is the authority on what this file must have created,
-- and every table privilege, policy and CHECK is asserted against the catalogue rather than against
-- intent. It raises, so a half-applied advertising schema is not a state this migration can leave behind.

do $verify$
declare
  expected text[] := array[
    'kicklive_ad_http_url_ok',
    'kicklive_ad_image_ref_ok',
    'kicklive_ad_targeting_ok',
    'kicklive_ad_eligibility',
    'kicklive_ad_targeting_matches',
    'kicklive_ad_rotation_key',
    'kicklive_ad_bucket',
    'kicklive_ad_serve',
    'kicklive_ad_explain',
    'kicklive_ad_save_advertiser',
    'kicklive_ad_save_campaign',
    'kicklive_ad_save_advertisement',
    'kicklive_ad_status_transitions',
    'kicklive_ad_set_advertiser_status',
    'kicklive_ad_set_campaign_status',
    'kicklive_ad_set_status',
    'kicklive_ad_set_placement',
    'kicklive_ad_reserve_creative',
    'kicklive_ad_attach_creative',
    'kicklive_ad_record_event',
    'kicklive_ad_record_events',
    'kicklive_ad_analytics',
    'kicklive_ad_expire_due',
    'kicklive_ad_sweep',
    'kicklive_ad_admin_list',
    'kicklive_ad_placements',
    'kicklive_ad_diagnostics',
    'kicklive_ad_guard_placement_format',
    'kicklive_ad_guard_slot_formats',
    'kicklive_ad_guard_advertisement_format',
    'kicklive_asset_url_column'
  ];
  client_writable text[];
  policy_holders  text[];
  missing         text[];
  not_granted     text[];
  t text;
begin
  select array_agg(x) into missing from unnest(expected) x
   where not exists (
     select 1 from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
      where ns.nspname = 'public' and p.proname = x
   );
  if missing is not null then
    raise exception 'kicklive migration verification failed: advertising functions not created: %', missing;
  end if;

  foreach t in array array[
    'advertisers', 'advertisement_campaigns', 'advertisements', 'ad_placements',
    'advertisement_placements', 'ad_events', 'advertisement_analytics'
  ] loop
    if not exists (
      select 1 from pg_class c join pg_namespace ns on ns.oid = c.relnamespace
       where ns.nspname = 'public' and c.relname = t and c.relrowsecurity
    ) then
      raise exception 'kicklive migration verification failed: public.% is not RLS-protected', t;
    end if;
    if exists (
      select 1 from pg_policy p join pg_class c on c.oid = p.polrelid
       join pg_namespace ns on ns.oid = c.relnamespace
       where ns.nspname = 'public' and c.relname = t
    ) then
      raise exception 'kicklive migration verification failed: public.% has a policy; the Worker is the only access path', t;
    end if;
    -- The assertion that matters most in this file: no client role holds *any* table privilege on any ad
    -- table. Not "no write privilege" — with RLS enabled and no policies a read privilege is already a
    -- door, and the shape of this schema is that a browser reaches these rows only through a function
    -- that decided it may.
    select array_agg(distinct g.grantee || ':' || g.privilege_type) into client_writable
      from information_schema.role_table_grants g
     where g.table_schema = 'public' and g.table_name = t
       and g.grantee in ('anon', 'authenticated');
    if client_writable is not null then
      raise exception 'kicklive migration verification failed: a client role holds a table privilege on public.%: %', t, client_writable;
    end if;
  end loop;

  if exists (
    select 1 from information_schema.role_table_grants
     where table_schema = 'public' and table_name = 'advertisements'
       and grantee in ('anon','authenticated')
  ) then
    raise exception 'kicklive migration verification failed: advertisements are readable by a client role';
  end if;

  -- Exposure, asserted structurally: the public serving function's result must not name a column that
  -- only an admin may see. It is a `returns jsonb` today, so this catches a future refactor that swaps it
  -- for a typed row-returning function — the shape a leak would actually arrive in.
  if exists (
    select 1 from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public' and p.proname = 'kicklive_ad_serve'
       and pg_get_function_result(p.oid) ilike '%budget%'
  ) then
    raise exception 'kicklive migration verification failed: kicklive_ad_serve exposes a budget column';
  end if;
  if exists (
    select 1 from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public' and p.proname = 'kicklive_ad_serve'
       and (pg_get_function_arguments(p.oid) ilike '%p_status%'
            or pg_get_function_arguments(p.oid) ilike '%p_advertiser_id%')
  ) then
    raise exception 'kicklive migration verification failed: kicklive_ad_serve takes a filter a caller could use to widen its own view';
  end if;

  -- The public surface must actually be callable by the roles that need it, and everything else must not
  -- be, and oid-based rather than signature-based, because `has_function_privilege('anon',
  -- 'public.f(...)','execute')` demands the exact argument list — including the defaults, which a caller
  -- never types — so a signature spelled one way here silently checks nothing.
  --
  -- Note the argument ORDER: (role, function, privilege). Written the other way round the call does not
  -- resolve to an overload, and Postgres' complaint is `expected a left parenthesis`, which points at
  -- nothing and cost an hour.
  select array_agg(p.proname) into not_granted
    from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
   where ns.nspname = 'public'
     and p.proname in ('kicklive_ad_serve', 'kicklive_ad_record_event')
     and not public.kicklive_has_grant('anon', p.oid::regprocedure::text, 'X');
  if not_granted is not null then
    raise exception 'kicklive migration verification failed: public surface not granted to anon: %', not_granted;
  end if;

  -- Read the ACL, not has_function_privilege: the second form answers "true" for every function when the
  -- applying role is a superuser, so this assertion can only ever fire when it is wrong to fire.
  if exists (
    select 1 from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
     where ns.nspname = 'public' and p.proname like 'kicklive_ad_%'
       and p.proname not in ('kicklive_ad_serve', 'kicklive_ad_record_event')
       and public.kicklive_has_grant('authenticated', p.oid::regprocedure::text, 'X')
  ) then
    raise exception 'kicklive migration verification failed: an admin-only advertising function is granted to authenticated';
  end if;

  -- The media kind widening must have widened, not narrowed: every kind Phase 6 accepted is still
  -- accepted, and `advertisements` now is one.
  if not exists (
    select 1 from pg_constraint where conname = 'media_assets_kind_check'
  ) then
    raise exception 'kicklive migration verification failed: media_assets kind constraint missing';
  end if;
  if exists (
    select 1
      from unnest(array['teams','players','competitions','seasons','news','team_news','matches','users','advertisements']) k
     where not exists (
       select 1 from pg_constraint c
        where c.conname = 'media_assets_kind_check'
          and pg_get_constraintdef(c.oid) like '%' || quote_literal(k) || '%'
     )
  ) then
    -- A textual check of the constraint definition, deliberately: the alternative is a live insert into the
    -- media registry during a migration, which is exactly what an idempotent file must not do. This also
    -- proves the widening did not *narrow* anything Phase 6 relied on.
    raise exception 'kicklive migration verification failed: media_assets kind CHECK no longer admits every expected kind';
  end if;

  if (select count(1) from public.ad_placements) < 8 then
    raise exception 'kicklive migration verification failed: placement registry under-seeded (expected 8)';
  end if;
  if (select count(1) from public.ad_status_transitions) < 13 then
    raise exception 'kicklive migration verification failed: status matrix under-seeded';
  end if;
  if public.kicklive_ad_http_url_ok('http://insecure.example/') or public.kicklive_ad_http_url_ok('https://a@b.example/x..') then
    raise exception 'kicklive migration verification failed: the destination URL rule accepted something it must refuse';
  end if;
  if not public.kicklive_ad_http_url_ok('https://sponsor.example/promo?utm=1') then
    raise exception 'kicklive migration verification failed: the destination URL rule refused a normal sponsor link';
  end if;
  if public.kicklive_ad_targeting_ok('{"interests":["football"]}'::jsonb) then
    raise exception 'kicklive migration verification failed: targeting accepted a profiling key';
  end if;

  raise notice 'kicklive: advertising migration verified — 7 tables + matrix, % functions, 8 placements',
    array_length(expected, 1);
end
$verify$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 17. ROLLBACK — commented, and short because the file is additive.
-- ─────────────────────────────────────────────────────────────────────────────
/*
 * Rollback is only safe while nothing has been measured. Check first:
 *
 *   select count(1) from public.ad_events;                 -- must be 0
 *   select count(1) from public.advertisement_analytics;  -- must be 0
 *   select count(1) from public.media_assets where entity_kind = 'advertisements';  -- see below
 *
 * Any non-zero count means the system has been in use, and the counts are the evidence for what was paid
 * for. Dropping the tables then is destroying records, not rolling back a deploy: archive the tables
 * instead (rename or `create table ..._phase7_archive as select *`), and let the owner decide.
 *
 * If ad creatives were ever stored, their media_assets rows must go through Phase 6's retention
 * (`kicklive_delete_asset` with purge, or the sweep) BEFORE the kind CHECK is narrowed back to eight —
 * otherwise the rows become un-updatable and their objects unreachable-but-present, which is the one
 * inconsistency a media registry must never end up in.
 *
 *   begin;
 *   drop trigger if exists trg_touch_updated_at on public.advertisements;
 *   drop trigger if exists trg_touch_updated_at on public.advertisement_campaigns;
 *   drop trigger if exists trg_touch_updated_at on public.advertisers;
 *   drop trigger if exists trg_touch_updated_at on public.ad_placements;
 *   drop trigger if exists trg_touch_updated_at on public.advertisement_analytics;
 *   drop trigger if exists trg_ad_placement_format_guard on public.advertisement_placements;
 *   drop trigger if exists trg_ad_slot_formats_guard on public.ad_placements;
 *   drop trigger if exists trg_ad_advertisement_format_guard on public.advertisements;
 *   -- one `drop function if exists public.<name>(<args>)` per entry in $verify$.expected ...
 *   alter table public.media_assets drop constraint if exists media_assets_kind_check;
 *   alter table public.media_assets add constraint media_assets_kind_check check (
 *     entity_kind in ('teams','players','competitions','seasons','news','team_news','matches','users')
 *   );
 *   drop table if exists public.advertisement_analytics, public.ad_events,
 *                          public.advertisement_placements, public.ad_placements,
 *                          public.advertisements, public.advertisement_campaigns,
 *                          public.advertisers, public.ad_status_transitions;
 *   commit;
 *   notify pgrst, 'reload schema';
 *
 * Note what is NOT reverted: `kicklive_asset_url_column` is left with its `advertisements` arm. A
 * function that answers a column name for a kind nobody can insert is harmless, and replacing it with
 * Phase 6's version would be a `create or replace` of a function Phase 6's own file still defines — a
 * drift with no owner.
 */

commit;

-- PostgREST caches function signatures: without this a client would get 404 on
-- /rest/v1/rpc/kicklive_ad_serve until the API is restarted.
notify pgrst, 'reload schema';
;

-- <<< END section 7: supabase/migrations/20260913120000_phase7_advertising.sql <<<

-- >>> BEGIN section 8: supabase/migrations/20260914120000_phase8_sponsorship.sql >>>
SELECT '8 / 10: supabase/migrations/20260914120000_phase8_sponsorship.sql' AS kicklive_sql_section;

-- ============================================================================
-- KICK LIVE · Phase 8 · sponsorship
-- ----------------------------------------------------------------------------
-- A sponsor is not an advertiser, and this file is the argument for keeping the two systems apart.
--
--   An ADVERTISEMENT buys a slot. It is scheduled by the second, measured by the impression, rotated by
--   weight against other creatives in the same slot, and it disappears the moment it stops being paid for.
--   Phase 7 built that machine (`advertisers`, `advertisement_campaigns`, `advertisements`, `ad_placements`).
--
--   A SPONSORSHIP is a right. It is a relationship between a brand and a *thing the competition office
--   recognises* — a competition, a season, a match, a team, an award, an event — it lasts a season rather
--   than a fortnight, it is displayed because the contract says so and not because a rota came round, and
--   being the title sponsor of a cup is not something another bidder can out-weight. There is no rotation
--   here, no auction, no impression cap and no click. If those words appear in a sponsorship file, the
--   design has been confused with the other one.
--
-- So: separate tables, separate status machines, separate caches, one shared media plane. `docs/
-- PRODUCTION_ARCHITECTURE.md` §14 specified this split before either existed, including the seam — "a
-- package may include placements: the link is `sponsorship_id` → generated campaign rows, not shared
-- columns" — and the link column is here (`sponsorships.advertisement_campaign_id`), deliberately written
-- by nobody in this migration: generating a flight from a rights package is Phase 9's job, and a column
-- with a foreign key is a seam, while a copy of the other system's columns would be a merger.
--
-- What a sponsor's own record holds (steps 2 and 13 of the brief):
--   · a brand (`display_name`) and, separately, the organisation behind it (`legal_name`) — the name on the
--     shirt and the name on the contract are different fields because they are different facts;
--   · private contact (`contact_name`, `contact_email`, `contact_phone`) that the public projection never
--     reads, not "never returns" — see the note on `kicklive_sponsorship_for`;
--   · five agreement fields (`value_amount`, `value_currency`, `value_basis`, `invoice_reference`,
--     `renewal_terms`) as *text the desk typed*. There is no ledger, no invoice table, no tax or bank
--     column, and no column that could hold one. Step 13 asks for structures that a future billing system
--     can attach to; the way to grant that without building it is to store what a contract already states
--     and to keep the money in the contract until somebody has to reconcile it.
--
-- Media (step 6): sponsor logos and banners go to the Phase 6 R2 plane, keyed under the `sponsors/` prefix
-- that Phase 6 reserved and refused to activate until a table existed to own the rows. This migration
-- creates that table and widens `media_assets_kind_check` in the same file, which is precisely what
-- Phase 6's comment asked for. Nothing here stores bytes.
--
-- Expiry (step 5) is enforced twice on purpose: the serving query filters on the window, so an expired
-- sponsorship stops appearing within one cache lifetime (max-age is short and said so below); and
-- `kicklive_sponsorship_expire_due` moves the *status* so the admin screen, the counts and any future
-- report stop claiming it is live. The first is what a viewer sees; the second is what an operator can
-- trust. A schedule cannot be a display rule.
--
-- Cache invalidation (step 11) has a real answer rather than a hopeful one: every write in this file bumps
-- `sponsorship_config.epoch`, and the public read carries that epoch. An edge entry is valid while the
-- epoch it was built under is current, so an activation is visible on the next request that can tell the
-- difference — and the browser's own Phase 4 cache is invalidated by tag from the admin mutation, which is
-- the only invalidation that can be synchronous because it is the only one in the same process.
--
-- Apply with `supabase db push`. It is additive: no table is dropped, no column is dropped, and the one
-- `alter table` touches a CHECK constraint on `media_assets` by replacing it with a superset. With this
-- migration applied and zero rows written, every public page is byte-identical to yesterday: `sponsorships`
-- is empty, so `kicklive_sponsorship_for` answers `{}` and the slots render nothing at all.
-- ============================================================================

begin;

-- ----------------------------------------------------------------------------
-- 0 · the validation primitives
--
-- IMMUTABLE and expression-only, because a table CHECK may not contain a subquery or read the clock and
-- these are called from CHECKs. Anything that has to *look something up* is a trigger instead (§6).
-- ----------------------------------------------------------------------------

-- The https rule is Phase 7's, and it is *delegated* rather than copied. The reason is the same one that
-- makes two implementations of a cache policy a mistake: a sponsor's link and an advertiser's destination are
-- the same hazard — a string that becomes an `href` — and two rules drift the moment one of them is
-- tightened. Phase 7's `kicklive_ad_http_url_ok` is the owner of that rule; the flow test behind it (`https://kicklive.football@evil.test/` refused,
-- no second colon, no protocol-relative form, no `..`), so sponsorship inherits that instead of re-deriving
-- a weaker one. `docs/SPONSORSHIP_ARCHITECTURE.md` §7 names the owner.
create or replace function public.kicklive_sponsor_https_ok(p_url text)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  select public.kicklive_ad_http_url_ok(p_url)
$fn$;

-- A target kind is a closed list — it decides which table an id is resolved against, and a value that
-- resolves nothing would be a sponsorship attached to nothing. The *packages* are open (step 3); this is
-- not that.
create or replace function public.kicklive_sponsor_target_kind_ok(p_kind text)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  select p_kind = any (array['competition', 'season', 'match', 'team', 'award', 'event'])
$fn$;

-- An entity id per kind: `competition`/`season`/`team`/`match` are integer keys in this schema, and
-- `award`/`event` do not have tables yet, so they take a slug. One regex, stated once, used by both the
-- CHECK and the guard trigger.
create or replace function public.kicklive_sponsor_target_id_ok(p_kind text, p_id text)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  select p_id is not null and case
    when p_kind in ('competition', 'season', 'team', 'match') then p_id ~ '^[1-9][0-9]{0,9}$'
    -- An award or an event is named by whoever creates it, so it is a slug rather than a row: the only
    -- requirement is that it is stable enough to be a cache key and boring enough to put in a URL.
    else p_id ~ '^[a-z0-9][a-z0-9._-]{1,63}$'
  end
$fn$;

-- Every numeric field is cast out of JSON text, and a bad cast raises rather than refuses. One helper,
-- three writers, and the answer names the field: an empty string is "absent" (the forms send one), a number
-- or a numeric string is accepted, and anything else is refused before it reaches a cast.
-- A date the client typed: shape checked here, calendar sense checked by the cast below. Both, rather than a
-- bare `::date`, because `{"endsAt": "2026-02-30"}` would otherwise raise `date/time field value out of
-- range` out of a definer function, and the Worker can only report that as a 502. A wrong form is a field
-- error, and the client has to be told which field.
create or replace function public.kicklive_sponsor_date_ok(p_value text)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  select p_value is null or p_value ~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'
$fn$;

create or replace function public.kicklive_sponsor_field_refuses(p_data jsonb, p_keys text[])
returns text
language sql immutable
set search_path = public, pg_temp
as $fn$
  select k.x
    from unnest(coalesce(p_keys, array[]::text[])) k(x)
   where p_data ? k.x
     and coalesce(p_data ->> k.x, '') <> ''
     and p_data ->> k.x !~ '^[0-9]{1,12}(\.[0-9]{1,2})?$'
   limit 1
$fn$;

-- A label a viewer will read: no control characters, no markup, and short enough to fit the band. Note
-- what is *not* checked: the words. "Official Partner" is a claim about a relationship, and the only
-- defence against an inflationary one is a human approving it, which is what `status` is for.
create or replace function public.kicklive_sponsor_label_ok(p_label text, p_max integer default 120)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  select p_label is null
      or (
        char_length(btrim(p_label)) between 1 and coalesce(p_max, 120)
        and p_label !~ '[[:cntrl:]]'
        and p_label not like '%<%'
        and p_label not like '%>%'
      )
$fn$;

-- The entitlement keys a package may promise, and the shape each must have. A closed set, for the reason
-- Phase 7's targeting keys are closed: the renderer is the far end of this, and a free-form bag of
-- properties turns every consumer into a try/catch. New entitlements are added here, which is a
-- deliberate change to what a sponsor can be promised.
-- Every entitlement is checked with a `case`, not with a chain of `and`/`or`. The difference is not style:
-- written as `a and b in (…) or not c and d in (…) or not c`, Postgres' precedence (`and` before `or`) makes
-- the whole expression true as soon as *any one* optional key is absent — which is every package that does
-- not set all ten. That accepted `{"tracks_pixels": true}` silently, and a validator that returns true for
-- garbage is worse than no validator, because the caller stops asking. Each clause below is one key, one
-- shape, and an explicit `else true`.
create or replace function public.kicklive_sponsor_entitlements_ok(p_doc jsonb)
returns boolean
language sql immutable
set search_path = public, pg_temp
as $fn$
  select p_doc is null
      or (
        jsonb_typeof(p_doc) = 'object'
        -- No unknown keys. This is the half that protects the renderer: it may switch on a name and treat
        -- anything else as absent, which is only safe if nothing else can be stored.
        and not exists (
          select 1 from jsonb_object_keys(p_doc) k(name)
           where k.name not in (
             'logo_on_screen', 'logo_size', 'banner_on_page', 'mentions_per_match',
             'ad_flight', 'auto_flight', 'priority_default', 'max_per_target',
             'requires_exclusivity', 'naming_rights', 'award_citation'
           )
        )
        and case when p_doc ? 'logo_on_screen'    then p_doc->>'logo_on_screen'    in ('true','false') else true end
        and case when p_doc ? 'banner_on_page'     then p_doc->>'banner_on_page'     in ('true','false') else true end
        and case when p_doc ? 'ad_flight'          then p_doc->>'ad_flight'          in ('true','false') else true end
        and case when p_doc ? 'auto_flight'        then p_doc->>'auto_flight'        in ('true','false') else true end
        and case when p_doc ? 'naming_rights'      then p_doc->>'naming_rights'      in ('true','false') else true end
        and case when p_doc ? 'award_citation'     then p_doc->>'award_citation'     in ('true','false') else true end
        and case when p_doc ? 'requires_exclusivity' then p_doc->>'requires_exclusivity' in ('true','false') else true end
        and case when p_doc ? 'logo_size'          then p_doc->>'logo_size'          in ('small','medium','large') else true end
        and case when p_doc ? 'mentions_per_match' then p_doc->>'mentions_per_match' ~ '^[0-9]$' else true end
        and case when p_doc ? 'priority_default'   then p_doc->>'priority_default'   ~ '^[0-9]{1,4}$' else true end
        and case when p_doc ? 'max_per_target'     then p_doc->>'max_per_target'     ~ '^[0-9]{1,3}$' else true end
      )
$fn$;
-- The above is checked with a full-table scan of the *keys*, not the values, on every write of a package —
-- and packages are written perhaps ten times a season, so the shape of the predicate is not a cost here.

comment on function public.kicklive_sponsor_entitlements_ok(jsonb) is 'Closed entitlement vocabulary. `auto_flight` is reserved for Phase 9 and is deliberately present now: a package that can promise a generated ad flight has to say so before the code exists that writes one, because the alternative is a migration that silently changes what old packages mean.';

-- ----------------------------------------------------------------------------
-- 1 · sponsors
-- ----------------------------------------------------------------------------

create table if not exists public.sponsors (
  id              uuid          primary key default gen_random_uuid(),
  -- The slug is the public handle: `/sponsor/acme`, and the cache key half of every sponsorship read. Once
  -- a sponsorship row or a page link exists it cannot change, which is enforced by a trigger (§6) because
  -- a CHECK cannot look up whether anybody is referring to the old value.
  slug            text          not null,
  display_name    text          not null,
  legal_name      text,
  description     text          check (description is null or char_length(description) <= 600),
  website_url     text          check (public.kicklive_sponsor_https_ok(website_url)),
  status          text          not null default 'draft'
                                constraint sponsors_status_check
                                check (status in ('draft', 'pending', 'approved', 'suspended', 'archived')),
  -- Private (§10): present in the admin list, absent from every projection the browser can reach. The
  -- phone is a business number, not a personal one, and it is still not public.
  contact_name    text          check (contact_name is null or char_length(contact_name) <= 120),
  contact_email   text          check (contact_email is null or (char_length(contact_email) <= 320 and contact_email ~ '^[^[:space:]@]+@[^[:space:]@.]+\.[^[:space:]@]{2,}$')),
  contact_phone   text          check (contact_phone is null or (char_length(contact_phone) <= 32 and contact_phone ~ '^[+0-9 ()./-]{6,}$')),
  contact_consent_at timestamptz,
  -- The brand kit. `logo_url`/`banner_url` hold `/api/media/assets/<key>` paths written by the media plane
  -- and nothing else — a hand-typed absolute URL is how a sponsor's logo ends up hotlinked from a domain
  -- nobody owns. `image_ref`-style allowances live in §7's attach function, not in a CHECK.
  logo_url        text,
  banner_url      text,
  logo_asset_id   bigint        references public.media_assets(id) on delete set null,
  banner_asset_id bigint        references public.media_assets(id) on delete set null,
  brand_colour    text          check (brand_colour is null or brand_colour ~* '^#[0-9a-f]{6}$'),
  on_dark         boolean       not null default false,
  -- Step 8, and the whole of it: an integer a human sets, and the number the renderer sorts by. Not a bid,
  -- not a price, not recomputed from engagement. Default 100 so a new relationship sits in the middle
  -- rather than at the top by accident.
  default_priority smallint     not null default 100 check (default_priority between 0 and 9999),
  -- Agreement fields (§13). Text and a number, never an instrument: no account, no IBAN, no card, no tax id.
  value_amount    numeric(12,2) check (value_amount is null or value_amount >= 0),
  value_currency  text          check (value_currency is null or value_currency ~ '^[A-Z]{3}$'),
  value_basis     text          check (value_basis is null or value_basis in ('negotiated', 'per_season', 'per_match', 'per_month')),
  invoice_reference text        check (invoice_reference is null or char_length(invoice_reference) <= 64),
  renewal_terms   text          check (renewal_terms is null or char_length(renewal_terms) <= 1000),
  internal_notes  text          check (internal_notes is null or char_length(internal_notes) <= 2000),
  approved_by     uuid          references public.profiles(id) on delete set null,
  approved_at     timestamptz,
  created_by      uuid          references public.profiles(id) on delete set null,
  created_at      timestamptz   not null default now(),
  updated_at      timestamptz   not null default now(),
  constraint sponsors_slug_check      check (slug ~ '^[a-z0-9][a-z0-9-]{1,63}$'),
  constraint sponsors_display_name_check check (public.kicklive_sponsor_label_ok(display_name, 120)),
  constraint sponsors_legal_name_check     check (public.kicklive_sponsor_label_ok(legal_name, 200)),
  -- Approval is a fact about a person and a moment, so it is recorded as one pair: no row reaches
  -- `approved` without a named approver. `approved_at` without `approved_by` is what a data import looks
  -- like, and an import should not be able to launder an approval.
  constraint sponsors_approval_recorded check (
    status <> 'approved' or (approved_by is not null and approved_at is not null)
  ),
  -- A logo slot may hold a URL only alongside the asset that produced it, or with neither. The pair is
  -- what makes `kicklive_sponsorship_diagnostics`' orphan count mean something.
  constraint sponsors_logo_pair_check check (
    (logo_url is null or logo_asset_id is not null)
    and (banner_url is null or banner_asset_id is not null)
  )
);
create unique index if not exists sponsors_slug_key on public.sponsors (slug);
create unique index if not exists sponsors_display_name_active_key on public.sponsors (lower(display_name))
  where status <> 'archived';
create index if not exists sponsors_status_idx on public.sponsors (status, default_priority);

comment on table public.sponsors is 'A brand with rights. Phase 7 `advertisers` is the paid-placement equivalent and is deliberately a different table: an advertiser buys a slot for a fortnight, a sponsor is associated with the competition, and the two sets of fields (rotation weights vs. season and exclusivity) do not overlap enough to share a row.';
comment on column public.sponsors.contact_email is 'Private. Excluded from every projection a browser can reach, by not being named in it (§7).';
comment on column public.sponsors.value_amount is 'What the contract says, to the kobo. Not a ledger: no invoice, no payment, no balance, and no column that could hold one.';

-- ----------------------------------------------------------------------------
-- 2 · sponsorship packages (step 3: configurable, seeded, not enumerated)
-- ----------------------------------------------------------------------------

create table if not exists public.sponsorship_packages (
  id              uuid          primary key default gen_random_uuid(),
  -- `code` is the stable name and `label` is the display one, so renaming "MAIN SPONSOR" to "PREMIER
  -- PARTNER" is a label edit that breaks no reference. Both are free text within shape limits — the brief's
  -- requirement is that the names are configurable, which a CHECK over six literals would have quietly
  -- contradicted.
  code            text          not null,
  label           text          not null,
  description     text          check (description is null or char_length(description) <= 500),
  -- What kind of relationship this is, for filtering and for the renderer's wording. Free-form within a
  -- shape, and seeded with the brief's six.
  kind            text          not null,
  tier            smallint      not null default 3 check (tier between 1 and 9),
  season_label    text          check (season_label is null or char_length(season_label) <= 24),
  exclusivity     text          not null default 'none'
                                constraint sponsorship_packages_exclusivity_check
                                check (exclusivity in ('none', 'category', 'package', 'exclusive')),
  entitlements    jsonb         not null default '{}'::jsonb check (public.kicklive_sponsor_entitlements_ok(entitlements)),
  -- Ordering *of the packages themselves* in a picker; `sponsorships.priority` is the ordering on the page.
  sort_order      smallint      not null default 100,
  is_active       boolean       not null default true,
  -- Price, again as a stated intention rather than a bill (step 13).
  price_amount    numeric(12,2) check (price_amount is null or price_amount >= 0),
  price_currency  text          check (price_currency is null or price_currency ~ '^[A-Z]{3}$'),
  price_basis     text          check (price_basis is null or price_basis in ('negotiated', 'per_season', 'per_match', 'per_month', 'one_off')),
  created_at      timestamptz   not null default now(),
  updated_at      timestamptz   not null default now(),
  constraint sponsorship_packages_code_check  check (code ~ '^[a-z][a-z0-9_]{1,31}$'),
  constraint sponsorship_packages_kind_check  check (kind ~ '^[a-z][a-z0-9_]{1,31}$'),
  constraint sponsorship_packages_label_check check (public.kicklive_sponsor_label_ok(label, 80)),
  -- What a package may be sold against. A closed set, because it decides which `target_kind` values an
  -- assignment may use for this package — the pair (package kind, target kind) is checked in §5's save.
  allowed_target_kinds text[]   not null default array['competition','season','match','team','award','event']::text[]
                                check (array_length(allowed_target_kinds, 1) between 1 and 6)
);
create unique index if not exists sponsorship_packages_code_key on public.sponsorship_packages (code);
create index if not exists sponsorship_packages_active_idx on public.sponsorship_packages (is_active, sort_order, tier);

comment on table public.sponsorship_packages is 'The rate card. Names are data, not code: nothing in the Worker or the SPA switches on a package code, and the six seeded rows are the brief''s examples rather than an enum.';

insert into public.sponsorship_packages (code, label, kind, tier, exclusivity, sort_order, description, allowed_target_kinds, entitlements)
values
  ('title',        'Title Sponsor',   'title',        1, 'exclusive', 10,
   'The name on the competition. Highest placement, one per target, and the only package whose entitlement set includes naming rights.',
   array['competition','season','event']::text[],
   '{"logo_on_screen": true, "logo_size": "large", "banner_on_page": true, "naming_rights": true, "mentions_per_match": 6, "requires_exclusivity": true, "max_per_target": 1, "priority_default": 10}'::jsonb),
  ('main',         'Main Sponsor',      'main',         2, 'category',  20,
   'Shared top billing alongside the title sponsor, in a different commercial category.',
   array['competition','season','event']::text[],
   '{"logo_on_screen": true, "logo_size": "medium", "banner_on_page": true, "mentions_per_match": 3, "requires_exclusivity": true, "max_per_target": 3, "priority_default": 40}'::jsonb),
  ('match',        'Match Sponsor',     'match',        3, 'none',      30,
   'One fixture. Shown on the match page and read out around kickoff.',
   array['match']::text[],
   '{"logo_on_screen": true, "logo_size": "medium", "banner_on_page": false, "mentions_per_match": 2, "requires_exclusivity": false, "max_per_target": 4, "priority_default": 70}'::jsonb),
  ('team',         'Team Sponsor',      'team',         4, 'category',  40,
   'Attached to a club, so it follows the club across competitions and renders wherever a crest renders.',
   array['team']::text[],
   '{"logo_on_screen": true, "logo_size": "small", "banner_on_page": true, "mentions_per_match": 1, "requires_exclusivity": true, "max_per_target": 2, "priority_default": 80}'::jsonb),
  ('award',        'Award Sponsor',     'award',        5, 'package',   50,
   'Named with a trophy or an individual award, and cited when the award is presented.',
   array['award','event']::text[],
   '{"logo_on_screen": true, "logo_size": "small", "award_citation": true, "requires_exclusivity": true, "max_per_target": 1, "priority_default": 60}'::jsonb),
  ('media_partner','Media Partner',     'media_partner', 6, 'none',      60,
   'Exchange of reach rather than money: the partner carries us, we carry their logo. No price, and the public band is smaller.',
   array['competition','season','match','event']::text[],
   '{"logo_on_screen": false, "logo_size": "small", "banner_on_page": false, "requires_exclusivity": false, "max_per_target": 8, "priority_default": 200}'::jsonb)
on conflict (code) do nothing;

-- ----------------------------------------------------------------------------
-- 3 · sponsorships (step 4: one relationship table, not six)
-- ----------------------------------------------------------------------------

create table if not exists public.sponsorships (
  id              uuid          primary key default gen_random_uuid(),
  sponsor_id      uuid          not null references public.sponsors(id) on delete restrict,
  package_id      uuid          not null references public.sponsorship_packages(id) on delete restrict,
  -- The polymorphic pair. Six separate tables (sponsorship_competitions, sponsorship_teams, …) would each
  -- need their own status machine, their own expiry pass, their own admin screen and their own leak; and
  -- "what is showing on this page" would become a union of six queries. One pair of columns, resolved by a
  -- function that knows which table each kind means, costs one trigger instead.
  target_kind     text          not null check (public.kicklive_sponsor_target_kind_ok(target_kind)),
  target_id       text          not null,
  -- `starts_at`/`ends_at` are DATEs, not timestamps: a sponsorship is bought by the day and a half-day
  -- boundary in UTC is how a "season" becomes an argument at 23:30 local time.
  starts_at       date          not null,
  ends_at         date          not null,
  status          text          not null default 'draft'
                                constraint sponsorships_status_check
                                check (status in ('draft', 'scheduled', 'active', 'paused', 'ended', 'archived')),
  -- The display switch. Distinct from `status` for the same reason `ad_placements.is_active` is: an
  -- operator must be able to take a live sponsorship off the site without editing the contract's state,
  -- and put it back without re-approval.
  is_active       boolean       not null default false,
  activated_by    uuid          references public.profiles(id) on delete set null,
  activated_at    timestamptz,
  -- Step 8: controlled order, nothing else. Lower priority sorts first; equal priorities fall back to the
  -- assignment date so the order is stable rather than whatever the planner produced.
  priority        smallint      not null default 100 check (priority between 0 and 9999),
  display_order   integer       not null default 0 check (display_order between 0 and 999999),
  -- What the page says, verbatim, in the sponsor's words as approved. Kept per assignment rather than on the
  -- sponsor because a title sponsorship and a match sponsorship do not describe the same relationship.
  attribution     text          check (public.kicklive_sponsor_label_ok(attribution, 160)),
  -- `naming_override` is how "the Cup, presented by X" is done without touching `competitions.name`:
  -- the canonical name stays the canonical name, and a display label is a display label.
  naming_override text          check (public.kicklive_sponsor_label_ok(naming_override, 120)),
  -- Per-placement branding overrides (step 6), so a dark stadium banner and a light archive page can carry
  -- the right artwork without the sponsor's record holding two versions of the truth.
  logo_asset_id   bigint        references public.media_assets(id) on delete set null,
  banner_asset_id bigint        references public.media_assets(id) on delete set null,
  logo_variant    text          check (logo_variant is null or logo_variant in ('default', 'mono', 'light', 'dark')),
  background_colour text        check (background_colour is null or background_colour ~* '^#[0-9a-f]{6}$'),
  link_url        text          check (link_url is null or public.kicklive_sponsor_https_ok(link_url)),
  -- The Phase 9 seam (see the header): a package may generate an advertising flight, and this is where the
  -- generated one is remembered. Nullable, written by nobody today, and `on delete set null` so removing
  -- a campaign can never delete a contract.
  advertisement_campaign_id uuid references public.advertisement_campaigns(id) on delete set null,
  -- §13 again: what the paperwork says, not what the bank says.
  value_amount    numeric(12,2) check (value_amount is null or value_amount >= 0),
  value_currency  text          check (value_currency is null or value_currency ~ '^[A-Z]{3}$'),
  value_basis     text          check (value_basis is null or value_basis in ('negotiated', 'per_season', 'per_match', 'per_month')),
  invoice_reference text        check (invoice_reference is null or char_length(invoice_reference) <= 64),
  renewal_terms   text          check (renewal_terms is null or char_length(renewal_terms) <= 1000),
  internal_notes  text          check (internal_notes is null or char_length(internal_notes) <= 2000),
  activation_error text,
  created_by      uuid          references public.profiles(id) on delete set null,
  created_at      timestamptz   not null default now(),
  updated_at      timestamptz   not null default now(),
  -- Only rules that can be true without looking anything up live here. "The sponsor is approved", "the
  -- package allows this kind", "the exclusivity slot is free" are §5 and §6 work, because each needs a
  -- second table and a CHECK may not read one.
  constraint sponsorships_window_ordered check (ends_at >= starts_at),
  constraint sponsorships_target_id_check check (public.kicklive_sponsor_target_id_ok(target_kind, target_id))
);
create index if not exists sponsorships_target_idx on public.sponsorships (target_kind, target_id, status, priority, display_order);
create index if not exists sponsorships_sponsor_idx on public.sponsorships (sponsor_id, status, ends_at);
create index if not exists sponsorships_expiry_idx on public.sponsorships (ends_at) where status in ('scheduled', 'active');
-- The double-booking guard, as an index rather than a trigger: the same sponsor may not hold the same
-- package against the same target for two windows starting on the same day, which is what a re-typed
-- renewal looks like in this table. Partial on purpose — an archived row must stay to explain history.
create unique index if not exists sponsorships_no_duplicate_key
  on public.sponsorships (sponsor_id, package_id, target_kind, target_id, starts_at)
  where status <> 'archived';

comment on column public.sponsorships.target_id is 'Text, because ids in this schema are not one type (competitions are integer, awards do not have a table). `kicklive_sponsor_target_exists` is what gives it meaning.';
comment on column public.sponsorships.advertisement_campaign_id is 'The documented seam to Phase 7. Nothing writes it in this migration; a generated flight is linked here so the two systems stay joinable without becoming one.';

-- ----------------------------------------------------------------------------
-- 4 · the status machine (Phase 7's lesson, applied with a `kind` column)
-- ----------------------------------------------------------------------------

create table if not exists public.sponsorship_status_transitions (
  kind        text        not null check (kind in ('sponsor', 'sponsorship')),
  from_status text        not null,
  to_status   text        not null,
  note        text,
  primary key (kind, from_status, to_status)
);

-- Read as `exists (kind, from, to)`: an absent row is a prohibition, so a row must never be inserted to
-- document something that is forbidden (Phase 7 learned that the hard way).
insert into public.sponsorship_status_transitions (kind, from_status, to_status, note) values
  ('sponsor', 'draft',     'pending',   'submitted for approval'),
  ('sponsor', 'draft',     'archived',  'nothing signed'),
  ('sponsor', 'pending',   'draft',     'back to editing'),
  ('sponsor', 'pending',   'approved',  'the approval act; stamps approved_by/at'),
  ('sponsor', 'pending',   'archived',  'declined'),
  ('sponsor', 'approved',  'suspended', 'refused new placements; existing ones are paused by the cascade'),
  ('sponsor', 'approved',  'archived',  'relationship over'),
  ('sponsor', 'suspended', 'approved',  'reinstatement is an explicit admin act, not a timeout'),
  ('sponsor', 'suspended', 'archived',  null),
  ('sponsorship', 'draft',     'scheduled', 'agreed and dated; not displaying yet'),
  ('sponsorship', 'draft',     'archived',  null),
  ('sponsorship', 'scheduled', 'active',    'the display act; preconditions run here'),
  ('sponsorship', 'scheduled', 'draft',     'back to editing'),
  ('sponsorship', 'scheduled', 'archived',  'cancelled before it ran'),
  ('sponsorship', 'active',    'paused',    'off the site immediately, contract intact'),
  ('sponsorship', 'active',    'ended',     'normal end of term (also set by kicklive_sponsorship_expire_due)'),
  ('sponsorship', 'active',    'archived',  'withdrawn'),
  ('sponsorship', 'paused',    'active',    're-activation re-runs the preconditions'),
  ('sponsorship', 'paused',    'ended',     null),
  ('sponsorship', 'paused',    'archived',  null),
  ('sponsorship', 'ended',     'active',    'a renewal inside the same window; the clock has to allow it'),
  ('sponsorship', 'ended',     'archived',  null)
on conflict (kind, from_status, to_status) do nothing;

comment on table public.sponsorship_status_transitions is 'Two machines in one table, discriminated by `kind`: a sponsor (the brand) and a sponsorship (one placement of that brand) are different lifecycles, and sharing arcs between them is how "archived sponsor can be re-approved" appears in a system that never meant to allow it.';

-- ----------------------------------------------------------------------------
-- 5 · the config row: an epoch for cache invalidation
-- ----------------------------------------------------------------------------

create table if not exists public.sponsorship_config (
  id          smallint primary key check (id = 1),
  epoch       bigint   not null default 1,
  updated_at  timestamptz not null default now(),
  constraint sponsorship_config_singleton check (id = 1)
);
insert into public.sponsorship_config (id, epoch) values (1, 1) on conflict (id) do nothing;

comment on table public.sponsorship_config is 'One row, one counter. Every write that changes what a viewer would see bumps it, and the public read carries it. Without it, "invalidate the cache when the configuration changes" needs a purge API credential in the Worker for one image; with it, an edge entry can be checked against the state of the data that produced it, and the browser''s own cache is tagged and invalidated from the mutation (§11).';

-- ----------------------------------------------------------------------------
-- 6 · triggers
-- ----------------------------------------------------------------------------

create or replace function public.kicklive_sponsor_guard_target()
returns trigger
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
begin
  -- `award` and `event` have no table yet, and that is a decision rather than an omission: a rights record
  -- for "Goal of the Month" must exist before there is a row to point at, and a foreign key to a table that
  -- does not exist would have forced one to be created with the wrong shape. Those two kinds are therefore
  -- validated for *format* only (§0), and the four that do have tables are validated for existence.
  if new.target_kind in ('award', 'event') then
    return new;
  end if;
  if not public.kicklive_sponsor_target_exists(new.target_kind, new.target_id) then
    raise exception 'sponsorship target %/% does not exist', new.target_kind, new.target_id
      using hint = 'the sponsor cannot be associated with a ' || new.target_kind || ' that is not in the database';
  end if;
  return new;
end
$fn$;

create or replace function public.kicklive_sponsor_target_exists(p_kind text, p_id text)
returns boolean
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- One function, four tables, and no dynamic SQL: a `format('… from %I', …)` built from a user value is
  -- how a lookup function turns into an injection sink, and the set of kinds is closed above anyway.
  select case p_kind
    when 'competition' then exists (select 1 from public.competitions c  where c.id::text = p_id)
    when 'season'      then exists (select 1 from public.seasons s       where s.id::text = p_id)
    when 'team'        then exists (select 1 from public.teams t         where t.id::text = p_id)
    when 'match'       then exists (select 1 from public.matches m       where m.id::text = p_id)
    else false
  end
$fn$;
-- A correction worth keeping in the file, because the reasoning was wrong in a way that a reviewer would
-- otherwise have to rediscover: an earlier draft of this function pointed `season` at `competitions`, on the
-- assertion that the schema has no seasons table. It does — `public.seasons`, which `matches.season_id`
-- already references. Pointing a sponsorship at `competitions.season`, a free-text label, would have meant
-- the competition office renaming "2025/26" to "2025-26" and every title sponsorship silently detaching from
-- the thing it pays for. Ids are the only durable join in this schema, and `target_kind` exists precisely so
-- each kind can be aimed at the table that owns it.

-- The drop carries the *trigger's* name, not the function's, and the difference is the whole failure mode: `drop
-- trigger if exists <function_name>` is a successful no-op, so the create below it fails on a re-run. The
-- names are kept visibly paired (`…_guard_target` → `sponsorships_guard_target`) so the pairing can be read.
drop trigger if exists sponsorships_guard_target on public.sponsorships;
create trigger sponsorships_guard_target
  before insert or update of target_kind, target_id on public.sponsorships
  for each row execute function public.kicklive_sponsor_guard_target();

-- A slug is a URL and a cache key. Once referenced it is immutable, and the reason to enforce that in the
-- database rather than in the form is that the form is not the only writer.
create or replace function public.kicklive_sponsor_guard_slug()
returns trigger
language plpgsql volatile
security invoker
set search_path = public, pg_temp
as $fn$
begin
  if new.slug is distinct from old.slug then
    raise exception 'sponsor slug is immutable once created'
      using hint = 'archive this sponsor and create a new one; a renamed slug breaks every page link and every cached read that used the old one';
  end if;
  return new;
end
$fn$;

drop trigger if exists sponsors_guard_slug on public.sponsors;
create trigger sponsors_guard_slug
  before update of slug on public.sponsors
  for each row execute function public.kicklive_sponsor_guard_slug();

-- A package code is the same kind of promise: `allowed_target_kinds` and `entitlements` may change (that is
-- what re-pricing a package is), but the identifier may not be recycled under an existing assignment.
create or replace function public.kicklive_sponsor_guard_package_code()
returns trigger
language plpgsql volatile
security invoker
set search_path = public, pg_temp
as $fn$
begin
  if new.code is distinct from old.code and exists (
    select 1 from public.sponsorships s where s.package_id = old.id
  ) then
    raise exception 'package % is referenced by % sponsorship(s) and cannot be renamed', old.code, (
      select count(1) from public.sponsorships s where s.package_id = old.id
    );
  end if;
  if not new.is_active and exists (
    select 1 from public.sponsorships s where s.package_id = old.id and s.status in ('scheduled', 'active')
  ) then
    raise exception 'package % still has scheduled or active sponsorships; end those first', new.code;
  end if;
  return new;
end
$fn$;

drop trigger if exists sponsorship_packages_guard_code on public.sponsorship_packages;
create trigger sponsorship_packages_guard_code
  before update on public.sponsorship_packages
  for each row execute function public.kicklive_sponsor_guard_package_code();

-- `updated_at`, same helper every phase has used since Phase 1.
drop trigger if exists sponsors_touch_updated_at on public.sponsors;
create trigger sponsors_touch_updated_at
  before update on public.sponsors
  for each row execute function public.touch_updated_at();
drop trigger if exists sponsorships_touch_updated_at on public.sponsorships;
create trigger sponsorships_touch_updated_at
  before update on public.sponsorships
  for each row execute function public.touch_updated_at();
drop trigger if exists packages_touch_updated_at on public.sponsorship_packages;
create trigger packages_touch_updated_at
  before update on public.sponsorship_packages
  for each row execute function public.touch_updated_at();

-- ----------------------------------------------------------------------------
-- 7 · the public read
-- ----------------------------------------------------------------------------

create or replace function public.kicklive_sponsorship_epoch()
returns bigint
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  select coalesce(max(c.epoch), 1) from public.sponsorship_config c
$fn$;

create or replace function public.kicklive_sponsorship_for(
  p_target_kind text,
  p_target_ids  text[] default null,
  p_limit       integer default 12
)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_ids   text[];
  v_epoch bigint;
  v_rows  jsonb;
begin
  if not public.kicklive_sponsor_target_kind_ok(p_target_kind) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'kind', 'reason', 'UNKNOWN_TARGET_KIND',
                              'allowed', jsonb_build_array('competition', 'season', 'match', 'team', 'award', 'event'));
  end if;
  -- One page, or one explicit set of ids (a match list page wants its fixtures' sponsors in one round
  -- trip). Never "everything": `p_target_ids` is required for the multi-id form and capped, because an
  -- unbounded "give me the sponsors of all matches" is a season's worth of rows for a page that shows ten.
  if p_target_ids is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'ids', 'reason', 'TARGET_IDS_REQUIRED',
                              'detail', 'name the target the page is about; a sponsorship is only meaningful against one thing');
  end if;
  if array_length(p_target_ids, 1) is null or array_length(p_target_ids, 1) > 50 then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'ids', 'reason', 'TARGET_IDS_OUT_OF_RANGE',
                              'detail', '1 to 50 ids per call');
  end if;
  v_ids := p_target_ids;
  v_epoch := public.kicklive_sponsorship_epoch();

  -- The projection is written out column by column, and that is the security control for step 10. A
  -- `to_jsonb(s)` would hand a viewer whatever the next migration adds to `sponsors` — including
  -- `contact_email`, which is why this function has an explicit list and why a test asserts that the
  -- private columns are not named in it.
  select coalesce(
    jsonb_agg(jsonb_build_object(
      'sponsorshipId', s.id,
      'sponsorId', sp.id,
      'slug', sp.slug,
      'name', coalesce(nullif(btrim(sp.display_name), ''), sp.legal_name),
      'attribution', coalesce(nullif(btrim(s.attribution), ''), p.label),
      'packageCode', p.code,
      'packageLabel', p.label,
      'packageKind', p.kind,
      'tier', p.tier,
      'logoUrl', coalesce(kicklive_asset_url_for_asset(l.id), sp.logo_url),
      'bannerUrl', coalesce(kicklive_asset_url_for_asset(b.id), sp.banner_url),
      'brandColour', coalesce(s.background_colour, sp.brand_colour),
      'onDark', sp.on_dark,
      -- A sponsor's own link, or the one the assignment chose. https was enforced on write, and it is
      -- re-checked on read: the column predates that rule for any row imported before this migration.
      'href', case when public.kicklive_sponsor_https_ok(coalesce(nullif(s.link_url, ''), sp.website_url))
                   then coalesce(nullif(s.link_url, ''), sp.website_url) end,
      'rel', 'noopener external',
      'namingOverride', nullif(s.naming_override, ''),
      'priority', s.priority,
      'displayOrder', s.display_order,
      'startsAt', s.starts_at,
      'endsAt', s.ends_at,
      'targetKind', s.target_kind,
      'targetId', s.target_id
    ) order by s.priority asc, s.display_order asc, s.starts_at desc, s.id)
      -- Cap first, then aggregate: `limit` inside the aggregate would need a subquery per row, and the
      -- order matters — a truncated answer must be the *highest-priority* rows, not the first ones the
      -- planner happened to visit.
    , '[]'::jsonb
  ) into v_rows
  from (
    select *
      from (
        select x.*, row_number() over (
                 partition by x.target_id
                 order by x.priority asc, x.display_order asc, x.starts_at desc, x.id
               ) as rn
          from (
            select sn.id, sn.sponsor_id, sn.package_id, sn.priority, sn.display_order, sn.starts_at, sn.ends_at,
                   sn.attribution, sn.naming_override, sn.link_url, sn.logo_asset_id, sn.banner_asset_id,
                   sn.background_colour, sn.target_kind, sn.target_id
              from public.sponsorships sn
              join public.sponsors sp2 on sp2.id = sn.sponsor_id and sp2.status = 'approved'
              join public.sponsorship_packages pk on pk.id = sn.package_id and pk.is_active
             where sn.status = 'active'
               and sn.is_active
               and sn.target_kind = p_target_kind
               and sn.target_id = any (v_ids)
               and current_date between sn.starts_at and sn.ends_at
           ) x
       ) ranked
      where ranked.rn <= greatest(1, least(coalesce(p_limit, 12), 24))
      order by ranked.priority asc, ranked.display_order asc, ranked.starts_at desc, ranked.id
  ) s
  join public.sponsors sp          on sp.id = s.sponsor_id
  join public.sponsorship_packages p on p.id = s.package_id
  left  join public.media_assets l  on l.id = s.logo_asset_id
  left  join public.media_assets b  on b.id = s.banner_asset_id;

  return jsonb_build_object(
    'ok', true,
    'sponsors', v_rows,
    'epoch', v_epoch,
    'maxAgeSeconds', 120,
    'note', 'ordered by priority then display order; expired and inactive rows are filtered here, not hidden by the client'
  );
end
$fn$;

-- The one helper the public read needs that Phase 6 does not offer: an asset id rendered as a URL, without
-- the caller having to know the object key. Kept tiny and stable, and named for what it does so nobody
-- mistakes it for the access-control check (`kicklive_asset_authorized` is that one).
create or replace function public.kicklive_asset_url_for_asset(p_asset_id bigint)
returns text
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  -- SECURITY DEFINER because `media_assets` grants nothing to any client role, and Phase 6's verify block
  -- requires that any `kicklive_*asset*` function be a definer one rather than an invoker one that quietly
  -- returns NULL for everyone outside the owner. The visibility predicate is what makes the definer-ness
  -- safe: an id may not be traded for the key of a private object, which is the one question this function
  -- could otherwise answer.
  select case when a.status in ('ready', 'superseded') and a.object_key is not null and a.visibility = 'public'
              then '/api/media/assets/' || a.object_key end
    from public.media_assets a
   where a.id = p_asset_id
$fn$;

-- ----------------------------------------------------------------------------
-- 8 · the writers
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 5b · the public rate card
-- ----------------------------------------------------------------------------

-- What a package promises, never what it costs. This function exists so that the *projection* is the
-- security control: the columns it selects are the only ones a browser can ask for, so a future writer that
-- adds `price_amount` to the table cannot accidentally publish it through this read, and the admin list can
-- keep carrying the money columns because its reader is the desk. One `select` and no parameters also means
-- there is no argument to validate, which is why the public surface is this small.
create or replace function public.kicklive_sponsor_package_card()
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  select jsonb_build_object(
           'ok', true,
           'epoch', public.kicklive_sponsorship_epoch(),
           'packages', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'code', p.code,
                      'label', p.label,
                      'description', p.description,
                      'kind', p.kind,
                      'tier', p.tier,
                      'season_label', p.season_label,
                      'exclusivity', p.exclusivity,
                      'allowed_target_kinds', to_jsonb(p.allowed_target_kinds),
                      'entitlements', p.entitlements
                    ) order by p.sort_order, p.tier, p.code)
               from public.sponsorship_packages p
              where p.is_active
           ), '[]'::jsonb)
         )
$fn$;

comment on function public.kicklive_sponsor_package_card() is
  'The published rate card: active packages, description and entitlements only. Price columns are not in the select list, so they are unreachable rather than filtered; the admin list is the surface that carries them.';

create or replace function public.kicklive_sponsor_save(p_data jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_id      uuid := nullif(p_data->>'id', '')::uuid;
  v_row     public.sponsors;
  v_new     public.sponsors;
  v_caller  uuid := auth.uid();
  v_slug    text;
  v_missing text[] := '{}';
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'reason', 'BODY_MUST_BE_OBJECT');
  end if;

  -- A caller may not approve their own work, and may not set a status at all from the save path: approval is
  -- `kicklive_sponsor_set_status`, so the audit trail has one door instead of two.
  if p_data ? 'status' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'status', 'reason', 'STATUS_VIA_SET_STATUS_ONLY',
                              'detail', 'a sponsor is approved or suspended by the status route, which records who did it');
  end if;
  if p_data ? 'approved_by' or p_data ? 'approved_at' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'reason', 'APPROVAL_IS_NOT_EDITABLE');
  end if;
  -- The two branding URLs are derived, never typed. A save that quietly ignored `logoUrl` would be worse than
  -- one that refused it: the desk would read `ok: true`, and the badge would not have changed, with the
  -- reason sitting three tables away in a bucket listing. Uploading is
  -- `kicklive_sponsor_reserve_asset` then `kicklive_sponsor_attach_asset` — which is also the only path where
  -- the URL is known to point at an object that exists and belongs to this sponsor.
  if p_data ? 'logoUrl' or p_data ? 'logo_url' or p_data ? 'bannerUrl' or p_data ? 'banner_url' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED',
                              'field', case when p_data ? 'bannerUrl' or p_data ? 'banner_url' then 'bannerUrl' else 'logoUrl' end,
                              'reason', 'BRANDING_IS_UPLOADED_NOT_TYPED');
  end if;

  select * into v_row from public.sponsors s where s.id = v_id;
  if v_id is not null and not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'SPONSOR_UNKNOWN');
  end if;

  v_slug := lower(btrim(coalesce(p_data->>'slug', v_row.slug, '')));
  if v_slug = '' then
    -- Derive it from the display name rather than demanding it: the field a human types is the name, and a
    -- slug nobody checked is how `/sponsor/acme-bak-2` ends up in a nav bar.
    v_slug := regexp_replace(lower(btrim(coalesce(p_data->>'displayName', p_data->>'display_name', v_row.display_name, ''))), '[^a-z0-9]+', '-', 'g');
    v_slug := btrim(v_slug, '-');
    v_slug := left(v_slug, 64);
    if v_slug !~ '^[a-z0-9][a-z0-9-]{1,63}$' then
      select array_append(v_missing, 'slug') into v_missing;
    end if;
  end if;
  if v_row.id is not null and v_slug <> v_row.slug then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'slug', 'reason', 'SLUG_IMMUTABLE');
  end if;

  if coalesce(p_data->>'displayName', p_data->>'display_name', v_row.display_name, '') = '' then
    select array_append(v_missing, 'displayName') into v_missing;
  end if;
  if array_length(v_missing, 1) is not null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'reason', 'REQUIRED_FIELDS', 'missing', to_jsonb(v_missing));
  end if;
  -- A cast failure inside the insert arrives as a raised exception, which the Worker can only report as a
  -- 502. `{"defaultPriority": "high"}` is a client bug, and a client bug deserves a field name.
  if public.kicklive_sponsor_field_refuses(p_data, array['defaultPriority', 'valueAmount', 'logoAssetId', 'bannerAssetId']) is not null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', public.kicklive_sponsor_field_refuses(p_data, array['defaultPriority', 'valueAmount', 'logoAssetId', 'bannerAssetId']), 'reason', 'NUMBER_REQUIRED');
  end if;
  if p_data ? 'websiteUrl' and not public.kicklive_sponsor_https_ok(p_data->>'websiteUrl') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'websiteUrl', 'reason', 'HTTPS_URL_WITH_HOST_REQUIRED');
  end if;
  if p_data ? 'brandColour' and coalesce(p_data->>'brandColour', '') !~* '^#[0-9a-f]{6}$' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'brandColour', 'reason', 'HEX_COLOUR_REQUIRED');
  end if;
  -- Validated *after* normalisation, not before. The table stores `lower(btrim(…))`, so a check against the
  -- raw field would refuse `"ads@flow.example "` — a trailing space from a paste — and then accept exactly
  -- that value on the next keystroke, because the second request has no space. The rule belongs to the form
  -- the value ends up in, which is why it reads the same expression the insert writes.
  if p_data ? 'contactEmail'
     and btrim(coalesce(p_data->>'contactEmail', '')) <> ''
     and lower(btrim(p_data->>'contactEmail')) !~ '^[^[:space:]@]+@[^[:space:]@.]+\.[^[:space:]@]{2,}$' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'contactEmail', 'reason', 'EMAIL_UNPARSEABLE');
  end if;

  insert into public.sponsors (
    slug, display_name, legal_name, description, website_url,
    contact_name, contact_email, contact_phone, contact_consent_at,
    brand_colour, on_dark, default_priority,
    value_amount, value_currency, value_basis, invoice_reference, renewal_terms, internal_notes,
    status, created_by
  ) values (
    v_slug,
    btrim(coalesce(p_data->>'displayName', p_data->>'display_name', v_row.display_name)),
    nullif(btrim(coalesce(p_data->>'legalName', p_data->>'legal_name', v_row.legal_name, '')), ''),
    nullif(btrim(coalesce(p_data->>'description', v_row.description, '')), ''),
    nullif(btrim(coalesce(p_data->>'websiteUrl', p_data->>'website_url', v_row.website_url, '')), ''),
    nullif(btrim(coalesce(p_data->>'contactName', v_row.contact_name, '')), ''),
    lower(nullif(btrim(coalesce(p_data->>'contactEmail', v_row.contact_email, '')), '')),
    nullif(btrim(coalesce(p_data->>'contactPhone', v_row.contact_phone, '')), ''),
    case when p_data ? 'contactConsentAt' then (p_data->>'contactConsentAt')::timestamptz else v_row.contact_consent_at end,
    nullif(btrim(coalesce(p_data->>'brandColour', v_row.brand_colour, '')), ''),
    coalesce((p_data->>'onDark')::boolean, v_row.on_dark, false),
    greatest(0, least(9999, coalesce((p_data->>'defaultPriority')::smallint, v_row.default_priority, 100))),
    coalesce((p_data->>'valueAmount')::numeric(12,2), v_row.value_amount),
    upper(nullif(btrim(coalesce(p_data->>'valueCurrency', v_row.value_currency, '')), '')),
    nullif(btrim(coalesce(p_data->>'valueBasis', v_row.value_basis, '')), ''),
    nullif(btrim(coalesce(p_data->>'invoiceReference', v_row.invoice_reference, '')), ''),
    nullif(btrim(coalesce(p_data->>'renewalTerms', v_row.renewal_terms, '')), ''),
    nullif(btrim(coalesce(p_data->>'internalNotes', v_row.internal_notes, '')), ''),
    'draft',
    v_caller
  )
  on conflict (slug) do update set
    display_name    = excluded.display_name,
    legal_name      = excluded.legal_name,
    description     = excluded.description,
    website_url     = excluded.website_url,
    contact_name    = excluded.contact_name,
    contact_email   = excluded.contact_email,
    contact_phone   = excluded.contact_phone,
    contact_consent_at = excluded.contact_consent_at,
    brand_colour    = excluded.brand_colour,
    on_dark         = excluded.on_dark,
    default_priority = excluded.default_priority,
    value_amount    = excluded.value_amount,
    value_currency  = excluded.value_currency,
    value_basis     = excluded.value_basis,
    invoice_reference = excluded.invoice_reference,
    renewal_terms   = excluded.renewal_terms,
    internal_notes  = excluded.internal_notes,
    updated_at      = now()
  returning * into v_new;

  -- A *new* sponsor must land as `draft`; the upsert above can only ever change content, so the status of an
  -- existing row survives an edit untouched, which is the property the two-verb API depends on.
  perform public.kicklive_sponsorship_touch_epoch(v_row.id is null);

  return jsonb_build_object(
    'ok', true,
    'created', v_row.id is null,
    'sponsor', to_jsonb(v_new) - 'contact_email' - 'contact_phone' - 'contact_name' - 'internal_notes'
  );
end
$fn$;

-- The epoch writer. Separate because five functions need it and because a trigger that bumps a global row
-- on every write is a lock nobody thought about: `true` for a change a viewer can see, `false` for an
-- internal note.
create or replace function public.kicklive_sponsorship_touch_epoch(p_visible boolean)
returns bigint
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_epoch bigint;
begin
  if not coalesce(p_visible, false) then
    return public.kicklive_sponsorship_epoch();
  end if;
  update public.sponsorship_config c
     set epoch = c.epoch + 1, updated_at = now()
   where c.id = 1
  returning c.epoch into v_epoch;
  return coalesce(v_epoch, 1);
end
$fn$;

create or replace function public.kicklive_sponsor_set_status(p_id uuid, p_status text, p_reason text default null)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row public.sponsors;
  v_allowed boolean;
  v_affected integer := 0;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_row from public.sponsors s where s.id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'SPONSOR_UNKNOWN');
  end if;
  select exists (
    select 1 from public.sponsorship_status_transitions t
     where t.kind = 'sponsor' and t.from_status = v_row.status and t.to_status = p_status
  ) into v_allowed;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'status', 'reason', 'TRANSITION_NOT_ALLOWED',
                              'detail', v_row.status || ' -> ' || coalesce(p_status, 'null'),
                              -- `coalesce` to an empty array, not NULL: "there is nowhere to go from here" is
                              -- an answer a client can render, and `allowed.map` must not need a guard to find
                              -- out that a record is terminal.
                              'allowed', coalesce(to_jsonb((select array_agg(t.to_status) from public.sponsorship_status_transitions t
                                                              where t.kind = 'sponsor' and t.from_status = v_row.status)), '[]'::jsonb));
  end if;
  if p_status = 'suspended' and p_reason is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'reason', 'reason', 'REASON_REQUIRED',
                              'detail', 'a suspension is a decision with a consequence; write down which one');
  end if;

  update public.sponsors s
     set status = p_status,
         approved_by = case when p_status = 'approved' then auth.uid() else s.approved_by end,
         approved_at = case when p_status = 'approved' then now() else s.approved_at end,
         internal_notes = case when p_reason is not null and p_status = 'suspended'
                              then btrim(coalesce(s.internal_notes || E'\n', '') || 'suspended: ' || p_reason)
                              else s.internal_notes end,
         updated_at = now()
   where s.id = p_id
   returning * into v_row;

  -- The cascade that makes the status mean something: a sponsor that is not approved may not be displayed,
  -- so every live placement of theirs goes off the site in the same transaction. Leaving them `active` is
  -- how a suspended brand stays on the banner for the rest of the season.
  if p_status in ('suspended', 'archived') then
    update public.sponsorships sn
       set status = 'paused', is_active = false, updated_at = now()
     where sn.sponsor_id = p_id and sn.status = 'active';
    get diagnostics v_affected = row_count;
  end if;

  perform public.kicklive_sponsorship_touch_epoch(true);
  return jsonb_build_object('ok', true, 'sponsor', to_jsonb(v_row) - 'contact_email' - 'contact_phone' - 'contact_name',
                            'sponsorships_paused', v_affected);
end
$fn$;

create or replace function public.kicklive_sponsor_package_save(p_data jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_id   uuid := nullif(p_data->>'id', '')::uuid;
  v_row  public.sponsorship_packages;
  v_new  public.sponsorship_packages;
  v_kinds text[];
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_row from public.sponsorship_packages p where p.id = v_id;
  if v_id is not null and not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'PACKAGE_UNKNOWN');
  end if;

  -- An aliased element column, because `array_agg(k)` over an unaliased function-in-FROM is
  -- `column "k" does not exist` at the first call that passes the field — the kind of mistake that installs
  -- happily (the body is not parsed until then) and surfaces as a 502 in front of a user.
  v_kinds := coalesce(
    nullif((select array_agg(v.value) from jsonb_array_elements_text(coalesce(p_data->'allowedTargetKinds', '[]'::jsonb)) as v(value)), '{}'),
    v_row.allowed_target_kinds,
    -- The column default, written again on purpose. A `save` that omitted the field and inherited the
    -- table's default through a different code path than the seed did is how a package ends up narrower or
    -- wider than the row that created it by hand; one list, cited in both places, cannot drift silently.
    array['competition', 'season', 'match', 'team', 'award', 'event']::text[]
  );
  if v_kinds is null or array_length(v_kinds, 1) is null then
    v_kinds := v_row.allowed_target_kinds;
  end if;
  if exists (select 1 from unnest(v_kinds) k(x) where not public.kicklive_sponsor_target_kind_ok(k.x)) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'allowedTargetKinds', 'reason', 'UNKNOWN_TARGET_KIND');
  end if;
  if public.kicklive_sponsor_field_refuses(p_data, array['tier', 'sortOrder', 'priceAmount']) is not null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', public.kicklive_sponsor_field_refuses(p_data, array['tier', 'sortOrder', 'priceAmount']), 'reason', 'NUMBER_REQUIRED');
  end if;
  if p_data ? 'entitlements' and not public.kicklive_sponsor_entitlements_ok(p_data->'entitlements') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'entitlements', 'reason', 'BAD_KEY_SET',
                              'detail', 'see kicklive_sponsor_entitlements_ok for the allowed keys');
  end if;

  insert into public.sponsorship_packages (
    code, label, kind, description, tier, season_label, exclusivity, entitlements, sort_order, is_active,
    price_amount, price_currency, price_basis, allowed_target_kinds
  ) values (
    lower(btrim(coalesce(p_data->>'code', v_row.code, ''))),
    btrim(coalesce(p_data->>'label', v_row.label, '')),
    lower(btrim(coalesce(p_data->>'kind', v_row.kind, coalesce(p_data->>'code', v_row.code, '')))),
    nullif(btrim(coalesce(p_data->>'description', v_row.description, '')), ''),
    greatest(1, least(9, coalesce((p_data->>'tier')::smallint, v_row.tier, 3))),
    nullif(btrim(coalesce(p_data->>'seasonLabel', v_row.season_label, '')), ''),
    coalesce(p_data->>'exclusivity', v_row.exclusivity, 'none'),
    coalesce(p_data->'entitlements', v_row.entitlements, '{}'::jsonb),
    greatest(0, least(9999, coalesce((p_data->>'sortOrder')::smallint, v_row.sort_order, 100))),
    coalesce((p_data->>'isActive')::boolean, v_row.is_active, true),
    coalesce((p_data->>'priceAmount')::numeric(12,2), v_row.price_amount),
    upper(nullif(btrim(coalesce(p_data->>'priceCurrency', v_row.price_currency, '')), '')),
    nullif(btrim(coalesce(p_data->>'priceBasis', v_row.price_basis, '')), ''),
    v_kinds
  )
  on conflict (code) do update set
    label = excluded.label,
    kind = excluded.kind,
    description = excluded.description,
    tier = excluded.tier,
    season_label = excluded.season_label,
    exclusivity = excluded.exclusivity,
    entitlements = excluded.entitlements,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active,
    price_amount = excluded.price_amount,
    price_currency = excluded.price_currency,
    price_basis = excluded.price_basis,
    allowed_target_kinds = excluded.allowed_target_kinds,
    updated_at = now()
  returning * into v_new;

  -- Whether a viewer-facing answer changed: a label or a price is not one, `is_active` and the entitlements
  -- are, and the exclusivity setting decides who else may be shown.
  perform public.kicklive_sponsorship_touch_epoch(
    v_row.id is null
    or v_new.is_active is distinct from v_row.is_active
    or v_new.entitlements is distinct from v_row.entitlements
    or v_new.exclusivity is distinct from v_row.exclusivity
    or v_new.allowed_target_kinds is distinct from v_row.allowed_target_kinds
  );
  return jsonb_build_object('ok', true, 'created', v_row.id is null, 'package', to_jsonb(v_new));
end
$fn$;

create or replace function public.kicklive_sponsorship_save(p_data jsonb)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_id        uuid := nullif(p_data->>'id', '')::uuid;
  v_row       public.sponsorships;
  v_new       public.sponsorships;
  v_sponsor   public.sponsors;
  v_package   public.sponsorship_packages;
  v_kind      text;
  v_target    text;
  v_status    text;
  v_start     date;
  v_end       date;
  v_conflict  text;
  v_held      integer;
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if p_data ? 'status' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'status', 'reason', 'STATUS_VIA_SET_STATUS_ONLY');
  end if;
  -- `is_active` is refused for the `status` reason and for the sponsor's `logoUrl` reason at once. It is a
  -- second door onto a column the status route already owns (with its transition row and its author), and a
  -- save that quietly ignored it would answer `ok: true` to a desk that had just unticked "display" — the
  -- form would look saved, the band would not change, and the reason would be sitting in a column this
  -- function never reads. The switch exists: it is `kicklive_sponsorship_set_status(p_is_active => ...)`.
  if p_data ? 'isActive' or p_data ? 'is_active' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'isActive', 'reason', 'DISPLAY_SWITCH_VIA_SET_STATUS_ONLY',
                              'detail', 'a sponsorship is shown or hidden by the status route, which records who did it');
  end if;
  select * into v_row from public.sponsorships s where s.id = v_id;
  if v_id is not null and not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'SPONSORSHIP_UNKNOWN');
  end if;

  v_kind := lower(btrim(coalesce(p_data->>'targetKind', v_row.target_kind, '')));
  v_target := btrim(coalesce(p_data->>'targetId', p_data->>'target_id', v_row.target_id, ''));
  if not public.kicklive_sponsor_target_kind_ok(v_kind) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'targetKind', 'reason', 'UNKNOWN_TARGET_KIND');
  end if;
  if not public.kicklive_sponsor_target_id_ok(v_kind, v_target) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'targetId', 'reason', 'MALFORMED_TARGET_ID',
                              'detail', 'competition, season, team and match take a numeric id; award and event take a slug');
  end if;

  select * into v_sponsor from public.sponsors s where s.id = coalesce(nullif(p_data->>'sponsorId', '')::uuid, v_row.sponsor_id);
  if v_sponsor.id is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'sponsorId', 'reason', 'SPONSOR_REQUIRED');
  end if;
  select * into v_package from public.sponsorship_packages p where p.id = coalesce(nullif(p_data->>'packageId', '')::uuid, v_row.package_id);
  if v_package.id is null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'packageId', 'reason', 'PACKAGE_REQUIRED');
  end if;
  if not v_package.is_active then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'packageId', 'reason', 'PACKAGE_INACTIVE');
  end if;
  -- Whether the package may be sold against this kind is asked *before* whether the target exists, because
  -- the first is a fact about the request and the second about the database. A form that offers "Season" for
  -- a match-only package should be told that on the first save, not after it has been made to pick a season.
  -- The existence check runs here as well as in the trigger, so the client gets a field error rather than a
  -- raised exception — the trigger is the one that also fires for anything that is not this function.
  if not exists (select 1 from unnest(v_package.allowed_target_kinds) k(x) where k.x = v_kind) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'targetKind', 'reason', 'KIND_NOT_IN_PACKAGE',
                              'detail', 'the ' || v_package.label || ' package is not sold against a ' || v_kind);
  end if;
  if v_kind <> 'award' and v_kind <> 'event' and not public.kicklive_sponsor_target_exists(v_kind, v_target) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'targetId', 'reason', 'TARGET_NOT_FOUND',
                              'detail', 'no ' || v_kind || ' with that id');
  end if;

  if public.kicklive_sponsor_field_refuses(p_data, array['priority', 'displayOrder', 'valueAmount', 'logoAssetId', 'bannerAssetId']) is not null then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', public.kicklive_sponsor_field_refuses(p_data, array['priority', 'displayOrder', 'valueAmount', 'logoAssetId', 'bannerAssetId']), 'reason', 'NUMBER_REQUIRED');
  end if;
  if p_data ? 'attribution' and not public.kicklive_sponsor_label_ok(p_data->>'attribution', 160) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'attribution', 'reason', 'LABEL_UNSAFE');
  end if;
  if p_data ? 'namingOverride' and not public.kicklive_sponsor_label_ok(p_data->>'namingOverride', 120) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'namingOverride', 'reason', 'LABEL_UNSAFE');
  end if;
  if p_data ? 'linkUrl' and not public.kicklive_sponsor_https_ok(p_data->>'linkUrl') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'linkUrl', 'reason', 'HTTPS_URL_WITH_HOST_REQUIRED');
  end if;

  -- The window, resolved once here rather than twice in the VALUES list, so the ordering rule and the stored
  -- row cannot disagree about what the dates were. The table's CHECK stays as the backstop for every writer
  -- that is not this function; the refusal below exists so that this writer answers with a field name.
  if not public.kicklive_sponsor_date_ok(nullif(p_data->>'startsAt', '')) or not public.kicklive_sponsor_date_ok(nullif(p_data->>'endsAt', '')) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED',
                              'field', case when public.kicklive_sponsor_date_ok(nullif(p_data->>'startsAt', '')) then 'endsAt' else 'startsAt' end,
                              'reason', 'DATE_REQUIRED', 'detail', 'expected a calendar date as YYYY-MM-DD');
  end if;
  begin
    v_start := coalesce(nullif(p_data->>'startsAt', '')::date, v_row.starts_at, current_date);
    v_end := coalesce(nullif(p_data->>'endsAt', '')::date, v_row.ends_at, (date_trunc('year', current_date) + interval '1 year - 1 day')::date);
  exception
    -- By SQLSTATE, not by name: PL/pgSQL has no `datetime_field_value_out_of_range` condition, and the two
    -- codes here are the ones a `::date` cast actually raises — 22007 for a value Postgres cannot parse and
    -- 22008 for one that parses and does not exist. Naming a condition that does not exist fails at
    -- *compilation*, which is what the rerun pass with bodies on is for.
    when sqlstate '22007' or sqlstate '22008' then
      return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'endsAt', 'reason', 'DATE_NOT_ON_CALENDAR',
                                'detail', 'the shape is right and the day is not: 2026-02-30 does not exist');
  end;
  if v_end < v_start then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'endsAt', 'reason', 'WINDOW_NOT_ORDERED',
                              'detail', 'a sponsorship that ends before it starts is a date typed into the wrong box');
  end if;

  -- Exclusivity, and the reason it is a query rather than a constraint: "no other *approved sponsor in the
  -- same category* may hold an active title slot on this target" reaches three tables and the calendar. As a
  -- CHECK it would be impossible; as a trigger alone it would be a 500. Here it is a refusal with a name.
  if v_package.exclusivity in ('exclusive', 'package') then
    select pk.label
      into v_conflict
      from public.sponsorships s
      join public.sponsorship_packages pk on pk.id = s.package_id
      join public.sponsors sp on sp.id = s.sponsor_id
     where s.target_kind = v_kind and s.target_id = v_target
       and s.status in ('scheduled', 'active') and s.is_active
       and s.id is distinct from v_id
       and (v_package.exclusivity = 'exclusive'
            or sp.id <> v_sponsor.id)  -- `package`: another sponsor, same package
       and (v_package.exclusivity = 'package' or pk.exclusivity in ('exclusive', 'package'))
     limit 1;
    if v_conflict is not null then
      return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'targetId', 'reason', 'EXCLUSIVITY_TAKEN',
                                'detail', 'this ' || v_kind || ' already carries a ' || v_conflict || ' sponsorship');
    end if;
  end if;
  -- `max_per_target` from the package's entitlements, honoured here rather than in the renderer, because a
  -- limit that only the display respects is a limit that the data will happily exceed.
  if v_package.entitlements ? 'max_per_target' then
    select count(1) into v_held
      from public.sponsorships s
     where s.target_kind = v_kind and s.target_id = v_target
       and s.package_id = v_package.id
       and s.status in ('scheduled', 'active')
       and s.id is distinct from v_id;
    if v_held > coalesce((v_package.entitlements->>'max_per_target')::int, 99) then
      return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'packageId', 'reason', 'PACKAGE_LIMIT_FOR_TARGET',
                                'detail', v_package.label || ' allows ' || (v_package.entitlements->>'max_per_target') ||
                                            ' per ' || v_kind || ' and this one has ' || v_held::text);
    end if;
  end if;

  -- The unique index (`…no_duplicate_key`) is the thing that actually prevents a re-typed renewal, and an
  -- exception from it would reach the API as an untranslatable 23505. Same wrapper Phase 7 uses for a
  -- duplicate creative title: catch it at the write, name the field, and let the envelope stay the contract.
  begin
  insert into public.sponsorships (
    id, sponsor_id, package_id, target_kind, target_id, starts_at, ends_at, attribution, naming_override,
    logo_asset_id, banner_asset_id, logo_variant, background_colour, link_url, priority, display_order,
    value_amount, value_currency, value_basis, invoice_reference, renewal_terms, internal_notes,
    advertisement_campaign_id, status, is_active, created_by
  ) values (
    coalesce(v_id, gen_random_uuid()),
    v_sponsor.id, v_package.id, v_kind, v_target,
    v_start,
    v_end,
    nullif(btrim(coalesce(p_data->>'attribution', v_row.attribution, '')), ''),
    nullif(btrim(coalesce(p_data->>'namingOverride', v_row.naming_override, '')), ''),
    coalesce(nullif(p_data->>'logoAssetId', '')::bigint, v_row.logo_asset_id),
    coalesce(nullif(p_data->>'bannerAssetId', '')::bigint, v_row.banner_asset_id),
    nullif(btrim(coalesce(p_data->>'logoVariant', v_row.logo_variant, '')), ''),
    nullif(btrim(coalesce(p_data->>'backgroundColour', v_row.background_colour, '')), ''),
    nullif(btrim(coalesce(p_data->>'linkUrl', v_row.link_url, '')), ''),
    greatest(0, least(9999, coalesce((p_data->>'priority')::smallint,
                                     (v_package.entitlements->>'priority_default')::smallint,
                                     v_row.priority, v_sponsor.default_priority, 100))),
    greatest(0, least(999999, coalesce((p_data->>'displayOrder')::integer, v_row.display_order, 0))),
    coalesce((p_data->>'valueAmount')::numeric(12,2), v_row.value_amount),
    upper(nullif(btrim(coalesce(p_data->>'valueCurrency', v_row.value_currency, '')), '')),
    nullif(btrim(coalesce(p_data->>'valueBasis', v_row.value_basis, '')), ''),
    nullif(btrim(coalesce(p_data->>'invoiceReference', v_row.invoice_reference, '')), ''),
    nullif(btrim(coalesce(p_data->>'renewalTerms', v_row.renewal_terms, '')), ''),
    nullif(btrim(coalesce(p_data->>'internalNotes', v_row.internal_notes, '')), ''),
    coalesce(nullif(p_data->>'advertisementCampaignId', '')::uuid, v_row.advertisement_campaign_id),
    coalesce(v_row.status, 'draft'),
    coalesce(v_row.is_active, false),
    auth.uid()
  )
  on conflict (id) do update set
    sponsor_id = excluded.sponsor_id,
    package_id = excluded.package_id,
    target_kind = excluded.target_kind,
    target_id = excluded.target_id,
    starts_at = excluded.starts_at,
    ends_at = excluded.ends_at,
    attribution = excluded.attribution,
    naming_override = excluded.naming_override,
    logo_asset_id = excluded.logo_asset_id,
    banner_asset_id = excluded.banner_asset_id,
    logo_variant = excluded.logo_variant,
    background_colour = excluded.background_colour,
    link_url = excluded.link_url,
    priority = excluded.priority,
    display_order = excluded.display_order,
    value_amount = excluded.value_amount,
    value_currency = excluded.value_currency,
    value_basis = excluded.value_basis,
    invoice_reference = excluded.invoice_reference,
    renewal_terms = excluded.renewal_terms,
    internal_notes = excluded.internal_notes,
    advertisement_campaign_id = excluded.advertisement_campaign_id,
    activation_error = null,
    updated_at = now()
  returning * into v_new;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'startsAt', 'reason', 'DUPLICATE_ASSIGNMENT_IN_WINDOW',
                              'detail', 'this sponsor already holds this package against this target on that start date; renew by extending the existing record');
  end;

  -- Editing the copy or the dates of a sponsorship a viewer can currently see must re-render the page, but
  -- editing only the internal notes must not: an epoch bump is cheap, and doing it anyway would mean the
  -- edge cache is cold for every desk keystroke.
  perform public.kicklive_sponsorship_touch_epoch(
    v_row.id is null
    or v_new.priority is distinct from v_row.priority
    or v_new.display_order is distinct from v_row.display_order
    or v_new.starts_at is distinct from v_row.starts_at
    or v_new.ends_at is distinct from v_row.ends_at
    or v_new.attribution is distinct from v_row.attribution
    or v_new.naming_override is distinct from v_row.naming_override
    or v_new.logo_asset_id is distinct from v_row.logo_asset_id
    or v_new.banner_asset_id is distinct from v_row.banner_asset_id
    or v_new.link_url is distinct from v_row.link_url
  );

  return jsonb_build_object('ok', true, 'created', v_row.id is null, 'sponsorship', to_jsonb(v_new) - 'internal_notes');
end
$fn$;

create or replace function public.kicklive_sponsorship_set_status(p_id uuid, p_status text, p_reason text default null, p_is_active boolean default null)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_row public.sponsorships;
  v_sponsor public.sponsors;
  v_package public.sponsorship_packages;
  v_allowed boolean;
  v_missing text[] := '{}';
begin
  if not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  select * into v_row from public.sponsorships s where s.id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'SPONSORSHIP_UNKNOWN');
  end if;
  select exists (
    select 1 from public.sponsorship_status_transitions t
     where t.kind = 'sponsorship' and t.from_status = v_row.status and t.to_status = p_status
  ) into v_allowed;
  if not v_allowed then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'field', 'status', 'reason', 'TRANSITION_NOT_ALLOWED',
                              'detail', v_row.status || ' -> ' || coalesce(p_status, 'null'),
                              'allowed', coalesce(to_jsonb((select array_agg(t.to_status) from public.sponsorship_status_transitions t
                                                              where t.kind = 'sponsorship' and t.from_status = v_row.status)), '[]'::jsonb));
  end if;

  -- The preconditions, gathered rather than short-circuited, so one round trip tells an operator everything
  -- they have to fix. A sponsorship that displays a brand the office has not approved is the failure this
  -- whole phase has to make impossible.
  if p_status = 'active' then
    select * into v_sponsor from public.sponsors s where s.id = v_row.sponsor_id;
    if v_sponsor.status <> 'approved' then
      select array_append(v_missing, 'sponsor:' || coalesce(v_sponsor.status, 'unknown')) into v_missing;
    end if;
    select * into v_package from public.sponsorship_packages p where p.id = v_row.package_id;
    if not v_package.is_active then
      select array_append(v_missing, 'package_inactive') into v_missing;
    end if;
    if v_row.ends_at < current_date then
      select array_append(v_missing, 'window_in_the_past') into v_missing;
    end if;
    if v_row.sponsor_id is null then
      select array_append(v_missing, 'sponsor_missing') into v_missing;
    end if;
    if array_length(v_missing, 1) is not null then
      update public.sponsorships s
         set activation_error = array_to_string(v_missing, ', '), updated_at = now()
       where s.id = p_id;
      return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'NOT_READY_TO_DISPLAY', 'missing', to_jsonb(v_missing),
                                'detail', 'a sponsorship displays a brand, so the brand has to be approved, the package live, and the window not over');
    end if;
  end if;

  update public.sponsorships s
     set status = p_status,
         -- `is_active` is the display switch and it follows the status by default: `active` shows, anything
         -- else does not, and an operator who wants the reverse (a live contract, hidden today) says so with
         -- the explicit parameter rather than by learning the trick.
         is_active = coalesce(p_is_active, p_status = 'active'),
         activated_by = case when p_status = 'active' then auth.uid() else s.activated_by end,
         activated_at = case when p_status = 'active' then now() else s.activated_at end,
         activation_error = null,
         internal_notes = case when p_reason is not null
                              then btrim(coalesce(s.internal_notes || E'\n', '') || p_status || ': ' || p_reason)
                              else s.internal_notes end,
         updated_at = now()
   where s.id = p_id
   returning * into v_row;

  perform public.kicklive_sponsorship_touch_epoch(true);
  return jsonb_build_object('ok', true, 'sponsorship', to_jsonb(v_row) - 'internal_notes', 'isActive', v_row.is_active);
end
$fn$;

-- ----------------------------------------------------------------------------
-- 9 · media (step 6): reserve and attach, on Phase 6's vocabulary
-- ----------------------------------------------------------------------------

create or replace function public.kicklive_sponsor_reserve_asset(
  p_sponsor_id uuid,
  p_slot       text,
  p_content_type text,
  p_byte_size  bigint,
  p_sha256     text,
  p_width      integer default null,
  p_height     integer default null,
  p_alt_text   text default null
)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_sponsor public.sponsors;
  v_existing public.media_assets;
  v_ver      integer;
  v_key      text;
  v_ext      text;
  v_max      bigint;
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if p_slot not in ('logo', 'banner') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'slot', 'reason', 'SLOT_UNKNOWN',
                              'allowed', jsonb_build_array('logo', 'banner'));
  end if;
  select * into v_sponsor from public.sponsors s where s.id = p_sponsor_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'SPONSOR_UNKNOWN');
  end if;
  -- An image only, and only what Phase 6 accepts: `svg` is refused here as it is there, because a logo is
  -- the one asset a partner is handed an <img> tag for.
  if p_content_type not in ('image/png', 'image/jpeg', 'image/webp', 'image/gif') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'file', 'reason', 'UNSUPPORTED_TYPE');
  end if;
  v_max := case p_slot when 'banner' then 10485760::bigint else 5242880::bigint end;
  if p_byte_size is null or p_byte_size < 1 or p_byte_size > v_max then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'file', 'reason', 'TOO_LARGE',
                              'maxBytes', v_max);
  end if;
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'sha256', 'reason', 'DIGEST_REQUIRED');
  end if;

  v_ext := case p_content_type when 'image/png' then 'png' when 'image/jpeg' then 'jpg'
                               when 'image/webp' then 'webp' else 'gif' end;
  -- Same-bytes-same-slot is not a new version: re-uploading the file that is already current returns it,
  -- because a logo re-saved by a nervous operator must not become "v3" and a cache miss on every page.
  select * into v_existing
    from public.media_assets a
   where a.entity_kind = 'sponsors' and a.entity_id = p_sponsor_id::text
     -- `uploading` included, deliberately. A client that retries the same file while the first attempt is
     -- still in flight gets the same row and the same key; restricting this to `ready` would hand the retry a
     -- second key and leave the first object in the bucket with no row pointing at it — the definition of an
     -- orphan, and one nothing but a manual audit would ever find. `failed` is excluded so a genuine re-do
     -- still gets a fresh version. Whether the caller may then *skip* the write is answered separately below,
     -- because the two questions are not the same question.
     and a.variant = p_slot and a.sha256 = p_sha256 and a.status in ('ready', 'uploading')
   order by a.version desc limit 1;
  if found then
    -- Two answers rather than one, and the difference is the whole safety argument. A `ready` row's bytes are
    -- already in the bucket, so the caller may skip the upload: `existing`. An `uploading` row is a reservation
    -- somebody is still writing — reusing its id and key is what stops the retry from orphaning an object, but
    -- skipping *that* upload would publish a URL to bytes that may never arrive, which is the one thing
    -- Phase 6's order-of-operations exists to prevent. So the flag reports what may be skipped, and `reused`
    -- says the key is not new either way.
    return jsonb_build_object('ok', true,
                              'existing', (v_existing.status = 'ready'),
                              'reused', true,
                              'assetId', v_existing.id,
                              'objectKey', v_existing.object_key,
                              'url', '/api/media/assets/' || v_existing.object_key,
                              'version', v_existing.version,
                              'slot', p_slot,
                              'bucket', v_existing.bucket);
  end if;

  select coalesce(max(a.version), 0) + 1 into v_ver
    from public.media_assets a
   where a.entity_kind = 'sponsors' and a.entity_id = p_sponsor_id::text and a.variant = p_slot;
  -- Phase 6's key grammar, with the slot in the variant position: `sponsors/<uuid>/logo/v2-1a2b3c4d.png`.
  v_key := 'sponsors/' || p_sponsor_id::text || '/' || p_slot || '/v' || v_ver::text || '-' || left(p_sha256, 8) || '.' || v_ext;

  insert into public.media_assets (
    entity_kind, entity_id, bucket, object_key, variant, version, content_type, byte_size, sha256,
    width, height, alt_text, visibility, status, created_by
  ) values (
    'sponsors', p_sponsor_id::text, 'media', v_key, p_slot, v_ver, p_content_type, p_byte_size, p_sha256,
    p_width, p_height, nullif(btrim(coalesce(p_alt_text, '')), ''), 'public', 'uploading', auth.uid()
  )
  returning id into v_existing.id;

  return jsonb_build_object('ok', true, 'existing', false, 'assetId', v_existing.id, 'objectKey', v_key,
                            'version', v_ver, 'url', '/api/media/assets/' || v_key,
                            'bucket', 'media', 'slot', p_slot);
end
$fn$;

-- Attaching is a separate call because it is the moment the bytes are known to exist: the Worker writes to
-- R2, verifies with a head, and only then does this move the entity's URL. A failure in between leaves the
-- asset `failed` and the sponsor row showing what it showed before — never a URL to nothing.
create or replace function public.kicklive_sponsor_attach_asset(p_sponsor_id uuid, p_asset_id bigint, p_slot text)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_asset   public.media_assets;
  v_url     text;
  v_sponsor jsonb;
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if p_slot not in ('logo', 'banner') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'slot', 'reason', 'SLOT_UNKNOWN');
  end if;
  select * into v_asset from public.media_assets a where a.id = p_asset_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'NOT_FOUND', 'reason', 'ASSET_UNKNOWN');
  end if;
  if v_asset.entity_kind <> 'sponsors' or v_asset.entity_id <> p_sponsor_id::text or v_asset.variant <> p_slot then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ASSET_FOR_OTHER_ENTITY',
                              'detail', 'an asset may only be attached to the sponsor and slot it was reserved for');
  end if;
  if v_asset.status not in ('ready', 'uploading') then
    return jsonb_build_object('ok', false, 'code', 'CONFLICT', 'reason', 'ASSET_NOT_READY', 'detail', v_asset.status);
  end if;
  v_url := '/api/media/assets/' || v_asset.object_key;

  update public.sponsors s
     set logo_asset_id   = case when p_slot = 'logo'   then p_asset_id else s.logo_asset_id end,
         logo_url        = case when p_slot = 'logo'   then v_url      else s.logo_url end,
         banner_asset_id = case when p_slot = 'banner' then p_asset_id else s.banner_asset_id end,
         banner_url      = case when p_slot = 'banner' then v_url      else s.banner_url end,
         updated_at      = now()
   where s.id = p_sponsor_id;

  -- The previous occupant of the slot becomes `superseded`, so it stays readable for the immutable cache
  -- entries already pointing at it and disappears from history lists as "current". Phase 6's rule, reused.
  update public.media_assets a
     set status = 'superseded', superseded_at = now(), updated_at = now()
   where a.entity_kind = 'sponsors' and a.entity_id = p_sponsor_id::text and a.variant = p_slot
     and a.id <> p_asset_id and a.status = 'ready';
  update public.media_assets a set status = 'ready', ready_at = coalesce(a.ready_at, now()), updated_at = now()
   where a.id = p_asset_id and a.status = 'uploading';

  -- A sponsor's logo appears on live pages, so this is a viewer-visible change.
  perform public.kicklive_sponsorship_touch_epoch(true);
  -- `return jsonb_build_object(…) from public.sponsors` is not a thing a plpgsql function can say: RETURN
  -- takes an expression and no FROM. The row is selected first, and the private columns are removed from
  -- the copy that goes back to the caller.
  select to_jsonb(s) - 'contact_email' - 'contact_phone' - 'contact_name' - 'internal_notes' into v_sponsor
    from public.sponsors s where s.id = p_sponsor_id;
  return jsonb_build_object('ok', true, 'sponsor', v_sponsor, 'assetId', p_asset_id, 'url', v_url);
end
$fn$;

-- ----------------------------------------------------------------------------
-- 10 · the clock, the diagnostics, the admin list
-- ----------------------------------------------------------------------------

create or replace function public.kicklive_sponsorship_expire_due(p_limit integer default 500)
returns jsonb
language plpgsql volatile
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_ids      uuid[];
  v_count    integer := 0;
  v_activated integer := 0;
begin
  if auth.uid() is not null and not public.is_admin() then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  -- `for update` is legal only on the outer statement, so the rows are locked by id list rather than inside
  -- the CTE — and the list is bounded before anything is touched, because this runs from a cron alongside
  -- the media sweep and must not become the reason a deploy cannot be cancelled.
  select array_agg(x.id) into v_ids
    from (
      select s.id from public.sponsorships s
       where s.status = 'active' and s.ends_at < current_date
       order by s.ends_at, s.id
       limit greatest(1, least(coalesce(p_limit, 500), 2000))
    ) x;
  if v_ids is null then
    return jsonb_build_object('ok', true, 'ended', 0, 'scheduled_activated', 0, 'epoch', public.kicklive_sponsorship_epoch());
  end if;
  update public.sponsorships s
     set status = 'ended', is_active = false, updated_at = now()
   where s.id = any (v_ids) and s.status = 'active' and s.ends_at < current_date;
  get diagnostics v_count = row_count;

  -- A scheduled sponsorship whose window has begun is activated here, and only if it is already ready — the
  -- preconditions are the same function the human path runs, so "the clock did it" and "an operator did it"
  -- cannot disagree about what may be shown.
  with candidates as (
    select sn.id
      from public.sponsorships sn
      join public.sponsors sp on sp.id = sn.sponsor_id and sp.status = 'approved'
      join public.sponsorship_packages pk on pk.id = sn.package_id and pk.is_active
     where sn.status = 'scheduled' and sn.starts_at <= current_date and sn.ends_at >= current_date
     order by sn.starts_at, sn.id
     limit greatest(1, least(coalesce(p_limit, 500), 2000))
  )
  update public.sponsorships s
     set status = 'active', is_active = true, activated_at = now(), activation_error = null, updated_at = now()
    from candidates c
   where s.id = c.id
     and not exists (select 1 from public.sponsors x where x.id = s.sponsor_id and x.status <> 'approved');
  get diagnostics v_activated = row_count;

  if v_count > 0 or v_activated > 0 then
    perform public.kicklive_sponsorship_touch_epoch(true);
  end if;
  return jsonb_build_object('ok', true, 'ended', v_count, 'scheduled_activated', v_activated,
                            'epoch', public.kicklive_sponsorship_epoch(),
                            'note', 'the serving query filters the window too; this pass keeps the statuses honest');
end
$fn$;

create or replace function public.kicklive_sponsorship_diagnostics()
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  -- Counts of states that must not exist, and nothing else: no sponsor names, no contacts, no amounts. The
  -- response is meant to be pasteable into a support channel.
  return jsonb_build_object(
    'ok', true,
    'epoch', public.kicklive_sponsorship_epoch(),
    'active_but_expired',     (select count(1) from public.sponsorships s where s.status = 'active' and s.ends_at < current_date),
    'active_unapproved',      (select count(1) from public.sponsorships s join public.sponsors sp on sp.id = s.sponsor_id
                                where s.status = 'active' and sp.status <> 'approved'),
    'active_inactive_flag',   (select count(1) from public.sponsorships s where s.status = 'active' and not s.is_active),
    'displayed_not_active',   (select count(1) from public.sponsorships s where s.is_active and s.status <> 'active'),
    'active_dead_package',    (select count(1) from public.sponsorships s join public.sponsorship_packages pk on pk.id = s.package_id
                                where s.status = 'active' and not pk.is_active),
    'window_reversed',        (select count(1) from public.sponsorships s where s.ends_at < s.starts_at),
    'target_kind_mismatch',   (select count(1) from public.sponsorships s join public.sponsorship_packages pk on pk.id = s.package_id
                                where not (s.target_kind = any (pk.allowed_target_kinds))),
    'sponsor_without_logo',   (select count(1) from public.sponsors s where s.status = 'approved' and s.logo_url is null),
    'orphan_logo_assets',     (select count(1) from public.media_assets ma where ma.entity_kind = 'sponsors' and ma.status in ('ready','superseded')
                                and not exists (select 1 from public.sponsors s where s.id::text = ma.entity_id
                                                 and (s.logo_asset_id = ma.id or s.banner_asset_id = ma.id))),
    'double_title',           (select count(1) from (
                                 select s.target_kind, s.target_id from public.sponsorships s
                                   join public.sponsorship_packages pk on pk.id = s.package_id
                                  where s.status = 'active' and s.is_active and pk.exclusivity = 'exclusive'
                                  group by 1, 2 having count(1) > 1) d),
    'counts', jsonb_build_object(
      'sponsors',          (select count(1) from public.sponsors),
      'sponsors_approved', (select count(1) from public.sponsors where status = 'approved'),
      'packages',          (select count(1) from public.sponsorship_packages),
      'packages_active',   (select count(1) from public.sponsorship_packages where is_active),
      'sponsorships',      (select count(1) from public.sponsorships),
      'sponsorships_live', (select count(1) from public.sponsorships where status = 'active' and is_active)
    ),
    'definitions', jsonb_build_object(
      'ordering', 'priority asc, display_order asc, starts_at desc — no randomness, no bidding',
      'visibility', 'status = active AND is_active AND current_date between starts_at and ends_at AND sponsor approved AND package active'
    )
  );
end
$fn$;

create or replace function public.kicklive_sponsorship_admin_list(
  p_resource       text,
  p_q              text default null,
  p_status         text default null,
  p_target_kind    text default null,
  p_target_id      text default null,
  p_sponsor_id     uuid default null,
  p_include_expired boolean default false,
  p_limit          integer default 50,
  p_offset         integer default 0
)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_rows jsonb;
  v_total integer;
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if p_resource not in ('sponsors', 'packages', 'sponsorships') then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'resource', 'reason', 'UNKNOWN_RESOURCE',
                              'allowed', jsonb_build_array('sponsors', 'packages', 'sponsorships'));
  end if;

  if p_resource = 'sponsors' then
    -- The admin view of a sponsor *does* carry the contact fields, because the person reading it is the
    -- person who has to telephone them. `select` privilege on the table is not part of that; the identity
    -- check above is.
    select count(1) into v_total from public.sponsors s
     where (p_q is null or s.display_name ilike '%' || p_q || '%' or s.legal_name ilike '%' || p_q || '%' or s.slug ilike '%' || p_q || '%')
       and (p_status is null or s.status = p_status);
    select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.default_priority, x.display_name), '[]'::jsonb) into v_rows
      from (
        select s.id, s.slug, s.display_name, s.legal_name, s.description, s.website_url, s.status,
               s.contact_name, s.contact_email, s.contact_phone, s.contact_consent_at,
               s.logo_url, s.banner_url, s.logo_asset_id, s.banner_asset_id, s.brand_colour, s.on_dark,
               s.default_priority, s.value_amount, s.value_currency, s.value_basis, s.invoice_reference,
               s.renewal_terms, s.internal_notes, s.approved_at, s.created_at, s.updated_at,
               (select count(1) from public.sponsorships sn where sn.sponsor_id = s.id) as sponsorship_count,
               (select count(1) from public.sponsorships sn where sn.sponsor_id = s.id and sn.status = 'active' and sn.is_active) as live_count
          from public.sponsors s
         where (p_q is null or s.display_name ilike '%' || p_q || '%' or s.legal_name ilike '%' || p_q || '%' or s.slug ilike '%' || p_q || '%')
           and (p_status is null or s.status = p_status)
         order by s.default_priority, s.display_name
         limit greatest(1, least(coalesce(p_limit, 50), 200)) offset greatest(0, coalesce(p_offset, 0))
      ) x;
    return jsonb_build_object('ok', true, 'sponsors', v_rows, 'total', v_total, 'limit', least(coalesce(p_limit, 50), 200), 'offset', p_offset);
  end if;

  if p_resource = 'packages' then
    select count(1) into v_total from public.sponsorship_packages;
    select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.sort_order, x.tier), '[]'::jsonb) into v_rows
      from (
        select p.id, p.code, p.label, p.kind, p.description, p.tier, p.season_label, p.exclusivity,
               p.entitlements, p.sort_order, p.is_active, p.price_amount, p.price_currency, p.price_basis,
               to_jsonb(p.allowed_target_kinds) as allowed_target_kinds,
               (select count(1) from public.sponsorships s where s.package_id = p.id) as usage_count,
               (select count(1) from public.sponsorships s where s.package_id = p.id and s.status = 'active' and s.is_active) as live_count
          from public.sponsorship_packages p
         where (p_q is null or p.label ilike '%' || p_q || '%' or p.code ilike '%' || p_q || '%')
           and (p_status is null or (p.is_active and p_status = 'active') or (not p.is_active and p_status = 'inactive'))
         order by p.sort_order, p.tier
      ) x;
    return jsonb_build_object('ok', true, 'packages', v_rows, 'total', v_total);
  end if;

  select count(1) into v_total from public.sponsorships s
   where (p_sponsor_id is null or s.sponsor_id = p_sponsor_id)
     and (p_target_kind is null or s.target_kind = p_target_kind)
     and (p_target_id is null or s.target_id = p_target_id)
     and (p_status is null or s.status = p_status)
     and (p_include_expired or s.ends_at >= current_date);
  select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.target_kind, x.priority, x.display_order, x.ends_at desc), '[]'::jsonb) into v_rows
    from (
      select s.id, s.sponsor_id, s.package_id, s.target_kind, s.target_id, s.starts_at, s.ends_at, s.status,
             s.is_active, s.priority, s.display_order, s.attribution, s.naming_override, s.logo_asset_id,
             s.banner_asset_id, s.logo_variant, s.background_colour, s.link_url, s.activation_error,
             s.value_amount, s.value_currency, s.value_basis, s.invoice_reference, s.renewal_terms,
             s.advertisement_campaign_id, s.activated_at, s.created_at, s.updated_at,
             sp.slug as sponsor_slug, sp.display_name as sponsor_name, sp.status as sponsor_status,
             p.code as package_code, p.label as package_label, p.tier as package_tier,
             (current_date between s.starts_at and s.ends_at) as window_open
        from public.sponsorships s
        join public.sponsors sp on sp.id = s.sponsor_id
        join public.sponsorship_packages p on p.id = s.package_id
       where (p_sponsor_id is null or s.sponsor_id = p_sponsor_id)
         and (p_target_kind is null or s.target_kind = p_target_kind)
         and (p_target_id is null or s.target_id = p_target_id)
         and (p_status is null or s.status = p_status)
         and (p_include_expired or s.ends_at >= current_date)
       order by s.target_kind, s.priority, s.display_order, s.ends_at desc
       limit greatest(1, least(coalesce(p_limit, 50), 200)) offset greatest(0, coalesce(p_offset, 0))
    ) x;
  return jsonb_build_object('ok', true, 'sponsorships', v_rows, 'total', v_total, 'epoch', public.kicklive_sponsorship_epoch());
end
$fn$;

-- Why is this page showing what it shows? The same code path the viewer gets, plus the reasons. Phase 7's
-- `kicklive_ad_explain` lesson applies: a preview that agrees with the *form* is a lie, and one that agrees
-- with production is a feature.
create or replace function public.kicklive_sponsorship_explain(p_target_kind text, p_target_id text)
returns jsonb
language plpgsql stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_rows jsonb;
begin
  if not (public.is_admin() or public.is_admin_or_media()) then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN', 'reason', 'ADMIN_ONLY');
  end if;
  if not public.kicklive_sponsor_target_kind_ok(p_target_kind) then
    return jsonb_build_object('ok', false, 'code', 'VALIDATION_FAILED', 'field', 'kind', 'reason', 'UNKNOWN_TARGET_KIND');
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'sponsorshipId', s.id,
    'sponsor', sp.display_name,
    'package', pk.label,
    'wouldServe', s.status = 'active' and s.is_active
                   and current_date between s.starts_at and s.ends_at
                   and sp.status = 'approved' and pk.is_active,
    'blockers', (
      select nullif(array_to_string(array_remove(array[
        case when s.status <> 'active'      then 'status:' || s.status end,
        case when not s.is_active          then 'display_switch_off' end,
        case when s.ends_at < current_date  then 'window_ended' end,
        case when s.starts_at > current_date then 'window_not_started' end,
        case when sp.status <> 'approved'  then 'sponsor:' || sp.status end,
        case when not pk.is_active         then 'package_inactive' end,
        case when s.activation_error is not null then 'activation:' || s.activation_error end
      ], null), ', '), '')
    ),
    'priority', s.priority,
    'displayOrder', s.display_order
  ) order by s.priority, s.display_order), '[]'::jsonb) into v_rows
    from public.sponsorships s
    join public.sponsors sp on sp.id = s.sponsor_id
    join public.sponsorship_packages pk on pk.id = s.package_id
   where s.target_kind = p_target_kind and s.target_id = p_target_id
     and s.status <> 'archived';
  return jsonb_build_object('ok', true, 'target', p_target_kind || ':' || p_target_id, 'rows', coalesce(v_rows, '[]'::jsonb),
                            'serving', public.kicklive_sponsorship_for(p_target_kind, array[p_target_id]));
end
$fn$;

create or replace function public.kicklive_sponsorship_status_transitions(p_kind text default 'sponsorship')
returns jsonb
language sql stable
security definer
set search_path = public, pg_temp
as $fn$
  select jsonb_build_object(
    'ok', true,
    'kind', p_kind,
    'transitions', coalesce((
      select jsonb_agg(jsonb_build_object('from', t.from_status, 'to', t.to_status, 'note', t.note)
                       order by t.from_status, t.to_status)
        from public.sponsorship_status_transitions t
       where t.kind = p_kind
    ), '[]'::jsonb),
    'statuses', case p_kind
      when 'sponsor' then to_jsonb(array['draft','pending','approved','suspended','archived'])
      else to_jsonb(array['draft','scheduled','active','paused','ended','archived'])
    end
  )
$fn$;

-- ----------------------------------------------------------------------------
-- 11 · row-level security and grants
-- ----------------------------------------------------------------------------

do $rls$
declare
  t text;
begin
  foreach t in array array['sponsors', 'sponsorship_packages', 'sponsorships', 'sponsorship_status_transitions', 'sponsorship_config']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
  end loop;
end
$rls$;

-- No policies, on purpose, and for the Phase 7 reason: a read grant under RLS with no policy is a door that
-- answers zero rows, which reads like a bug in the app. Every access is through the functions above, which
-- check who is calling.
--
-- `service_role` gets the write privileges the definer functions need. That is not decoration and it is not
-- "the owner will be superuser": a `SECURITY DEFINER` function runs as its owner, and on a hosted Supabase
-- project that owner is a role with table privileges rather than a bypass, so a migration that forgets these
-- grants installs cleanly and then fails the first time anybody saves a sponsor. Delete is deliberately
-- absent on the two tables that hold agreements — archiving is this system's delete, and it is what lets a
-- report answer "who sponsored what in March" a year later.
grant select, insert, update           on table public.sponsors                       to service_role;
grant select, insert, update           on table public.sponsorship_packages           to service_role;
grant select, insert, update, delete   on table public.sponsorships                   to service_role;
grant select                           on table public.sponsorship_status_transitions  to service_role;
grant select, update                   on table public.sponsorship_config             to service_role;
-- No sequences to grant here: every id in this migration is a uuid with `gen_random_uuid()`, and the one
-- bigint in play (`media_assets.id`) belongs to Phase 6, which already granted it.

-- Explicit grants, per function, in a loop over the catalogue rather than written out by hand: the Phase 7
-- lesson is that a `like` pattern misses the function whose name does not fit it, and that shows up at
-- runtime as a 401 no type checker can see. So the loop carries an explicit `in` list for the names the
-- pattern cannot reach, and the verify block below asserts the same set independently.
do $grant$
declare
  f record;
begin
  for f in
    select p.oid::regprocedure::text as sig, p.proname
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and (p.proname like 'kicklive_sponsor%' or p.proname like 'kicklive_sponsorship%')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    execute format('grant execute on function %s to service_role', f.sig);
    -- The public surface: three functions a stranger may call, each with its own fixed projection.
    if f.proname in ('kicklive_sponsorship_for', 'kicklive_sponsorship_epoch', 'kicklive_sponsor_package_card') then
      execute format('grant execute on function %s to anon, authenticated', f.sig);
    elsif f.proname <> 'kicklive_sponsorship_touch_epoch' then
      -- The staff surface, granted to `authenticated` and to nobody else. This is the part that is easy to
      -- get wrong in the comfortable direction: these functions all decide the caller's role from the JWT
      -- (`is_admin()` reads `profiles where id = auth.uid()`), and a call made on the **service-role key has
      -- no subject at all** — PostgREST sends only `authorization: Bearer <service key>`, so `auth.uid()` is
      -- NULL, `is_admin()` is false, and every admin write answers ADMIN_ONLY forever. Granting these to
      -- `authenticated` is what lets the Worker call them *as the signed-in admin*, which is the only way the
      -- database's own check can mean anything. It is not a widening: an anonymous caller still has no
      -- execute, a signed-in fan still trips `is_admin()`, the Worker's capability matrix still refuses before
      -- a request is built, and no client role holds a privilege on a table (asserted below).
      execute format('grant execute on function %s to authenticated', f.sig);
    end if;
    -- `touch_epoch` matches the LIKE but must not be grantable to anyone who can name a function: it writes the
    -- cache version, and its only caller is another definer function in this file. It is excluded above rather
    -- than revoked afterwards, so that the list of exceptions and the list of grants stay one edit apart.
    --
    -- `kicklive_asset_url_for_asset` is deliberately NOT mentioned here, and that is a correction, not an
    -- omission: this loop reaches a function only through `like 'kicklive_sponsor%'`, and that name does not
    -- match it. An earlier draft of this comment claimed the loop left it service-role-only; the loop never
    -- saw it at all, so it kept Phase 6's default `execute(public)` grant — a definer function that turns an
    -- asset id into a stored object key, callable by any stranger. The verification block below now checks
    -- that by name, and the grant is set by name next to it. Matching the pattern is not the same as being
    -- covered.
    null;
  end loop;
end
$grant$;

-- Named, not pattern-matched, for the reason just written down: Phase 6 granted this helper to PUBLIC and the
-- loop above cannot reach it. It answers only for `visibility = 'public'` assets, and it exists so that the
-- band's projection can prefer a freshly uploaded object over the column that was copied from — a caller with
-- the table privilege does not need it, and a caller without one must not be able to use it as an oracle.
revoke all on function public.kicklive_asset_url_for_asset(bigint) from public, anon, authenticated;
grant execute on function public.kicklive_asset_url_for_asset(bigint) to service_role;

-- The three primitives this file calls that other phases own: they must be executable by the definer
-- functions here, and `security definer` does not change what the *function's own* role may execute.
grant execute on function public.is_admin() to service_role;
grant execute on function public.is_admin_or_media() to service_role;
grant execute on function public.touch_updated_at() to service_role;

-- ----------------------------------------------------------------------------
-- 12 · media plane: admit the `sponsors` kind Phase 6 reserved
-- ----------------------------------------------------------------------------

alter table public.media_assets drop constraint if exists media_assets_kind_check;
alter table public.media_assets add constraint media_assets_kind_check check (
  entity_kind in ('teams','players','competitions','seasons','news','team_news','matches','users','advertisements','sponsors')
);

-- ----------------------------------------------------------------------------
-- 13 · verification
-- ----------------------------------------------------------------------------

do $verify$
declare
  n integer;
  k text;
  expected text[] := array[
    'kicklive_sponsor_https_ok',
    'kicklive_sponsor_target_kind_ok',
    'kicklive_sponsor_target_id_ok',
    'kicklive_sponsor_label_ok',
    'kicklive_sponsor_entitlements_ok',
    'kicklive_sponsor_target_exists',
    'kicklive_sponsor_guard_target',
    'kicklive_sponsor_guard_slug',
    'kicklive_sponsor_guard_package_code',
    'kicklive_sponsorship_epoch',
    'kicklive_sponsorship_for',
    'kicklive_sponsor_package_card',
    'kicklive_sponsorship_touch_epoch',
    'kicklive_sponsor_save',
    'kicklive_sponsor_set_status',
    'kicklive_sponsor_package_save',
    'kicklive_sponsorship_save',
    'kicklive_sponsorship_set_status',
    'kicklive_sponsor_reserve_asset',
    'kicklive_sponsor_attach_asset',
    'kicklive_sponsorship_expire_due',
    'kicklive_sponsorship_diagnostics',
    'kicklive_sponsorship_admin_list',
    'kicklive_sponsorship_explain',
    'kicklive_sponsorship_status_transitions',
    'kicklive_asset_url_for_asset'
  ];
  names text[];
begin
  select array_agg(distinct p.proname) into names
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname like any (array['kicklive_sponsor%', 'kicklive_sponsorship%', 'kicklive_asset_url_for_asset']);
  foreach k in array expected loop
    if not (k = any (names)) then
      raise exception 'kicklive migration verification failed: function % is missing', k;
    end if;
  end loop;
  -- The `touch` function is not in the pattern above, and this is the exact mistake the Phase 7 grant loop
  -- was written to avoid: a name the LIKE cannot reach. Assert it rather than trusting the glob.
  if not exists (select 1 from pg_proc p join pg_namespace nn on nn.oid = p.pronamespace
                   where nn.nspname = 'public' and p.proname = 'kicklive_sponsorship_touch_epoch') then
    raise exception 'kicklive migration verification failed: the epoch writer is missing, so no cache could be invalidated';
  end if;

  -- RLS on every new table, and no client privilege on any of them.
  select count(1) into n from pg_class c join pg_namespace nn on nn.oid = c.relnamespace
   where nn.nspname = 'public' and c.relname in ('sponsors','sponsorship_packages','sponsorships','sponsorship_status_transitions','sponsorship_config')
     and c.relrowsecurity;
  if n <> 5 then
    raise exception 'kicklive migration verification failed: % of 5 sponsorship tables have RLS enabled', n;
  end if;
  if exists (
    select 1 from information_schema.role_table_grants g
     where g.table_schema = 'public'
       and g.table_name in ('sponsors','sponsorship_packages','sponsorships','sponsorship_status_transitions','sponsorship_config')
       and g.grantee in ('anon','authenticated')
  ) then
    raise exception 'kicklive migration verification failed: a client role holds a table privilege on a sponsorship table';
  end if;

  -- The public surface is exactly three functions: the band for a target, the epoch, and the rate card. If a
  -- fourth one day answers `anon`, that is a review, not a refactor — the count is asserted rather than
  -- enumerated because a list of names here is a second place to remember them, and the grants loop above is
  -- where they are actually decided.
  select count(1) into n from pg_proc p join pg_namespace nn on nn.oid = p.pronamespace
   where nn.nspname = 'public' and public.kicklive_has_grant('anon', p.oid::regprocedure::text, 'X')
     and p.proname like 'kicklive_sponsor%';
  if n <> 3 then
    raise exception 'kicklive migration verification failed: anon may execute % sponsorship function(s), expected 3 (the read, the epoch and the rate card)', n;
  end if;

  -- And the shape of the staff grant, stated as the two facts that matter rather than as a count: an
  -- authenticated caller can reach the writers (so `is_admin()` has a subject to judge), and cannot reach the
  -- cache-version writer or the private-object helper at all.
  if not public.kicklive_has_grant('authenticated', 'public.kicklive_sponsor_save(jsonb)', 'X') then
    raise exception 'kicklive migration verification failed: the staff surface is not executable as `authenticated`, so every admin write would arrive with auth.uid() = NULL and be refused by its own is_admin() check';
  end if;
  if public.kicklive_has_grant('authenticated', 'public.kicklive_sponsorship_touch_epoch(boolean)', 'X') then
    raise exception 'kicklive migration verification failed: a client role may bump the sponsorship cache epoch directly';
  end if;
  if public.kicklive_has_grant('authenticated', 'public.kicklive_asset_url_for_asset(bigint)', 'X') then
    raise exception 'kicklive migration verification failed: a client role may trade an asset id for a stored key';
  end if;

  -- The seeded rate card, and the reason a count is checked rather than a name: this migration may be
  -- applied to a database where an operator has already renamed a package, and a label test would fail for
  -- the correct reason. Codes are the stable identity, so codes are what is asserted.
  select count(1) into n from public.sponsorship_packages p
   where p.code = any (array['title','main','match','team','award','media_partner']);
  if n <> 6 then
    raise exception 'kicklive migration verification failed: % of the 6 seeded packages are present', n;
  end if;

  -- The kind the whole media story depends on, and the CHECK that carries it.
  if not exists (
    select 1 from pg_constraint c join pg_namespace nn on nn.oid = c.connamespace
     where c.conname = 'media_assets_kind_check'
       and pg_get_constraintdef(c.oid) like '%sponsors%'
  ) then
    raise exception 'kicklive migration verification failed: media_assets still refuses the sponsors kind, so no logo could be stored';
  end if;

  -- The transitions table: a sponsor may be approved, and a sponsorship may not go from `archived` to
  -- anything. Read as exists(), so absence is the assertion.
  if not exists (select 1 from public.sponsorship_status_transitions t
                  where t.kind = 'sponsor' and t.from_status = 'pending' and t.to_status = 'approved') then
    raise exception 'kicklive migration verification failed: the approval arc is missing';
  end if;
  if exists (select 1 from public.sponsorship_status_transitions t where t.to_status = 'draft' and t.from_status = 'archived') then
    raise exception 'kicklive migration verification failed: an archived record may not be revived into a draft';
  end if;

  -- The singleton config row must exist with a readable epoch, or every cache check below is meaningless.
  select count(1) into n from public.sponsorship_config where id = 1;
  if n <> 1 then
    raise exception 'kicklive migration verification failed: sponsorship_config has no singleton row';
  end if;
end
$verify$;

commit;

